async fn announce_created_session_before_initial_message<C, F, T>(
    created_tx: mpsc::UnboundedSender<C>,
    created: C,
    initial_message: Option<F>,
) -> Option<vibex_core::VibexError>
where
    F: Future<Output = vibex_core::VibexResult<T>>,
{
    let _ = created_tx.send(created);
    match initial_message {
        Some(submission) => submission.await.err(),
        None => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TimelineRestoreError {
    PageSessionMismatch,
    PrefixIncomplete,
    PaginationStalled,
}

impl TimelineRestoreError {
    fn into_vibex_error(self) -> vibex_core::VibexError {
        let (code, message) = match self {
            Self::PageSessionMismatch => (
                "timeline_page_session_mismatch",
                "timeline page belongs to another session",
            ),
            Self::PrefixIncomplete => (
                "timeline_prefix_incomplete",
                "timeline restore did not start from the authoritative prefix",
            ),
            Self::PaginationStalled => (
                "timeline_pagination_stalled",
                "timeline pagination did not advance its authoritative cursor",
            ),
        };
        vibex_core::VibexError::storage(code, message)
    }
}

fn next_authoritative_timeline_cursor(
    expected_session_id: &VibexSessionId,
    after_sequence: i64,
    page: &TimelinePage,
) -> Result<Option<i64>, TimelineRestoreError> {
    if &page.session_id != expected_session_id {
        return Err(TimelineRestoreError::PageSessionMismatch);
    }
    if after_sequence == 0
        && (page.has_older || page.start_sequence.is_some_and(|sequence| sequence > 1))
    {
        return Err(TimelineRestoreError::PrefixIncomplete);
    }
    if !page.has_newer {
        return Ok(None);
    }
    page.end_sequence
        .filter(|end_sequence| *end_sequence > after_sequence)
        .map(Some)
        .ok_or(TimelineRestoreError::PaginationStalled)
}

async fn fetch_authoritative_timeline(
    runtime: Arc<DesktopRuntime>,
    session_id: VibexSessionId,
) -> vibex_core::VibexResult<Vec<vibex_core::TimelineItem>> {
    let mut items = Vec::new();
    let mut after_sequence = 0_i64;
    loop {
        let page = runtime
            .agent()
            .fetch_timeline(FetchTimelineRequest {
                session_id: session_id.clone(),
                after_sequence: Some(after_sequence),
                limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
            })
            .await?;
        let next_cursor = next_authoritative_timeline_cursor(&session_id, after_sequence, &page)
            .map_err(TimelineRestoreError::into_vibex_error)?;
        items.extend(page.items);
        let Some(next_cursor) = next_cursor else {
            return Ok(items);
        };
        after_sequence = next_cursor;
    }
}

async fn fetch_child_agent_session_snapshot(
    runtime: Arc<DesktopRuntime>,
    session_id: VibexSessionId,
) -> vibex_core::VibexResult<(AgentSession, Vec<vibex_core::TimelineItem>)> {
    let session = runtime.agent().manager().get_session(&session_id).await?;
    let items = fetch_authoritative_timeline(runtime, session_id).await?;
    Ok((session, items))
}

fn normalize_empty_preview_visibility(state: &mut DesktopUiStateV1) {
    if state.preview.layout.tabs.is_empty() {
        state.workbench.preview_visible = false;
    }
}

fn clear_remembered_workbench_layout(state: &mut DesktopUiStateV1) {
    let defaults = vibex_desktop_model::WorkbenchUiState::default();
    let editor_recovery = std::mem::take(&mut state.preview.editor_recovery);
    state.workbench.selected_file_path = None;
    state.workbench.selected_git_path = None;
    state.workbench.sidebar_visible = defaults.sidebar_visible;
    state.workbench.preview_visible = defaults.preview_visible;
    state.workbench.right_rail_visible = defaults.right_rail_visible;
    state.workbench.sidebar_width = defaults.sidebar_width;
    state.workbench.preview_width = defaults.preview_width;
    state.workbench.right_rail_width = defaults.right_rail_width;
    state.preview = vibex_desktop_model::PreviewUiState {
        editor_recovery,
        ..vibex_desktop_model::PreviewUiState::default()
    };
    state.terminal = vibex_desktop_model::TerminalUiState::default();
    state.right_rail = vibex_desktop_model::RightRailUiState::default();
    state.composer.terminal_ids.clear();
    state.terminal_tab_titles.clear();
    state.agent_tab_order.clear();
    state.agent_sort_strategy = AgentSortStrategy::default();
}

fn apply_layout_memory_preference(state: &mut DesktopUiStateV1) {
    if !state.workbench.remember_layout {
        clear_remembered_workbench_layout(state);
    }
}

