fn touch_session_view_lru(lru: &mut VecDeque<String>, key: &str) {
    lru.retain(|cached| cached != key);
    lru.push_back(key.to_string());
}

fn insert_bounded_session_view<T>(
    cache: &mut BTreeMap<String, T>,
    lru: &mut VecDeque<String>,
    key: String,
    entry: T,
    limit: usize,
    max_bytes: usize,
    weight: impl Fn(&T) -> usize,
) {
    let entry_bytes = weight(&entry);
    cache.remove(&key);
    lru.retain(|cached| cached != &key);
    if limit == 0 || entry_bytes > max_bytes {
        return;
    }
    cache.insert(key.clone(), entry);
    touch_session_view_lru(lru, &key);
    let mut total_bytes = cache
        .values()
        .map(&weight)
        .fold(0_usize, usize::saturating_add);
    while lru.len() > limit || total_bytes > max_bytes {
        let Some(evicted) = lru.pop_front() else {
            cache.clear();
            break;
        };
        if let Some(entry) = cache.remove(&evicted) {
            total_bytes = total_bytes.saturating_sub(weight(&entry));
        }
    }
}

fn insert_bounded_timeline_projection<T>(
    cache: &mut BTreeMap<String, (i64, T)>,
    key: String,
    sequence: i64,
    value: T,
    max_entries: usize,
    max_bytes: usize,
    weight: impl Fn(&T) -> usize,
) {
    if max_entries == 0 {
        cache.clear();
        return;
    }
    cache.insert(key.clone(), (sequence, value));
    loop {
        let total_bytes = cache
            .values()
            .map(|(_, value)| weight(value))
            .sum::<usize>();
        if cache.len() <= max_entries && total_bytes <= max_bytes {
            break;
        }
        let evicted = cache
            .iter()
            .filter(|(candidate, _)| candidate.as_str() != key)
            .max_by_key(|(_, (candidate_sequence, _))| candidate_sequence.abs_diff(sequence))
            .map(|(candidate, _)| candidate.clone());
        let Some(evicted) = evicted else {
            // One visible entry may itself exceed the byte budget. Retain it so
            // the active Markdown row does not allocate its source every frame.
            break;
        };
        cache.remove(&evicted);
    }
}

#[derive(Clone)]
struct TimelineMarkdownSourceSnapshot {
    source: Arc<str>,
    refreshed_at: Instant,
}

#[derive(Clone)]
struct AgentReasoningSummary {
    plain: Arc<str>,
    preview: Arc<str>,
    tooltip: Arc<str>,
    has_more: bool,
}

// Collapsed reasoning rows sit inside an animated GPUI subtree. Keep their
// parsed projection outside the render closure so shimmer repaints do not
// reparse the streaming Markdown source.
#[derive(Clone)]
struct TimelineReasoningSummarySnapshot {
    source_len: usize,
    source_ptr: usize,
    refreshed_at: Instant,
    summary: AgentReasoningSummary,
}

fn timeline_reasoning_summary_cached_at(
    cache: &mut BTreeMap<String, (i64, TimelineReasoningSummarySnapshot)>,
    key: String,
    sequence: i64,
    source: &str,
    allow_throttle: bool,
    now: Instant,
) -> AgentReasoningSummary {
    let source_ptr = source.as_ptr() as usize;
    if let Some((cached_sequence, snapshot)) = cache.get(&key)
        && *cached_sequence == sequence
        && snapshot.source_len == source.len()
        && snapshot.source_ptr == source_ptr
    {
        return snapshot.summary.clone();
    }

    if allow_throttle
        && let Some((_, snapshot)) = cache.get(&key)
        && source.len() > snapshot.source_len
        && source_ptr == snapshot.source_ptr
        && now.saturating_duration_since(snapshot.refreshed_at)
            < TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL
        && source.len().saturating_sub(snapshot.source_len)
            < TIMELINE_STREAMING_MARKDOWN_REFRESH_BYTES
    {
        return snapshot.summary.clone();
    }

    let (plain, _) = agent_markdown_summary(source);
    let plain: Arc<str> = Arc::from(plain);
    let preview: Arc<str> = Arc::from(reasoning_preview_text(&plain));
    let tooltip: Arc<str> = Arc::from(plain.trim());
    let summary = AgentReasoningSummary {
        has_more: plain.chars().count() > AGENT_THINKING_LABEL_MAX_CHARS,
        plain,
        preview,
        tooltip,
    };
    insert_bounded_timeline_projection(
        cache,
        key,
        sequence,
        TimelineReasoningSummarySnapshot {
            source_len: source.len(),
            source_ptr,
            refreshed_at: now,
            summary: summary.clone(),
        },
        TIMELINE_REASONING_SUMMARY_CACHE_LIMIT,
        TIMELINE_REASONING_SUMMARY_CACHE_BYTES,
        |snapshot| {
            snapshot
                .summary
                .plain
                .len()
                .saturating_add(snapshot.summary.preview.len())
                .saturating_add(snapshot.summary.tooltip.len())
        },
    );
    summary
}

#[cfg(test)]
fn timeline_reasoning_summary_cached(
    cache: &mut BTreeMap<String, (i64, TimelineReasoningSummarySnapshot)>,
    key: String,
    sequence: i64,
    source: &str,
) -> AgentReasoningSummary {
    timeline_reasoning_summary_cached_at(cache, key, sequence, source, false, Instant::now())
}

fn timeline_markdown_source_snapshot(
    cache: &mut BTreeMap<String, (i64, TimelineMarkdownSourceSnapshot)>,
    row: &TimelineRow,
    now: Instant,
    allow_throttle: bool,
) -> (Arc<str>, i64) {
    if let Some((sequence, snapshot)) = cache.get(&row.id) {
        if *sequence == row.last_sequence && snapshot.source.len() == row.body.len() {
            return (snapshot.source.clone(), *sequence);
        }
        if row.streaming && allow_throttle {
            let pending_bytes = row.body.len().abs_diff(snapshot.source.len());
            if now.saturating_duration_since(snapshot.refreshed_at)
                < TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL
                && pending_bytes < TIMELINE_STREAMING_MARKDOWN_REFRESH_BYTES
            {
                return (snapshot.source.clone(), *sequence);
            }
        }
    }

    let source: Arc<str> = Arc::from(row.body.as_str());
    insert_bounded_timeline_projection(
        cache,
        row.id.clone(),
        row.last_sequence,
        TimelineMarkdownSourceSnapshot {
            source: source.clone(),
            refreshed_at: now,
        },
        TIMELINE_MARKDOWN_SOURCE_CACHE_LIMIT,
        TIMELINE_MARKDOWN_SOURCE_CACHE_BYTES,
        |snapshot| snapshot.source.len(),
    );
    (source, row.last_sequence)
}

fn agent_timeline_poll_interval(base_ms: u64, idle_poll_count: u16) -> Duration {
    let base_ms = base_ms.max(1);
    let exponent = idle_poll_count
        .saturating_sub(AGENT_TIMELINE_IDLE_POLL_THRESHOLD)
        .min(8) as u32;
    let multiplier = 1_u64.checked_shl(exponent).unwrap_or(u64::MAX);
    Duration::from_millis(
        base_ms
            .saturating_mul(multiplier)
            .min(AGENT_TIMELINE_IDLE_POLL_MAX_MS.max(base_ms)),
    )
}

fn agent_turn_completion_is_active(
    current_generation: u64,
    turn_generation: u64,
    selected_session_id: Option<&VibexSessionId>,
    turn_session_id: &VibexSessionId,
) -> bool {
    current_generation == turn_generation && selected_session_id == Some(turn_session_id)
}

fn composer_submission_status_is_actionable(status: MessageSubmissionStatus) -> bool {
    matches!(
        status,
        MessageSubmissionStatus::Failed | MessageSubmissionStatus::Cancelled
    )
}

/// A submission whose prompt already reached the provider and then failed in
/// the turn itself (retry exhaustion, terminal provider error, abnormal stop)
/// records `dispatched_at_ms`. That failure is owned by the timeline — error
/// items plus auto-continue — so it must not surface as a "message was not
/// sent" composer bar.
fn composer_submission_failure_reached_provider(state: &MessageSubmissionState) -> bool {
    state.status == MessageSubmissionStatus::Failed && state.dispatched_at_ms.is_some()
}

fn ambiguous_message_submission_notice() -> &'static str {
    locale::text(
        "There was a problem sending your message. Please try again shortly.",
        "消息发送遇到异常，请稍后再试。",
        "訊息傳送遇到異常，請稍後再試。",
    )
}

