fn agent_projection_should_repaint(active_tab: &str, changed: bool) -> bool {
    changed && active_tab == "agent"
}

fn should_defer_timeline_streaming_work(active_tab: &str, new_session_open: bool) -> bool {
    active_tab != "agent" || new_session_open
}

fn timeline_live_event_is_streaming_only(event: &TimelineLiveEvent) -> bool {
    if !timeline_live_event_is_well_formed(event) {
        return false;
    }
    match &event.item.payload {
        TimelinePayload::AgentMessageDelta(_) => true,
        TimelinePayload::Reasoning(reasoning) => !reasoning.is_final,
        _ => false,
    }
}

fn timeline_batch_requires_auto_continue_refresh(events: &[TimelineLiveEvent]) -> bool {
    events.iter().any(|event| {
        if !timeline_live_event_is_well_formed(event) {
            return false;
        }
        match &event.item.payload {
            // Non-final reasoning arrives while the provider is still running.
            // The authoritative idle/error snapshot refreshes the completion
            // status once the turn settles, without scanning the history for
            // every thought chunk. Agent-message deltas remain refreshable
            // because a trailing answer delta can change the latest outcome.
            TimelinePayload::AgentMessageDelta(_) => true,
            TimelinePayload::Reasoning(reasoning) => reasoning.is_final,
            _ => true,
        }
    })
}

/// Session snapshots also carry the latest timeline timestamp. That timestamp
/// changes for every streamed item, but it does not change the sidebar shape.
/// Keep the comparison focused on fields that can affect the sidebar so a
/// hidden workbench does not repaint for every reasoning chunk.
fn session_snapshot_sidebar_changed(previous: Option<&AgentSession>, next: &AgentSession) -> bool {
    let Some(previous) = previous else {
        return true;
    };
    previous.id != next.id
        || previous.title != next.title
        || previous.project_id != next.project_id
        || previous.workspace_id != next.workspace_id
        || previous.workspace_root != next.workspace_root
        || previous.workspace_mode != next.workspace_mode
        || previous.agent_id != next.agent_id
        || previous.state != next.state
        || previous.created_at_ms != next.created_at_ms
        || previous.archived_at_ms != next.archived_at_ms
        || previous.deleted_at_ms != next.deleted_at_ms
}

fn session_update_should_repaint(
    active_tab: &str,
    new_session_open: bool,
    snapshot_changed: bool,
    sidebar_changed: bool,
) -> bool {
    sidebar_changed
        || (!should_defer_timeline_streaming_work(active_tab, new_session_open) && snapshot_changed)
}

fn timeline_batch_should_repaint(
    active_tab: &str,
    unread_changed: bool,
    timeline_changed: bool,
    needs_refetch: bool,
) -> bool {
    unread_changed || agent_projection_should_repaint(active_tab, timeline_changed || needs_refetch)
}

fn timeline_virtual_rows_need_rebuild(turn_count: usize, row_size_count: usize) -> bool {
    turn_count != row_size_count
}

/// Position lookup for `TimelineModel::items` keyed by item id.
///
/// Row/turn renderers resolve payloads from item ids on every frame; a linear
/// scan over the whole timeline turns that into quadratic work once a session
/// accumulates thousands of items, which is exactly when scrolling must stay
/// smooth. The index is rebuilt lazily whenever the timeline identity changes.
#[derive(Default)]
struct TimelineItemIndex {
    session_id: Option<VibexSessionId>,
    revision: u64,
    item_count: usize,
    end_sequence: Option<i64>,
    positions: HashMap<String, usize>,
}

struct ChildAgentTimelineState {
    session: Option<AgentSession>,
    timeline: TimelineModel,
    loaded: bool,
    loading: bool,
    error: Option<String>,
    load_generation: u64,
}

impl ChildAgentTimelineState {
    fn new(session_id: VibexSessionId) -> Self {
        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(session_id, std::iter::empty());
        Self {
            session: None,
            timeline,
            loaded: false,
            loading: false,
            error: None,
            load_generation: 0,
        }
    }
}

#[derive(Clone)]
struct ChildAgentTimelineRowProjection {
    row: TimelineRow,
    delegation: Option<TimelineDelegationProjection>,
}

struct ChildAgentTimelineSnapshot {
    loading: bool,
    loaded: bool,
    error: Option<String>,
    rows: Vec<ChildAgentTimelineRowProjection>,
    turns: Vec<TimelineConversationTurn>,
}

impl TimelineItemIndex {
    fn is_current_for(&self, timeline: &TimelineModel) -> bool {
        self.session_id.as_ref() == timeline.session_id.as_ref()
            && self.revision == timeline.revision
            && self.item_count == timeline.items.len()
            && self.end_sequence == timeline.authoritative_end_sequence
    }

    fn rebuild(&mut self, timeline: &TimelineModel) {
        self.session_id = timeline.session_id.clone();
        self.revision = timeline.revision;
        self.item_count = timeline.items.len();
        self.end_sequence = timeline.authoritative_end_sequence;
        self.positions.clear();
        self.positions.reserve(timeline.items.len());
        // Items are ordered by sequence, so a later write always wins the id.
        for (position, item) in timeline.items.iter().enumerate() {
            self.positions.insert(item.id.to_string(), position);
        }
    }

    fn sync(&mut self, timeline: &TimelineModel) {
        if self.is_current_for(timeline) {
            return;
        }

        let append_only = self.session_id.as_ref() == timeline.session_id.as_ref()
            && self.item_count < timeline.items.len()
            && (self.item_count == 0
                || timeline.items.get(self.item_count - 1).is_some_and(|item| {
                    Some(item.sequence) == self.end_sequence
                        && self.positions.get(item.id.as_str()) == Some(&(self.item_count - 1))
                }));
        if !append_only {
            self.rebuild(timeline);
            return;
        }

        self.positions
            .reserve(timeline.items.len().saturating_sub(self.item_count));
        for (position, item) in timeline.items.iter().enumerate().skip(self.item_count) {
            self.positions.insert(item.id.to_string(), position);
        }
        self.revision = timeline.revision;
        self.item_count = timeline.items.len();
        self.end_sequence = timeline.authoritative_end_sequence;
    }

    fn invalidate(&mut self) {
        *self = Self::default();
    }
}

#[derive(Clone, Copy, Default)]
struct ConversationTurnsSummary {
    has_incomplete_turn: bool,
    has_pending_permission: bool,
}

impl ConversationTurnsSummary {
    fn from_turns<T>(turns: &[T]) -> Self
    where
        T: std::borrow::Borrow<TimelineConversationTurn>,
    {
        Self {
            has_incomplete_turn: turns.iter().any(|turn| !turn.borrow().complete),
            has_pending_permission: turns.iter().any(|turn| turn.borrow().pending_permission),
        }
    }
}

struct AgentSessionViewCacheEntry {
    estimated_resident_bytes: usize,
    timeline: TimelineModel,
    runtime_selection: Option<AgentSessionRuntimeSelectionState>,
    token_usage: Option<AgentTokenUsage>,
    timeline_follow: TimelineFollowState,
    timeline_scroll: VirtualListScrollHandle,
    timeline_row_sizes: Rc<Vec<Size<gpui::Pixels>>>,
    timeline_measured_turn_heights: BTreeMap<String, f32>,
    timeline_measured_turn_layout_signatures: BTreeMap<String, u64>,
    timeline_estimated_turn_heights: BTreeMap<String, (u64, f32)>,
    conversation_turns_cache: Rc<Vec<Rc<TimelineConversationTurn>>>,
    conversation_turns_cache_key: Option<ConversationTurnsCacheKey>,
    conversation_turns_summary: ConversationTurnsSummary,
    streaming_row_state: Option<StreamingRowStateCache>,
    timeline_layout_width: Option<f32>,
    content_width: SessionContentWidthMode,
    collapsed_timeline_rows: BTreeSet<String>,
    reasoning_expansion: BTreeMap<String, bool>,
    timeline_process_expansion: BTreeMap<String, bool>,
    timeline_command_expansion: BTreeMap<String, bool>,
    timeline_file_changes_expansion: BTreeMap<String, bool>,
}

impl AgentSessionViewCacheEntry {
    fn calculate_estimated_resident_bytes(&self) -> usize {
        timeline_items_resident_bytes(&self.timeline.items)
            .saturating_add(
                self.conversation_turns_cache
                    .iter()
                    .map(|turn| timeline_conversation_turn_resident_bytes(turn))
                    .fold(0_usize, usize::saturating_add),
            )
            .saturating_add(
                self.timeline_row_sizes.len() * std::mem::size_of::<Size<gpui::Pixels>>(),
            )
            .saturating_add(
                self.timeline_measured_turn_heights
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_measured_turn_layout_signatures
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_estimated_turn_heights
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.collapsed_timeline_rows
                    .iter()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.reasoning_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_process_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_command_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_file_changes_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
    }
}

fn timeline_items_resident_bytes(items: &[TimelineItem]) -> usize {
    items
        .iter()
        .map(timeline_item_resident_bytes)
        .fold(0_usize, usize::saturating_add)
}

fn timeline_item_resident_bytes(item: &TimelineItem) -> usize {
    let option_len = |value: &Option<String>| value.as_ref().map_or(0, String::len);
    let raw_extension_len = |extension: &Option<vibex_core::AgentEventRawExtension>| {
        extension.as_ref().map_or(0, |extension| {
            extension
                .content_blocks
                .iter()
                .map(|block| block.block_type.len().saturating_add(block.summary.len()))
                .chain(extension.raw_input.iter().map(String::len))
                .chain(extension.raw_output.iter().map(|output| output.text.len()))
                .chain(
                    extension
                        .locations
                        .iter()
                        .map(|location| location.uri.len()),
                )
                .chain(
                    extension
                        .meta
                        .iter()
                        .map(|(key, value)| key.len().saturating_add(value.len())),
                )
                .fold(0_usize, usize::saturating_add)
        })
    };
    let payload_bytes = match &item.payload {
        TimelinePayload::UserMessage(message) => message.text.len().saturating_add(
            message
                .attachments
                .iter()
                .map(|attachment| {
                    attachment
                        .label
                        .len()
                        .saturating_add(option_len(&attachment.mime_type))
                        .saturating_add(option_len(&attachment.uri))
                })
                .sum::<usize>(),
        ),
        TimelinePayload::AgentMessageDelta(delta) => delta.text_delta.len(),
        TimelinePayload::AgentMessage(message) => message.text.len(),
        TimelinePayload::Reasoning(reasoning) => reasoning.text.len(),
        TimelinePayload::Plan(plan) => plan.title.len().saturating_add(
            plan.steps
                .iter()
                .map(|step| step.title.len())
                .sum::<usize>(),
        ),
        TimelinePayload::ToolCall(tool) => tool
            .tool_call_id
            .len()
            .saturating_add(tool.tool_name.len())
            .saturating_add(tool.summary.len())
            .saturating_add(option_len(&tool.input_summary))
            .saturating_add(option_len(&tool.output_summary))
            .saturating_add(raw_extension_len(&tool.raw_extension)),
        TimelinePayload::Command(command) => command
            .command
            .len()
            .saturating_add(option_len(&command.cwd))
            .saturating_add(option_len(&command.output_summary))
            .saturating_add(raw_extension_len(&command.raw_extension)),
        TimelinePayload::FileOperation(operation) => operation
            .path
            .len()
            .saturating_add(operation.summary.len())
            .saturating_add(option_len(&operation.old_text))
            .saturating_add(option_len(&operation.new_text))
            .saturating_add(operation.patch.as_ref().map_or(0, |patch| patch.text.len()))
            .saturating_add(raw_extension_len(&operation.raw_extension)),
        TimelinePayload::WebSearch(search) => search
            .query
            .len()
            .saturating_add(option_len(&search.result_summary))
            .saturating_add(raw_extension_len(&search.raw_extension)),
        TimelinePayload::TodoUpdate(todo) => todo
            .title
            .len()
            .saturating_add(
                todo.items
                    .iter()
                    .map(|item| item.title.len())
                    .sum::<usize>(),
            )
            .saturating_add(raw_extension_len(&todo.raw_extension)),
        TimelinePayload::Collaboration(collaboration) => collaboration
            .action
            .len()
            .saturating_add(collaboration.summary.len())
            .saturating_add(option_len(&collaboration.agent_label))
            .saturating_add(raw_extension_len(&collaboration.raw_extension)),
        TimelinePayload::ImageGeneration(image) => image
            .summary
            .len()
            .saturating_add(option_len(&image.mime_type))
            .saturating_add(option_len(&image.image_reference))
            .saturating_add(raw_extension_len(&image.raw_extension)),
        TimelinePayload::GitNotice(notice) => notice.summary.len(),
        TimelinePayload::SystemNotice(notice) => notice.message.len(),
        TimelinePayload::PermissionRequest(request) => request
            .id
            .as_str()
            .len()
            .saturating_add(request.session_id.as_str().len())
            .saturating_add(
                request
                    .project_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(
                request
                    .workspace_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(option_len(&request.provider_request_id))
            .saturating_add(request.title.len())
            .saturating_add(
                request
                    .details
                    .iter()
                    .map(|detail| detail.label.len().saturating_add(detail.value.len()))
                    .sum::<usize>(),
            ),
        TimelinePayload::PermissionResolution(resolution) => resolution
            .request_id
            .as_str()
            .len()
            .saturating_add(resolution.session_id.as_str().len())
            .saturating_add(
                resolution
                    .responder_device_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(option_len(&resolution.provider_resolution_id))
            .saturating_add(option_len(&resolution.note)),
        TimelinePayload::ElicitationRequest(request) => request
            .id
            .as_str()
            .len()
            .saturating_add(request.session_id.as_str().len())
            .saturating_add(option_len(&request.provider_request_id))
            .saturating_add(option_len(&request.tool_call_id))
            .saturating_add(request.message.len())
            .saturating_add(option_len(&request.title))
            .saturating_add(option_len(&request.description))
            .saturating_add(
                request
                    .fields
                    .iter()
                    .map(|field| {
                        field
                            .id
                            .len()
                            .saturating_add(field.title.len())
                            .saturating_add(option_len(&field.description))
                            .saturating_add(elicitation_field_kind_resident_bytes(&field.kind))
                    })
                    .sum::<usize>(),
            ),
        TimelinePayload::ElicitationResolution(resolution) => resolution
            .request_id
            .as_str()
            .len()
            .saturating_add(resolution.session_id.as_str().len())
            .saturating_add(
                resolution
                    .answers
                    .iter()
                    .map(|(field_id, answer)| {
                        field_id
                            .len()
                            .saturating_add(elicitation_answer_resident_bytes(answer))
                    })
                    .sum::<usize>(),
            )
            .saturating_add(
                resolution
                    .responder_device_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            ),
        TimelinePayload::Retry(retry) => retry
            .reason
            .as_ref()
            .map_or(0, String::len)
            .saturating_add(retry.attempt.map_or(0, |value| value.to_string().len()))
            .saturating_add(
                retry
                    .max_attempts
                    .map_or(0, |value| value.to_string().len()),
            ),
        TimelinePayload::Error(error) => error.code.len().saturating_add(error.message.len()),
    };
    std::mem::size_of::<TimelineItem>()
        .saturating_add(item.id.as_str().len())
        .saturating_add(item.session_id.as_str().len())
        .saturating_add(
            item.correlation_id
                .as_ref()
                .map_or(0, |id| id.as_str().len()),
        )
        .saturating_add(option_len(&item.provider_correlation_id))
        .saturating_add(
            item.execution_attribution
                .as_ref()
                .map_or(0, |attribution| {
                    attribution
                        .agent_label
                        .len()
                        .saturating_add(attribution.auth_source_label.len())
                        .saturating_add(attribution.model_label.len())
                }),
        )
        .saturating_add(payload_bytes)
}

fn elicitation_field_kind_resident_bytes(kind: &ElicitationFieldKind) -> usize {
    let option_string_len = |value: &Option<String>| value.as_ref().map_or(0, String::len);
    let option_bytes = |options: &[vibex_core::ElicitationOption]| {
        options
            .iter()
            .map(|option| {
                option
                    .value
                    .len()
                    .saturating_add(option.title.len())
                    .saturating_add(option_string_len(&option.description))
            })
            .sum::<usize>()
    };
    match kind {
        ElicitationFieldKind::Text {
            pattern,
            default,
            options,
            ..
        } => option_string_len(pattern)
            .saturating_add(option_string_len(default))
            .saturating_add(option_bytes(options)),
        ElicitationFieldKind::Number {
            minimum,
            maximum,
            default,
        } => option_string_len(minimum)
            .saturating_add(option_string_len(maximum))
            .saturating_add(option_string_len(default)),
        ElicitationFieldKind::Integer { .. } => 0,
        ElicitationFieldKind::Boolean { .. } => 0,
        ElicitationFieldKind::MultiSelect {
            options, default, ..
        } => default
            .iter()
            .map(String::len)
            .sum::<usize>()
            .saturating_add(option_bytes(options)),
        ElicitationFieldKind::Unsupported { schema_type } => schema_type.len(),
    }
}

fn elicitation_answer_resident_bytes(answer: &vibex_core::ElicitationAnswerValue) -> usize {
    match answer {
        vibex_core::ElicitationAnswerValue::String(value)
        | vibex_core::ElicitationAnswerValue::Number(value) => value.len(),
        vibex_core::ElicitationAnswerValue::Integer(_)
        | vibex_core::ElicitationAnswerValue::Boolean(_) => 0,
        vibex_core::ElicitationAnswerValue::StringArray(values) => {
            values.iter().map(String::len).sum()
        }
    }
}

fn timeline_conversation_turn_resident_bytes(turn: &TimelineConversationTurn) -> usize {
    let row_bytes = |row: &TimelineRow| {
        row.id
            .len()
            .saturating_add(row.item_ids.iter().map(String::len).sum::<usize>())
            .saturating_add(row.turn_id.as_ref().map_or(0, String::len))
            .saturating_add(row.title.len())
            .saturating_add(row.body.len())
            .saturating_add(row.runtime_attribution.as_ref().map_or(0, String::len))
            .saturating_add(row.file_path.as_ref().map_or(0, String::len))
    };
    turn.id
        .len()
        .saturating_add(turn.runtime_attribution.as_ref().map_or(0, String::len))
        .saturating_add(turn.live_status.as_ref().map_or(0, String::len))
        .saturating_add(turn.user_row.as_ref().map_or(0, row_bytes))
        .saturating_add(
            turn.process_rows
                .iter()
                .map(row_bytes)
                .fold(0_usize, usize::saturating_add),
        )
        .saturating_add(turn.conclusion_row.as_ref().map_or(0, row_bytes))
        .saturating_add(
            turn.process_activity_groups
                .iter()
                .map(|group| group.id.len())
                .sum::<usize>(),
        )
        .saturating_add(
            turn.process_activity_groups_with_commands
                .iter()
                .chain(turn.process_activity_groups_with_file_operations.iter())
                .chain(
                    turn.process_activity_groups_with_commands_and_file_operations
                        .iter(),
                )
                .map(|group| group.id.len())
                .sum::<usize>(),
        )
}

fn timeline_process_activity_groups_for_display(
    turn: &TimelineConversationTurn,
    enhanced_command_display: bool,
    enhanced_file_operation_display: bool,
) -> &[TimelineProcessActivityGroup] {
    match (enhanced_command_display, enhanced_file_operation_display) {
        (true, true) => &turn.process_activity_groups,
        (false, true) => &turn.process_activity_groups_with_commands,
        (true, false) => &turn.process_activity_groups_with_file_operations,
        (false, false) => &turn.process_activity_groups_with_commands_and_file_operations,
    }
}

struct SidebarProjectionCache {
    revision: u64,
    groups: Rc<Vec<SidebarProjectProjection>>,
}

/// Inputs that `conversation_turns` depends on. Timeline identity/content fields
/// also let the cache prove that a change was append-only before reusing its
/// completed prefix.
#[derive(Clone, PartialEq, Eq)]
struct ConversationTurnsCacheKey {
    session_id: Option<VibexSessionId>,
    timeline_revision: u64,
    item_count: usize,
    end_sequence: Option<i64>,
    session_state: Option<AgentSessionState>,
    agent_turn_pending: bool,
    pending_edit: Option<(VibexSessionId, i64, i64)>,
    optimistic_message: Option<(VibexSessionId, String, i64)>,
    reasoning_display_mode: ReasoningDisplayMode,
}

fn conversation_turn_start_index(
    turn: &TimelineConversationTurn,
    items: &[TimelineItem],
) -> Option<usize> {
    if let Some(sequence) = turn.user_row.as_ref().map(|row| row.first_sequence) {
        return items
            .binary_search_by_key(&sequence, |item| item.sequence)
            .ok();
    }

    if let Some(item_id) = turn.id.strip_prefix("turn:continuation:") {
        return items.iter().position(|item| item.id.as_str() == item_id);
    }

    let sequence = turn
        .process_rows
        .iter()
        .chain(turn.conclusion_row.iter())
        .map(|row| row.first_sequence)
        .min()?;
    items
        .binary_search_by_key(&sequence, |item| item.sequence)
        .ok()
}

/// Rebuild only the final real turn after an append-only timeline update. The
/// prefix is shared by `Rc`, so a GPUI frame holding the previous projection
/// cannot force a deep clone of the whole conversation.
fn refresh_conversation_turns_cache_incrementally(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    previous_key: &ConversationTurnsCacheKey,
    next_key: &ConversationTurnsCacheKey,
    timeline: &TimelineModel,
) -> bool {
    if previous_key.session_id != next_key.session_id
        || next_key.session_id != timeline.session_id
        || previous_key.reasoning_display_mode != next_key.reasoning_display_mode
        || previous_key.pending_edit.is_some()
        || next_key.pending_edit.is_some()
        || previous_key.optimistic_message.is_some()
        || next_key.optimistic_message.is_some()
        || previous_key.item_count > next_key.item_count
        || next_key.item_count != timeline.items.len()
    {
        return false;
    }

    let append_only = if previous_key.item_count < next_key.item_count {
        previous_key.item_count > 0
            && previous_key.end_sequence
                == timeline
                    .items
                    .get(previous_key.item_count - 1)
                    .map(|item| item.sequence)
    } else {
        previous_key.item_count == next_key.item_count
            && previous_key.timeline_revision == next_key.timeline_revision
    };
    if !append_only || cache.is_empty() {
        return false;
    }

    let Some((turn_index, start_index)) =
        cache.iter().enumerate().rev().find_map(|(index, turn)| {
            conversation_turn_start_index(turn, &timeline.items).map(|start| (index, start))
        })
    else {
        return false;
    };
    let suffix = timeline_conversation_turns_with_reasoning_mode(
        &timeline.items[start_index..],
        next_key.session_state,
        next_key.agent_turn_pending,
        next_key.reasoning_display_mode,
    );
    let Some(first_suffix) = suffix.first() else {
        return false;
    };
    if first_suffix.id != cache[turn_index].id {
        return false;
    }

    let mut turns = cache[..turn_index].to_vec();
    turns.extend(suffix.into_iter().map(Rc::new));
    *cache = Rc::new(turns);
    true
}

struct AgentStreamingDeltaUpdate {
    item_id: String,
    sequence: i64,
    timestamp_ms: i64,
    text: String,
    conclusion: bool,
    runtime_attribution: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StreamingRowStateCache {
    turn_id: String,
    row_id: String,
    body_len: usize,
}

struct AgentStreamingCacheUpdate {
    turn_id: String,
    row_id: String,
    previous_body_len: usize,
    body_len: usize,
    output_char_delta: usize,
}

fn timeline_item_runtime_attribution(item: &TimelineItem) -> Option<String> {
    item.execution_attribution.as_ref().map(|attribution| {
        format!(
            "{} · {} · {}",
            attribution.agent_label, attribution.auth_source_label, attribution.model_label
        )
    })
}

fn timeline_live_event_is_well_formed(event: &TimelineLiveEvent) -> bool {
    event.sequence == event.item.sequence && event.session_id == event.item.session_id
}

fn timeline_live_event_updates_sidebar_timestamp(event: &TimelineLiveEvent) -> bool {
    if !timeline_live_event_is_well_formed(event) {
        return false;
    }
    match &event.item.payload {
        // Streaming deltas are presentation buffers. Updating the sidebar's
        // sort key for every chunk makes unrelated sessions repaint while the
        // active Agent is thinking or writing.
        TimelinePayload::AgentMessageDelta(_) => false,
        TimelinePayload::Reasoning(reasoning) => reasoning.is_final,
        _ => true,
    }
}

fn agent_streaming_delta_updates(
    events: &[TimelineLiveEvent],
) -> Option<Vec<AgentStreamingDeltaUpdate>> {
    let mut updates = Vec::with_capacity(events.len());
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            return None;
        }
        let TimelinePayload::AgentMessageDelta(delta) = &event.item.payload else {
            return None;
        };
        if delta.text_delta.contains("Reconnecting... ") {
            return None;
        }
        updates.push(AgentStreamingDeltaUpdate {
            item_id: event.item.id.to_string(),
            sequence: event.sequence,
            timestamp_ms: event.item.timestamp_ms,
            text: delta.text_delta.clone(),
            conclusion: delta.phase == Some(AgentMessagePhase::FinalAnswer),
            runtime_attribution: timeline_item_runtime_attribution(&event.item),
        });
    }
    updates
        .windows(2)
        .all(|pair| {
            pair[1].sequence == pair[0].sequence.saturating_add(1)
                && pair[1].conclusion == pair[0].conclusion
        })
        .then_some(updates)
}

fn agent_text_append_batch(events: &[TimelineLiveEvent]) -> bool {
    !events.is_empty()
        && events.iter().all(|event| {
            matches!(
                &event.item.payload,
                TimelinePayload::AgentMessageDelta(_) | TimelinePayload::AgentMessage(_)
            )
        })
}

fn update_unread_agent_completions(
    unread_session_ids: &mut BTreeSet<String>,
    selected_session_id: Option<&VibexSessionId>,
    events: &[TimelineLiveEvent],
) -> bool {
    let previous_len = unread_session_ids.len();
    for event in events {
        if selected_session_id == Some(&event.session_id)
            || !timeline_live_event_is_well_formed(event)
        {
            continue;
        }
        if matches!(
            &event.item.payload,
            TimelinePayload::AgentMessage(message) if message.is_final
        ) {
            unread_session_ids.insert(event.session_id.as_str().to_string());
        }
    }
    unread_session_ids.len() != previous_len
}

fn mark_agent_session_read(
    unread_session_ids: &mut BTreeSet<String>,
    session_id: &VibexSessionId,
) -> bool {
    unread_session_ids.remove(session_id.as_str())
}

fn record_timeline_row_endpoint(item_ids: &mut Vec<String>, item_id: String) {
    match item_ids.len() {
        0 => item_ids.push(item_id),
        1 if item_ids[0] != item_id => item_ids.push(item_id),
        1 => {}
        _ if item_ids.last() != Some(&item_id) => {
            item_ids.truncate(2);
            item_ids[1] = item_id;
        }
        _ => {}
    }
}

fn append_agent_streaming_deltas_to_cache(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    state_cache: &mut Option<StreamingRowStateCache>,
    updates: &[AgentStreamingDeltaUpdate],
) -> Option<AgentStreamingCacheUpdate> {
    if updates.is_empty() {
        return None;
    }
    let last_turn = cache.last()?;
    let conclusion = updates.first()?.conclusion;
    let last_row = if conclusion {
        last_turn.conclusion_row.as_ref()?
    } else {
        last_turn.process_rows.last()?
    };
    if last_turn.complete
        || last_row.kind != TimelineRowKind::AgentMessage
        || !last_row.streaming
        || last_row.conclusion != conclusion
        || updates.iter().any(|update| update.conclusion != conclusion)
        || updates
            .iter()
            .any(|update| update.runtime_attribution != last_row.runtime_attribution)
        || updates
            .first()
            .is_none_or(|update| update.sequence != last_row.last_sequence.saturating_add(1))
        || updates
            .windows(2)
            .any(|pair| pair[1].sequence != pair[0].sequence.saturating_add(1))
    {
        return None;
    }

    let turn_id = last_turn.id.clone();
    let row_id = last_row.id.clone();
    let previous_body_len = last_row.body.len();
    let output_char_delta = updates
        .iter()
        .map(|update| update.text.chars().count())
        .sum();

    let turns = Rc::make_mut(cache);
    let turn = Rc::make_mut(turns.last_mut().expect("cache was checked above"));
    let body_len = {
        let row = if conclusion {
            turn.conclusion_row
                .as_mut()
                .expect("streaming conclusion row was checked above")
        } else {
            turn.process_rows
                .last_mut()
                .expect("streaming process row was checked above")
        };
        for update in updates {
            row.body.push_str(&update.text);
            record_timeline_row_endpoint(&mut row.item_ids, update.item_id.clone());
            row.last_sequence = update.sequence;
        }
        row.body.len()
    };
    turn.item_count = turn.item_count.saturating_add(updates.len());
    turn.ended_at_ms = updates.last().map(|update| update.timestamp_ms);
    for row in turn
        .user_row
        .iter_mut()
        .chain(turn.process_rows.iter_mut())
        .chain(turn.conclusion_row.iter_mut())
    {
        row.turn_item_count = turn.item_count;
    }
    *state_cache = Some(StreamingRowStateCache {
        turn_id: turn_id.clone(),
        row_id: row_id.clone(),
        body_len,
    });
    Some(AgentStreamingCacheUpdate {
        turn_id,
        row_id,
        previous_body_len,
        body_len,
        output_char_delta,
    })
}

/// Thought chunks arrive as individual timeline items, so a thinking stream
/// would otherwise reproject the whole in-flight turn once per chunk. Mirror
/// the agent-message streaming fast path: recognise a pure run of appended
/// non-final reasoning deltas so the cached turn can be extended in place.
struct AgentReasoningDeltaUpdate {
    item_id: String,
    sequence: i64,
    timestamp_ms: i64,
    text: String,
    runtime_attribution: Option<String>,
}

fn agent_reasoning_delta_updates(
    events: &[TimelineLiveEvent],
) -> Option<Vec<AgentReasoningDeltaUpdate>> {
    let mut updates = Vec::with_capacity(events.len());
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            return None;
        }
        let TimelinePayload::Reasoning(reasoning) = &event.item.payload else {
            return None;
        };
        if reasoning.is_final {
            return None;
        }
        updates.push(AgentReasoningDeltaUpdate {
            item_id: event.item.id.to_string(),
            sequence: event.sequence,
            timestamp_ms: event.item.timestamp_ms,
            text: reasoning.text.clone(),
            runtime_attribution: timeline_item_runtime_attribution(&event.item),
        });
    }
    updates
        .windows(2)
        .all(|pair| pair[1].sequence == pair[0].sequence.saturating_add(1))
        .then_some(updates)
}

fn append_agent_reasoning_deltas_to_cache(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    state_cache: &mut Option<StreamingRowStateCache>,
    reasoning_display_mode: ReasoningDisplayMode,
    previous_end_sequence: Option<i64>,
    updates: &[AgentReasoningDeltaUpdate],
) -> Option<AgentStreamingCacheUpdate> {
    let first = updates.first()?;
    let last_turn = cache.last()?;
    // `live_status` is only populated while the turn tail is a run of streaming
    // reasoning, which is exactly the state this append can extend.
    let live_status = last_turn.live_status.as_ref()?;
    if last_turn.complete
        || previous_end_sequence.is_none_or(|end| end.saturating_add(1) != first.sequence)
        || updates
            .windows(2)
            .any(|pair| pair[1].sequence != pair[0].sequence.saturating_add(1))
    {
        return None;
    }

    let turn_id = last_turn.id.clone();
    let timeline_row = (reasoning_display_mode == ReasoningDisplayMode::Timeline)
        .then(|| {
            last_turn.process_rows.last().filter(|row| {
                row.kind == TimelineRowKind::Reasoning
                    && row.streaming
                    && row.last_sequence.saturating_add(1) == first.sequence
                    && updates
                        .iter()
                        .all(|update| update.runtime_attribution == row.runtime_attribution)
            })
        })
        .flatten();
    if reasoning_display_mode == ReasoningDisplayMode::Timeline && timeline_row.is_none() {
        return None;
    }
    let row_id =
        timeline_row.map_or_else(|| format!("reasoning-live:{turn_id}"), |row| row.id.clone());
    let previous_body_len = timeline_row.map_or_else(|| live_status.len(), |row| row.body.len());
    let output_char_delta = updates
        .iter()
        .map(|update| update.text.chars().count())
        .sum();

    let turns = Rc::make_mut(cache);
    let turn = Rc::make_mut(turns.last_mut().expect("cache was checked above"));
    if let Some(live_status) = turn.live_status.as_mut() {
        for update in updates {
            live_status.push_str(&update.text);
        }
    }
    let mut body_len = turn.live_status.as_ref().map_or(0, String::len);
    if reasoning_display_mode == ReasoningDisplayMode::Timeline
        && let Some(row) = turn.process_rows.last_mut()
    {
        for update in updates {
            row.body.push_str(&update.text);
            record_timeline_row_endpoint(&mut row.item_ids, update.item_id.clone());
            row.last_sequence = update.sequence;
        }
        body_len = row.body.len();
    }
    turn.item_count = turn.item_count.saturating_add(updates.len());
    turn.ended_at_ms = updates.last().map(|update| update.timestamp_ms);
    for row in turn
        .user_row
        .iter_mut()
        .chain(turn.process_rows.iter_mut())
        .chain(turn.conclusion_row.iter_mut())
    {
        row.turn_item_count = turn.item_count;
    }
    *state_cache = Some(StreamingRowStateCache {
        turn_id: turn_id.clone(),
        row_id: row_id.clone(),
        body_len,
    });
    Some(AgentStreamingCacheUpdate {
        turn_id,
        row_id,
        previous_body_len,
        body_len,
        output_char_delta,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentAnswerAction {
    Copy,
    ScrollToUserMessage,
    Fork,
    Timestamp,
}

const AGENT_ANSWER_ACTION_ORDER: [AgentAnswerAction; 4] = [
    AgentAnswerAction::Copy,
    AgentAnswerAction::ScrollToUserMessage,
    AgentAnswerAction::Fork,
    AgentAnswerAction::Timestamp,
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UserMessageEditActionState {
    Hidden,
    Disabled,
    Enabled,
}

#[derive(Clone)]
struct InlineUserMessageEdit {
    turn_id: String,
    row_id: String,
    source_session_id: VibexSessionId,
    user_sequence: i64,
    expected_source_end_sequence: i64,
    attachments: Vec<InlineComposerAttachment>,
    geometry: ComposerGeometry,
}

impl InlineUserMessageEdit {
    fn matches(&self, row_id: &str, session_id: Option<&VibexSessionId>) -> bool {
        self.row_id == row_id && session_id == Some(&self.source_session_id)
    }
}

#[derive(Clone)]
struct PendingUserMessageEdit {
    source_session_id: VibexSessionId,
    user_sequence: i64,
    submitted_at_ms: i64,
    text: String,
    attachments: Vec<MessageAttachment>,
}

impl PendingUserMessageEdit {
    fn cache_key(&self) -> (VibexSessionId, i64, i64) {
        (
            self.source_session_id.clone(),
            self.user_sequence,
            self.submitted_at_ms,
        )
    }

    fn projected_items(&self, timeline: &TimelineModel) -> Option<Vec<TimelineItem>> {
        if timeline.session_id.as_ref() != Some(&self.source_session_id) {
            return None;
        }
        let mut items = timeline.items.clone();
        let user_item_index = items.iter().position(|item| {
            item.sequence == self.user_sequence
                && matches!(&item.payload, TimelinePayload::UserMessage(_))
        })?;
        let user_item = items.get_mut(user_item_index)?;
        let TimelinePayload::UserMessage(message) = &mut user_item.payload else {
            return None;
        };
        message.text.clone_from(&self.text);
        message.attachments.clone_from(&self.attachments);
        user_item.timestamp_ms = self.submitted_at_ms;
        items.truncate(user_item_index + 1);
        Some(items)
    }
}

/// Presentation-only user message retained until the authoritative timeline
/// receives the durable row. The backend remains the source of truth.
#[derive(Clone)]
struct OptimisticUserMessage {
    session_id: VibexSessionId,
    item_id: TimelineItemId,
    after_sequence: i64,
    submitted_at_ms: i64,
    text: String,
    attachments: Vec<MessageAttachment>,
}

impl OptimisticUserMessage {
    fn cache_key(&self) -> (VibexSessionId, String, i64) {
        (
            self.session_id.clone(),
            self.item_id.as_str().to_string(),
            self.submitted_at_ms,
        )
    }

    fn is_confirmed_by(&self, timeline: &TimelineModel) -> bool {
        timeline.session_id.as_ref() == Some(&self.session_id)
            && timeline.items.iter().any(|item| {
                item.sequence > self.after_sequence
                    && matches!(
                        &item.payload,
                        TimelinePayload::UserMessage(message)
                            if message.text.trim() == self.text.trim()
                                && message.attachments == self.attachments
                    )
            })
    }

    fn projected_items(&self, timeline: &TimelineModel) -> Option<Vec<TimelineItem>> {
        if timeline
            .session_id
            .as_ref()
            .is_some_and(|session_id| session_id != &self.session_id)
            || self.is_confirmed_by(timeline)
        {
            return None;
        }
        let mut items = timeline.items.clone();
        let payload = TimelinePayload::UserMessage(UserMessagePayload {
            text: self.text.clone(),
            attachments: self.attachments.clone(),
        });
        items.push(TimelineItem {
            id: self.item_id.clone(),
            session_id: self.session_id.clone(),
            sequence: items
                .last()
                .map(|item| item.sequence.saturating_add(1))
                .unwrap_or(1),
            timestamp_ms: self.submitted_at_ms,
            source: TimelineSource::User,
            kind: payload.kind(),
            correlation_id: None,
            provider_correlation_id: None,
            redaction_state: TimelineRedactionState::None,
            execution_attribution: None,
            payload,
        });
        Some(items)
    }
}

fn agent_answer_actions(has_timestamp: bool) -> impl Iterator<Item = AgentAnswerAction> {
    AGENT_ANSWER_ACTION_ORDER
        .into_iter()
        .filter(move |action| has_timestamp || !matches!(action, AgentAnswerAction::Timestamp))
}

fn user_message_edit_action_state(
    latest_user_message: bool,
    turn_complete: bool,
    needs_authoritative_refetch: bool,
    session_state: Option<AgentSessionState>,
    action_pending: bool,
) -> UserMessageEditActionState {
    if !latest_user_message {
        return UserMessageEditActionState::Hidden;
    }
    if turn_complete
        && !needs_authoritative_refetch
        && !action_pending
        && matches!(
            session_state,
            Some(AgentSessionState::Idle | AgentSessionState::Error)
        )
    {
        UserMessageEditActionState::Enabled
    } else {
        UserMessageEditActionState::Disabled
    }
}

fn timeline_distance_to_bottom(offset_y: f32, max_offset_y: f32) -> f32 {
    (max_offset_y + offset_y).max(0.0)
}

fn timeline_should_resume_follow_after_scroll_idle(
    scrolled_toward_bottom: bool,
    distance_to_bottom: f32,
    scrollbar_interaction_active: bool,
) -> bool {
    scrolled_toward_bottom
        && !scrollbar_interaction_active
        && distance_to_bottom <= AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX
}

fn timeline_should_show_bottom_control(
    scrollable: bool,
    following_bottom: bool,
    distance_to_bottom: f32,
    currently_visible: bool,
) -> bool {
    scrollable
        && !following_bottom
        && distance_to_bottom > AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX
        && (currently_visible
            || distance_to_bottom >= AGENT_TIMELINE_BOTTOM_CONTROL_REVEAL_THRESHOLD_PX)
}

fn timeline_should_auto_follow_content(
    following_bottom: bool,
    scroll_wheel_active: bool,
    scrollbar_interaction_active: bool,
    content_extent_changed: bool,
) -> bool {
    following_bottom
        && !scroll_wheel_active
        && !scrollbar_interaction_active
        && content_extent_changed
}

fn stable_streaming_timeline_height(
    previous_height: Option<f32>,
    measured_height: f32,
    preserve_streaming_extent: bool,
) -> f32 {
    if preserve_streaming_extent {
        previous_height
            .unwrap_or(measured_height)
            .max(measured_height)
    } else {
        measured_height
    }
}

fn stable_streaming_timeline_height_for_layout(
    previous_height: Option<f32>,
    measured_height: f32,
    preserve_streaming_extent: bool,
    previous_layout_signature: Option<u64>,
    current_layout_signature: Option<u64>,
) -> f32 {
    let preserve_streaming_extent = preserve_streaming_extent
        && current_layout_signature.is_some()
        && previous_layout_signature == current_layout_signature;
    stable_streaming_timeline_height(previous_height, measured_height, preserve_streaming_extent)
}

fn timeline_layout_width_changed(previous: Option<f32>, current: Option<f32>) -> bool {
    match (previous, current) {
        (Some(previous), Some(current)) => {
            (previous - current).abs() >= AGENT_TIMELINE_LAYOUT_WIDTH_EPSILON_PX
        }
        _ => true,
    }
}

fn timeline_turn_duration_end(turn_complete: bool, ended_at_ms: Option<i64>) -> Option<i64> {
    turn_complete.then_some(ended_at_ms).flatten()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentGenerationPhase {
    Preparing,
    Thinking,
    CallingTool,
    Generating,
    WaitingForApproval,
}

#[derive(Debug)]
struct AgentGenerationStats {
    turn_id: String,
    started_at_ms: i64,
    output_token_baseline: Option<u64>,
    estimated_output_chars: Option<usize>,
    compaction_count: Option<usize>,
    last_generated_tokens: Option<u64>,
    last_token_sample_at: Instant,
    tokens_per_second: Option<f32>,
}

impl AgentGenerationStats {
    fn new(
        turn_id: String,
        started_at_ms: i64,
        output_token_baseline: Option<u64>,
        compaction_count: usize,
    ) -> Self {
        Self {
            turn_id,
            started_at_ms,
            output_token_baseline,
            estimated_output_chars: None,
            compaction_count: Some(compaction_count),
            last_generated_tokens: None,
            last_token_sample_at: Instant::now(),
            tokens_per_second: None,
        }
    }
}

fn agent_generation_phase(turn: &TimelineConversationTurn) -> AgentGenerationPhase {
    if turn.pending_permission {
        return AgentGenerationPhase::WaitingForApproval;
    }

    let latest_streaming_row = turn
        .conclusion_row
        .iter()
        .chain(turn.process_rows.iter().rev())
        .find(|row| row.streaming);
    match latest_streaming_row.map(|row| row.kind) {
        Some(TimelineRowKind::AgentMessage) => AgentGenerationPhase::Generating,
        Some(
            TimelineRowKind::ToolCall
            | TimelineRowKind::Command
            | TimelineRowKind::FileOperation
            | TimelineRowKind::WebSearch
            | TimelineRowKind::Collaboration
            | TimelineRowKind::ImageGeneration,
        ) => AgentGenerationPhase::CallingTool,
        Some(TimelineRowKind::Reasoning) => AgentGenerationPhase::Thinking,
        Some(_) | None if turn.live_status.is_some() => AgentGenerationPhase::Thinking,
        Some(_) | None => AgentGenerationPhase::Preparing,
    }
}

fn agent_generation_phase_label(
    phase: AgentGenerationPhase,
    locale: locale::ResolvedLocale,
) -> &'static str {
    match (phase, locale) {
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::En) => "Preparing",
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::ZhCn) => "准备中",
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::ZhTw) => "準備中",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::En) => "Thinking",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::ZhCn) => "思考中",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::ZhTw) => "思考中",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::En) => "Calling tool",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::ZhCn) => "调用工具",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::ZhTw) => "呼叫工具",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::En) => "Generating",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::ZhCn) => "生成中",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::ZhTw) => "生成中",
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::En) => {
            "Waiting for approval"
        }
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::ZhCn) => "等待确认",
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::ZhTw) => "等待確認",
    }
}

fn agent_generation_tool_call_count(turn: &TimelineConversationTurn) -> usize {
    turn.process_rows
        .iter()
        .filter(|row| {
            matches!(
                row.kind,
                TimelineRowKind::ToolCall
                    | TimelineRowKind::Command
                    | TimelineRowKind::FileOperation
                    | TimelineRowKind::WebSearch
                    | TimelineRowKind::Collaboration
                    | TimelineRowKind::ImageGeneration
            )
        })
        .count()
}

fn agent_generation_compaction_count(
    turn: &TimelineConversationTurn,
    timeline_items: &[TimelineItem],
) -> usize {
    let Some((start_sequence, projected_end_sequence)) = timeline_turn_sequence_range(turn) else {
        return 0;
    };
    let end_sequence = if turn.complete {
        projected_end_sequence
    } else {
        timeline_items
            .last()
            .map_or(projected_end_sequence, |item| {
                projected_end_sequence.max(item.sequence)
            })
    };
    let start_index = timeline_items.partition_point(|item| item.sequence < start_sequence);
    let end_index = timeline_items.partition_point(|item| item.sequence <= end_sequence);
    timeline_items[start_index..end_index]
        .iter()
        .filter(|item| {
            matches!(
                &item.payload,
                TimelinePayload::SystemNotice(notice) if notice.is_context_compaction()
            )
        })
        .count()
}

fn timeline_turn_file_changes_cache_sequence(turn: &TimelineConversationTurn) -> i64 {
    turn.process_rows
        .iter()
        .chain(turn.conclusion_row.iter())
        .filter(|row| row.kind == TimelineRowKind::FileOperation)
        .map(|row| row.last_sequence)
        .max()
        .unwrap_or_default()
}

fn turn_file_changes_line_counts(summary: &TurnFileChangesSummary) -> Option<(usize, usize)> {
    summary
        .files
        .iter()
        .any(|file| file.has_line_counts)
        .then_some((
            summary.files.iter().map(|file| file.added_lines).sum(),
            summary.files.iter().map(|file| file.removed_lines).sum(),
        ))
}

fn estimated_agent_output_chars(turn: &TimelineConversationTurn) -> Option<usize> {
    // Reasoning deltas are model output too. In Timeline mode they stream into
    // `process_rows`; in LatestAtBottom mode streaming reasoning rows are
    // filtered out and the text only accumulates in `live_status`. The two
    // sources overlap, so `live_status` is counted only when no reasoning row
    // already carries the stream, otherwise the tail would be double-counted.
    let mut streaming_reasoning_row_present = false;
    let mut output_chars = 0usize;
    for row in turn.process_rows.iter().chain(turn.conclusion_row.iter()) {
        match row.kind {
            TimelineRowKind::AgentMessage => output_chars += row.body.chars().count(),
            TimelineRowKind::Reasoning => {
                streaming_reasoning_row_present |= row.streaming;
                output_chars += row.body.chars().count();
            }
            _ => {}
        }
    }
    if !streaming_reasoning_row_present && let Some(status) = turn.live_status.as_deref() {
        output_chars += status.chars().count();
    }
    (output_chars > 0).then_some(output_chars)
}

#[cfg(test)]
fn estimated_agent_output_tokens(turn: &TimelineConversationTurn) -> Option<u64> {
    estimated_agent_output_chars(turn)
        .map(|output_chars| (output_chars as u64).saturating_add(3) / 4)
}

#[cfg(test)]
fn agent_generation_output_tokens(
    turn: &TimelineConversationTurn,
    output_tokens: Option<u64>,
    output_token_baseline: Option<u64>,
) -> Option<u64> {
    let reported = match (output_tokens, output_token_baseline) {
        (Some(current), Some(baseline)) => {
            current.checked_sub(baseline).filter(|tokens| *tokens > 0)
        }
        (Some(current), None) if current > 0 => Some(current),
        _ => None,
    };
    reported.or_else(|| estimated_agent_output_tokens(turn))
}

fn agent_generation_token_rate(
    previous_tokens: Option<u64>,
    current_tokens: Option<u64>,
    elapsed: Duration,
) -> Option<f32> {
    let (Some(previous), Some(current)) = (previous_tokens, current_tokens) else {
        return None;
    };
    let elapsed_seconds = elapsed.as_secs_f32();
    (current > previous && elapsed_seconds > 0.0)
        .then_some((current - previous) as f32 / elapsed_seconds)
}

fn timeline_session_state_for_render(
    selected_session_id: Option<&VibexSessionId>,
    timeline_session_id: Option<&VibexSessionId>,
    agent_loading: bool,
    session_state: Option<AgentSessionState>,
) -> Option<AgentSessionState> {
    if agent_loading || selected_session_id != timeline_session_id {
        None
    } else {
        session_state
    }
}

fn timeline_turn_process_expanded(
    turn: &TimelineConversationTurn,
    explicit_expansion: Option<bool>,
) -> bool {
    explicit_expansion.unwrap_or(!turn.complete && timeline_turn_conclusion_row(turn).is_none())
}

fn timeline_turn_conclusion_row(turn: &TimelineConversationTurn) -> Option<&TimelineRow> {
    turn.conclusion_row
        .as_ref()
        .filter(|row| !row.body.trim().is_empty())
}

fn timeline_streaming_agent_row<'a>(
    turn: &'a TimelineConversationTurn,
    row_id: &str,
) -> Option<&'a TimelineRow> {
    turn.conclusion_row
        .iter()
        .chain(turn.process_rows.iter().rev())
        .find(|row| row.id == row_id && row.kind == TimelineRowKind::AgentMessage && row.streaming)
}

fn timeline_streaming_reasoning_row<'a>(
    turn: &'a TimelineConversationTurn,
    row_id: &str,
) -> Option<&'a TimelineRow> {
    turn.process_rows
        .iter()
        .rev()
        .find(|row| row.id == row_id && row.kind == TimelineRowKind::Reasoning && row.streaming)
}

fn streaming_timeline_row_body_len(
    turn: &TimelineConversationTurn,
    state: &StreamingRowStateCache,
) -> Option<usize> {
    if state.row_id == format!("reasoning-live:{}", turn.id) {
        return turn.live_status.as_ref().map(String::len);
    }
    timeline_streaming_agent_row(turn, &state.row_id)
        .or_else(|| timeline_streaming_reasoning_row(turn, &state.row_id))
        .map(|row| row.body.len())
}

fn show_agent_answer_actions(conversation_conclusion: bool, row: &TimelineRow) -> bool {
    conversation_conclusion && !row.streaming && !row.body.is_empty()
}

fn session_search_documents(items: &[TimelineItem]) -> Vec<SessionSearchDocument> {
    let timestamps = items
        .iter()
        .map(|item| (item.id.to_string(), item.timestamp_ms))
        .collect::<BTreeMap<_, _>>();
    let mut documents = Vec::new();
    for turn in timeline_conversation_turns(items, Some(AgentSessionState::Idle), false) {
        for row in turn
            .user_row
            .into_iter()
            .chain(turn.process_rows)
            .chain(turn.conclusion_row)
        {
            let text = session_search_row_text(&row);
            if text.is_empty() {
                continue;
            }
            let item_id = row.item_ids.last().cloned();
            let timestamp_ms = item_id
                .as_deref()
                .and_then(|id| timestamps.get(id).copied())
                .unwrap_or_default();
            documents.push(SessionSearchDocument {
                turn_id: turn.id.clone(),
                item_id,
                first_sequence: row.first_sequence,
                timestamp_ms,
                text,
            });
        }
    }
    documents
}

fn session_search_row_text(row: &TimelineRow) -> String {
    let title = row.title.trim();
    let body = row.body.trim();
    match (title.is_empty(), body.is_empty(), title == body) {
        (true, true, _) => String::new(),
        (false, true, _) | (false, false, true) => title.to_string(),
        (true, false, _) => body.to_string(),
        (false, false, false) => format!("{title} {body}"),
    }
}

fn normalized_session_search_query(query: &str) -> String {
    query
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

fn session_search_match_ranges_with_limit(
    text: &str,
    query: &str,
    limit: usize,
) -> Vec<Range<usize>> {
    if text.is_empty() || query.is_empty() || limit == 0 {
        return Vec::new();
    }

    let folded_query = query.to_lowercase();
    if folded_query.is_empty() {
        return Vec::new();
    }

    let mut folded_text = String::new();
    let mut character_ranges = Vec::new();
    for (original_start, character) in text.char_indices() {
        let folded_start = folded_text.len();
        folded_text.extend(character.to_lowercase());
        character_ranges.push((
            folded_start..folded_text.len(),
            original_start..original_start + character.len_utf8(),
        ));
    }

    let mut ranges: Vec<Range<usize>> = Vec::new();
    for (folded_start, _) in folded_text.match_indices(&folded_query).take(limit) {
        let folded_end = folded_start + folded_query.len();
        let first_character =
            character_ranges.partition_point(|(folded, _)| folded.end <= folded_start);
        let last_character =
            character_ranges.partition_point(|(folded, _)| folded.start < folded_end);
        if first_character >= character_ranges.len() || last_character == 0 {
            continue;
        }
        let next =
            character_ranges[first_character].1.start..character_ranges[last_character - 1].1.end;
        if let Some(last) = ranges.last_mut()
            && last.end >= next.start
        {
            last.end = last.end.max(next.end);
        } else {
            ranges.push(next);
        }
    }
    ranges
}

fn session_search_match_ranges(text: &str, query: &str) -> Vec<Range<usize>> {
    session_search_match_ranges_with_limit(text, query, usize::MAX)
}

fn session_search_excerpt(text: &str, normalized_query: &str) -> Option<String> {
    let compact = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.is_empty() {
        return None;
    }
    let match_range = session_search_match_ranges_with_limit(&compact, normalized_query, 1)
        .into_iter()
        .next()?;
    let match_char = compact[..match_range.start].chars().count();
    let query_chars = compact[match_range].chars().count();
    let chars = compact.chars().collect::<Vec<_>>();
    let context = SESSION_SEARCH_EXCERPT_MAX_CHARS.saturating_sub(query_chars) / 2;
    let start = match_char.saturating_sub(context);
    let end = (match_char + query_chars + context).min(chars.len());
    let mut excerpt = chars[start..end].iter().collect::<String>();
    if start > 0 {
        excerpt.insert_str(0, "...");
    }
    if end < chars.len() {
        excerpt.push_str("...");
    }
    Some(excerpt)
}

fn session_search_highlighted_text(
    text: String,
    query: &str,
    highlight: HighlightStyle,
) -> StyledText {
    let highlights = session_search_match_ranges(&text, query)
        .into_iter()
        .map(|range| (range, highlight));
    StyledText::new(text).with_highlights(highlights)
}

fn agent_turn_is_active(
    agent_turn_pending: bool,
    session_state: Option<AgentSessionState>,
) -> bool {
    agent_turn_pending
        || matches!(
            session_state,
            Some(AgentSessionState::Running | AgentSessionState::NeedsInput)
        )
}

fn reorder_composer_queue_message(
    queue: &mut Vec<ComposerQueueMessage>,
    message_id: u64,
    target_id: u64,
    after: bool,
) -> bool {
    if message_id == target_id {
        return false;
    }
    let Some(source_index) = queue.iter().position(|message| message.id == message_id) else {
        return false;
    };
    let Some(target_session_id) = queue
        .iter()
        .find(|message| message.id == target_id)
        .map(|message| message.session_id.clone())
    else {
        return false;
    };
    if queue[source_index].session_id != target_session_id {
        return false;
    }
    let message = queue.remove(source_index);
    let Some(target_index) = queue.iter().position(|queued| queued.id == target_id) else {
        queue.push(message);
        return false;
    };
    queue.insert(target_index + usize::from(after), message);
    true
}

fn promote_composer_queue_message(
    queue: &mut Vec<ComposerQueueMessage>,
    message_id: u64,
) -> Option<VibexSessionId> {
    let source_index = queue.iter().position(|message| message.id == message_id)?;
    let message = queue.remove(source_index);
    let session_id = message.session_id.clone();
    let insert_at = queue
        .iter()
        .position(|queued| queued.session_id == session_id)
        .unwrap_or(queue.len());
    queue.insert(insert_at, message);
    Some(session_id)
}

fn composer_queue_auto_send_enabled(
    manual_session_ids: &BTreeSet<String>,
    session_id: &VibexSessionId,
) -> bool {
    !manual_session_ids.contains(session_id.as_str())
}

fn composer_queue_dispatch_enabled(
    manual_session_ids: &BTreeSet<String>,
    session_id: &VibexSessionId,
    behavior: ComposerQueueDispatchBehavior,
) -> bool {
    matches!(
        behavior,
        ComposerQueueDispatchBehavior::ForceNext | ComposerQueueDispatchBehavior::AfterInterrupt
    ) || composer_queue_auto_send_enabled(manual_session_ids, session_id)
}

fn composer_queue_session_blocks_dispatch(
    behavior: ComposerQueueDispatchBehavior,
    local_turn_pending: bool,
    session_state: Option<AgentSessionState>,
) -> bool {
    let session_blocks = match behavior {
        ComposerQueueDispatchBehavior::AfterInterrupt => false,
        ComposerQueueDispatchBehavior::AfterCompletion => {
            matches!(session_state, Some(AgentSessionState::NeedsInput))
        }
        ComposerQueueDispatchBehavior::Automatic | ComposerQueueDispatchBehavior::ForceNext => {
            matches!(
                session_state,
                Some(AgentSessionState::Running | AgentSessionState::NeedsInput)
            )
        }
    };
    local_turn_pending || session_blocks
}

fn composer_queue_waits_for_continuation(
    behavior: ComposerQueueDispatchBehavior,
    session_state: Option<AgentSessionState>,
    latest_turn_ended_normally: Option<bool>,
) -> bool {
    matches!(
        behavior,
        ComposerQueueDispatchBehavior::Automatic | ComposerQueueDispatchBehavior::AfterCompletion
    ) && session_state.is_some_and(|state| {
        agent_session_turn_requires_continuation(state, latest_turn_ended_normally)
    })
}

fn auto_continue_should_start(
    enabled: bool,
    session_state: AgentSessionState,
    latest_turn_ended_normally: Option<bool>,
    session_turn_pending: bool,
    current_turn_paused: bool,
    handled_turn_updated_at_ms: Option<i64>,
    session_updated_at_ms: i64,
) -> bool {
    enabled
        && agent_session_turn_requires_continuation(session_state, latest_turn_ended_normally)
        && !session_turn_pending
        && !current_turn_paused
        && handled_turn_updated_at_ms != Some(session_updated_at_ms)
}

fn restored_auto_continue_session_ids(state: &SessionUiState) -> BTreeSet<String> {
    state
        .auto_continue_session_overrides
        .iter()
        .filter(|(_, enabled)| **enabled)
        .map(|(session_id, _)| session_id.clone())
        .collect()
}

fn auto_continue_countdown_label(locale: locale::ResolvedLocale, remaining_seconds: u8) -> String {
    match locale {
        locale::ResolvedLocale::En => format!("Continue ({remaining_seconds}s)"),
        locale::ResolvedLocale::ZhCn => format!("继续（{remaining_seconds} 秒）"),
        locale::ResolvedLocale::ZhTw => format!("繼續（{remaining_seconds} 秒）"),
    }
}

