    fn delete_session(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        if self
            .pending_session_deletion_ids
            .contains(session_id.as_str())
        {
            return;
        }
        let Some(runtime) = self.runtime.clone() else {
            return;
        };
        let session_id_set = BTreeSet::from([session_id.as_str().to_string()]);
        self.pending_session_deletion_ids
            .extend(session_id_set.iter().cloned());
        self.optimistically_remove_sessions(&session_id_set);
        self.queue_agent_ui_state();
        cx.notify();
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            runtime.agent().manager().delete_session(&session_id).await
        });
        self.finish_optimistic_session_deletion(generation, session_id_set, runner, cx);
    }

    fn confirm_delete_selected_sessions(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let count = self.sidebar_state.selected_ids.len();
        if count == 0 {
            return;
        }
        let strings = self.strings();
        let locale = self.resolved_locale();
        let entity = cx.weak_entity();
        window.open_dialog(cx, move |dialog, _, _| {
            let entity = entity.clone();
            dialog
                .title(sidebar_delete_sessions_title(locale, count))
                .child(sidebar_delete_sessions_description(locale, count))
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-batch-delete")
                                    .outline()
                                    .label(strings.sidebar_cancel),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("confirm-batch-delete")
                                    .danger()
                                    .label(strings.sidebar_delete),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let _ = entity.update(cx, |this, cx| this.delete_selected_sessions(cx));
                    true
                })
        });
    }

    fn delete_selected_sessions(&mut self, cx: &mut Context<Self>) {
        if self.sidebar_state.selected_ids.is_empty() {
            return;
        }
        let session_ids = self
            .sidebar_state
            .selected_ids
            .iter()
            .filter_map(|id| VibexSessionId::parse(id).ok())
            .collect::<Vec<_>>();
        self.sidebar_batch_mode = false;
        self.sidebar_state.clear_selection();
        let session_ids = session_ids
            .into_iter()
            .filter(|session_id| {
                !self
                    .pending_session_deletion_ids
                    .contains(session_id.as_str())
            })
            .collect::<Vec<_>>();
        if session_ids.is_empty() {
            cx.notify();
            return;
        }
        let Some(runtime) = self.runtime.clone() else {
            cx.notify();
            return;
        };
        let session_id_set = session_ids
            .iter()
            .map(|session_id| session_id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.pending_session_deletion_ids
            .extend(session_id_set.iter().cloned());
        self.optimistically_remove_sessions(&session_id_set);
        self.queue_agent_ui_state();
        cx.notify();
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut first_error = None;
            for session_id in session_ids {
                if let Err(error) = runtime.agent().manager().delete_session(&session_id).await
                    && first_error.is_none()
                {
                    first_error = Some(error);
                }
            }
            if let Some(error) = first_error {
                return Err(error);
            }
            Ok::<(), vibex_core::VibexError>(())
        });
        self.finish_optimistic_session_deletion(generation, session_id_set, runner, cx);
    }

    fn optimistically_remove_sessions(&mut self, session_ids: &BTreeSet<String>) {
        self.agent_overview_generation = self.agent_overview_generation.wrapping_add(1);
        self.optimistically_removed_session_ids
            .extend(session_ids.iter().cloned());
        let deleting_selected_session = self
            .selected_session_id
            .as_ref()
            .is_some_and(|session_id| session_ids.contains(session_id.as_str()));
        self.sessions
            .retain(|session| !session_ids.contains(session.id.as_str()));
        self.agent_session_view_cache
            .retain(|session_id, _| !session_ids.contains(session_id));
        self.composer_session_drafts
            .retain(|session_id, _| !session_ids.contains(session_id));
        self.agent_session_view_lru
            .retain(|session_id| !session_ids.contains(session_id));
        self.pending_new_session_titles
            .retain(|session_id, _| !session_ids.contains(session_id));
        self.pending_agent_turn_session_ids
            .retain(|session_id| !session_ids.contains(session_id));
        self.unread_agent_completion_session_ids
            .retain(|session_id| !session_ids.contains(session_id));
        self.session_search_index
            .retain(|session_id, _| !session_ids.contains(session_id));
        if self
            .pending_session_search_jump
            .as_ref()
            .is_some_and(|target| session_ids.contains(target.session_id.as_str()))
        {
            self.pending_session_search_jump = None;
        }
        if deleting_selected_session {
            // The sidebar is updated optimistically, so the active workbench
            // must be invalidated in the same transaction. Otherwise the
            // removed session's timeline remains rendered until the
            // authoritative overview refresh completes.
            self.clear_child_agent_context();
            self.session_generation = self.session_generation.saturating_add(1);
            self.selected_session_id = None;
            self.timeline = TimelineModel::default();
            self.timeline_scroll = VirtualListScrollHandle::new();
            self.timeline_row_sizes = Rc::new(Vec::new());
            self.invalidate_timeline_render_caches();
            self.runtime_selection = None;
            self.token_usage = None;
            self.agent_loading = false;
            self.agent_turn_pending = false;
            self.composer_input_session_id = None;
            self.composer_attachments.clear();
            self.composer_command_entry = None;
            self.clear_suggestions();
        }
        self.reconcile_sidebar_state();
        self.publish_sidebar_invalidation();
    }

