    fn set_theme(&mut self, mode: ModelThemeMode, window: &mut Window, cx: &mut Context<Self>) {
        self.ui_state.appearance.theme = mode;
        theme::apply_appearance(&self.ui_state.appearance, Some(window), cx);
        self.queue_ui_state();
        cx.notify();
    }

    fn set_locale(&mut self, mode: LocaleMode, window: &mut Window, cx: &mut Context<Self>) {
        self.ui_state.appearance.locale = mode;
        locale::apply_locale(mode);
        self.sync_locale_dependents(window, cx);
        crate::system_tray::update_locale(self.resolved_locale(), cx);
        self.queue_ui_state();
        cx.notify();
    }

    fn sync_locale_dependents(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let strings = self.strings();
        self.session_search.update(cx, |input, cx| {
            input.set_placeholder(strings.session_search_placeholder, window, cx)
        });
        self.sidebar_rename_input.update(cx, |input, cx| {
            input.set_placeholder(strings.sidebar_rename_placeholder, window, cx)
        });
        self.user_message_edit_input.update(cx, |input, cx| {
            input.set_placeholder(
                locale::text("Edit message", "编辑消息", "編輯訊息"),
                window,
                cx,
            )
        });
        self.composer_input.update(cx, |input, cx| {
            input.set_placeholder(strings.message_agent, window, cx)
        });
        self.new_session_input.update(cx, |input, cx| {
            input.set_placeholder(strings.new_session_prompt_placeholder, window, cx)
        });
        self.new_session_worktree_name_input
            .update(cx, |input, cx| {
                input.set_placeholder(
                    locale::text("Worktree name", "Worktree 名称", "Worktree 名稱"),
                    window,
                    cx,
                )
            });
        self.new_session_worktree_path_input
            .update(cx, |input, cx| {
                input.set_placeholder(
                    locale::text("Managed path", "托管路径", "受管路徑"),
                    window,
                    cx,
                )
            });
        self.new_session_project_search.update(cx, |input, cx| {
            input.set_placeholder(strings.new_session_search_project, window, cx)
        });
        self.code_workbench
            .update(cx, |workbench, cx| workbench.sync_locale(window, cx));
        self.code_right_rail
            .update(cx, |right_rail, cx| right_rail.sync_locale(window, cx));
        self.management_view
            .update(cx, |management, cx| management.sync_locale(window, cx));
    }

    fn adjust_window_scale(&mut self, delta: i16, window: &mut Window, cx: &mut Context<Self>) {
        self.ui_state.appearance.window_scale_percent = adjust_u16(
            self.ui_state.appearance.window_scale_percent,
            delta,
            75,
            200,
        );
        theme::apply_appearance(&self.ui_state.appearance, Some(window), cx);
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_pending_turn_heights.clear();
        self.timeline_estimated_turn_heights.clear();
        self.rebuild_timeline_sizes();
        self.queue_ui_state();
        cx.notify();
    }

    fn set_interface_font_family(
        &mut self,
        family: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if let Some(family) = family.as_deref()
            && let Err(error) = crate::platform::load_selected_font_families(cx, &[family])
        {
            eprintln!("vibex-fonts: {error}");
        }
        self.ui_state.appearance.interface_font.family = family;
        theme::apply_appearance(&self.ui_state.appearance, Some(window), cx);
        self.queue_ui_state();
        cx.notify();
    }

    fn set_code_font_family(
        &mut self,
        family: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if let Some(family) = family.as_deref()
            && let Err(error) = crate::platform::load_selected_font_families(cx, &[family])
        {
            eprintln!("vibex-fonts: {error}");
        }
        self.ui_state.appearance.code_font.family = family;
        let code_family = self
            .ui_state
            .appearance
            .code_font
            .family
            .clone()
            .unwrap_or_else(|| crate::platform::default_code_font_family().to_string());
        let code_size = self.ui_state.appearance.code_font.size;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_code_font(code_family, code_size, cx)
        });
        theme::apply_appearance(&self.ui_state.appearance, Some(window), cx);
        self.queue_ui_state();
        cx.notify();
    }

    fn adjust_interface_font(
        &mut self,
        size_delta: i16,
        weight_delta: i16,
        cx: &mut Context<Self>,
    ) {
        self.ui_state.appearance.interface_font.size = adjust_u16(
            self.ui_state.appearance.interface_font.size,
            size_delta,
            12,
            24,
        );
        self.ui_state.appearance.interface_font.weight = adjust_u16(
            self.ui_state.appearance.interface_font.weight,
            weight_delta,
            100,
            900,
        );
        Theme::global_mut(cx).font_size = theme::scaled_font_size(
            self.ui_state.appearance.interface_font.size,
            self.ui_state.appearance.window_scale_percent,
        );
        apply_code_font_weight(self.ui_state.appearance.code_font.weight, cx);
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_pending_turn_heights.clear();
        self.timeline_estimated_turn_heights.clear();
        self.rebuild_timeline_sizes();
        self.queue_ui_state();
        cx.notify();
    }

    fn adjust_code_font(&mut self, size_delta: i16, weight_delta: i16, cx: &mut Context<Self>) {
        self.ui_state.appearance.code_font.size =
            adjust_u16(self.ui_state.appearance.code_font.size, size_delta, 10, 24);
        self.ui_state.appearance.code_font.weight = adjust_u16(
            self.ui_state.appearance.code_font.weight,
            weight_delta,
            100,
            900,
        );
        Theme::global_mut(cx).mono_font_size = theme::scaled_font_size(
            self.ui_state.appearance.code_font.size,
            self.ui_state.appearance.window_scale_percent,
        );
        apply_code_font_weight(self.ui_state.appearance.code_font.weight, cx);
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_pending_turn_heights.clear();
        self.timeline_estimated_turn_heights.clear();
        self.rebuild_timeline_sizes();
        let code_family = self
            .ui_state
            .appearance
            .code_font
            .family
            .clone()
            .unwrap_or_else(|| crate::platform::default_code_font_family().to_string());
        let code_size = self.ui_state.appearance.code_font.size;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_code_font(code_family, code_size, cx)
        });
        self.queue_ui_state();
        cx.notify();
    }

