    fn sync_timeline_display_settings_to_runtime(&self) {
        let Some(runtime) = self.runtime.as_ref() else {
            return;
        };
        runtime.set_timeline_display_settings(AgentTimelineDisplaySettings {
            show_agent_generation_status: self.ui_state.session.show_agent_generation_status,
            reasoning_display_mode: match self.ui_state.session.reasoning_display_mode {
                ReasoningDisplayMode::LatestAtBottom => {
                    AgentTimelineReasoningDisplayMode::LatestAtBottom
                }
                ReasoningDisplayMode::Timeline => AgentTimelineReasoningDisplayMode::Timeline,
            },
            reasoning_expanded_by_default: self.ui_state.session.reasoning_expanded_by_default,
            enhanced_command_execution_display: self
                .ui_state
                .session
                .enhanced_command_execution_display,
            enhanced_file_operation_display: self.ui_state.session.enhanced_file_operation_display,
        });
    }

    fn set_close_to_tray(&mut self, enabled: bool, cx: &mut Context<Self>) {
        self.ui_state.desktop_behavior.close_to_tray = enabled;
        self.queue_ui_state();
        cx.notify();
    }

    fn set_network_proxy_url(&mut self, value: String, cx: &mut Context<Self>) {
        let next = NetworkProxyUiState {
            enabled: self.ui_state.network_proxy.enabled,
            proxy_url: (!value.trim().is_empty()).then_some(value.trim().to_string()),
        };
        match vibex_desktop_runtime::network_proxy::configure(&next) {
            Ok(normalized) => {
                self.ui_state.network_proxy = normalized;
                self.queue_ui_state();
                self.set_settings_operation_note(None, cx);
            }
            Err(error) => {
                self.set_settings_operation_note(Some(localize_network_proxy_error(&error)), cx);
            }
        }
        cx.notify();
    }

    fn set_network_proxy_enabled(&mut self, enabled: bool, cx: &mut Context<Self>) {
        let next = NetworkProxyUiState {
            enabled,
            proxy_url: self.ui_state.network_proxy.proxy_url.clone(),
        };
        match vibex_desktop_runtime::network_proxy::configure(&next) {
            Ok(normalized) => {
                self.ui_state.network_proxy = normalized;
                self.queue_ui_state();
                self.set_settings_operation_note(None, cx);
            }
            Err(error) => {
                self.set_settings_operation_note(Some(localize_network_proxy_error(&error)), cx);
            }
        }
        cx.notify();
    }

    fn set_settings_operation_note(&mut self, note: Option<String>, cx: &mut Context<Self>) {
        // Settings callbacks can be running inside FoundationSettings::update. Defer the
        // sibling entity update until the current GPUI update finishes to avoid re-entrancy.
        let settings_view = self.settings_view.clone();
        cx.defer(move |cx| {
            settings_view.update(cx, |settings, cx| {
                settings.operation_note = note;
                cx.notify();
            });
        });
    }

