    fn show_turn_preview_rail(&mut self, cx: &mut Context<Self>) {
        if !self.turn_preview_rail_visible {
            self.turn_preview_rail_visible = true;
            cx.notify();
        }
    }

    fn handle_turn_preview_rail_hover(&mut self, hovered: bool, cx: &mut Context<Self>) {
        if !hovered && (self.turn_preview_rail_visible || self.turn_preview_active_index.is_some())
        {
            self.turn_preview_rail_visible = false;
            self.turn_preview_active_index = None;
            cx.notify();
        }
    }

    fn set_turn_preview_active_index(
        &mut self,
        index: usize,
        hovered: bool,
        cx: &mut Context<Self>,
    ) {
        let next = if hovered {
            Some(index)
        } else if self.turn_preview_active_index == Some(index) {
            None
        } else {
            self.turn_preview_active_index
        };
        if self.turn_preview_active_index != next {
            self.turn_preview_active_index = next;
            cx.notify();
        }
    }

    fn render_agent_turn_preview_rail(
        &mut self,
        turns: &[Rc<TimelineConversationTurn>],
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let locale = self.resolved_locale();
        let active_index = self
            .turn_preview_active_index
            .filter(|index| *index < turns.len());
        let reduced_motion = self.ui_state.appearance.reduced_motion;
        let foreground = cx.theme().foreground;
        let muted_foreground = cx.theme().muted_foreground;
        let popover = cx.theme().popover;
        let muted = cx.theme().muted;
        let border = cx.theme().border;
        let ring = cx.theme().ring;
        let background = cx.theme().background;
        let is_dark = cx.theme().is_dark();
        let card_width = (self.last_visibility.layout.viewport_width as f32
            - AGENT_TURN_PREVIEW_CARD_VIEWPORT_INSET)
            .clamp(
                AGENT_TURN_PREVIEW_CARD_MIN_WIDTH,
                AGENT_TURN_PREVIEW_CARD_MAX_WIDTH,
            );
        let card_background = if is_dark { muted } else { popover };
        let empty_message = match locale {
            locale::ResolvedLocale::En => "Empty message",
            locale::ResolvedLocale::ZhCn => "空消息",
            locale::ResolvedLocale::ZhTw => "空訊息",
        };

        // The rail only mounts its list while hovered, so building a preview card
        // per turn on every frame would scale the frame cost with conversation
        // length for something that is not on screen.
        let rail_turns: &[Rc<TimelineConversationTurn>] = if self.turn_preview_rail_visible {
            turns
        } else {
            &[]
        };
        let items = rail_turns
            .iter()
            .enumerate()
            .map(|(preview_index, turn)| {
                let turn_number = preview_index + 1;
                let row_index = preview_index;
                let label = format!("#{turn_number}");
                let title = agent_turn_preview_title(turn, &label);
                let aria_label = match locale {
                    locale::ResolvedLocale::En => {
                        format!("Jump to turn {turn_number}: {title}")
                    }
                    locale::ResolvedLocale::ZhCn => {
                        format!("跳转到第 {turn_number} 轮：{title}")
                    }
                    locale::ResolvedLocale::ZhTw => {
                        format!("跳轉到第 {turn_number} 輪：{title}")
                    }
                };
                let distance = active_index.map(|active| active.abs_diff(preview_index));
                let (line_width, line_height, line_color) = match distance {
                    Some(0) => (26.4, 2.88, foreground),
                    Some(1) => (20.0, 2.24, muted_foreground.opacity(0.48)),
                    Some(2) => (16.8, 2.24, muted_foreground.opacity(0.34)),
                    _ => (14.4, 2.24, muted_foreground.opacity(0.24)),
                };

                let preview_card = (distance == Some(0)).then(|| {
                    let content = agent_turn_preview_content(turn, &label, empty_message);
                    let card_shadow = if is_dark {
                        vec![
                            gpui::BoxShadow::new(px(0.0), px(8.0), gpui::black().opacity(0.24))
                                .blur_radius(px(22.0)),
                        ]
                    } else {
                        vec![
                            gpui::BoxShadow::new(px(0.0), px(1.0), background.opacity(0.70)),
                            gpui::BoxShadow::new(px(0.0), px(8.0), foreground.opacity(0.10))
                                .blur_radius(px(24.0)),
                        ]
                    };
                    let remaining_file_count = content
                        .file_paths
                        .len()
                        .saturating_sub(AGENT_TURN_PREVIEW_VISIBLE_FILE_COUNT);
                    let file_items = content
                        .file_paths
                        .iter()
                        .take(AGENT_TURN_PREVIEW_VISIBLE_FILE_COUNT)
                        .map(|path| {
                            h_flex()
                                .min_w_0()
                                .max_w(px(112.0))
                                .items_center()
                                .gap(px(5.0))
                                .child(
                                    Icon::default()
                                        .path("icons/vibex/file-code.svg")
                                        .size(px(12.0))
                                        .text_color(muted_foreground),
                                )
                                .child(
                                    div()
                                        .min_w_0()
                                        .text_ellipsis()
                                        .child(agent_turn_preview_file_name(path).to_string()),
                                )
                                .into_any_element()
                        })
                        .collect::<Vec<_>>();
                    let file_summary = (!file_items.is_empty()).then(|| {
                        h_flex()
                            .w_full()
                            .min_w_0()
                            .items_center()
                            .gap(px(12.0))
                            .pt(px(2.0))
                            .overflow_hidden()
                            .text_xs()
                            .line_height(gpui::relative(1.45))
                            .text_color(muted_foreground)
                            .children(file_items)
                            .when(remaining_file_count > 0, |this| {
                                this.child(
                                    div().flex_none().child(format!("+{remaining_file_count}")),
                                )
                            })
                    });
                    let card_anchor_y = if file_summary.is_some() { -64.0 } else { -53.0 };
                    let card = v_flex()
                        .relative()
                        .w(px(card_width))
                        .min_w_0()
                        .gap(px(4.0))
                        .rounded(px(14.0))
                        .border_1()
                        .border_color(if is_dark {
                            border.opacity(0.0)
                        } else {
                            border.opacity(0.72)
                        })
                        .bg(card_background)
                        .px(px(10.0))
                        .py(px(12.0))
                        .text_color(foreground)
                        .shadow(card_shadow)
                        .child(
                            div()
                                .w_full()
                                .min_w_0()
                                .overflow_hidden()
                                .line_clamp(1)
                                .text_sm()
                                .line_height(gpui::relative(1.4))
                                .font_weight(FontWeight(550.0))
                                .child(content.title.clone()),
                        )
                        .child(
                            div()
                                .w_full()
                                .min_w_0()
                                .overflow_hidden()
                                .whitespace_normal()
                                .line_clamp(3)
                                .text_sm()
                                .line_height(gpui::relative(1.5))
                                .text_color(muted_foreground)
                                .child(content.message.clone()),
                        )
                        .when_some(file_summary, |this, summary| this.child(summary));
                    let card = if reduced_motion {
                        card.into_any_element()
                    } else {
                        Transition::new(AGENT_TURN_PREVIEW_CARD_TRANSITION_DURATION)
                            .ease(ease_out_cubic)
                            .slide_x(px(-7.2), px(0.0))
                            .fade(0.0, 1.0)
                            .apply(card, format!("turn-preview-card-open-{preview_index}"))
                            .into_any_element()
                    };
                    div()
                        .absolute()
                        .top_1_2()
                        .left(px(36.8))
                        .child(div().relative().top(px(card_anchor_y)).child(card))
                });

                h_flex()
                    .id(format!("turn-preview-{preview_index}"))
                    .relative()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .justify_start()
                    .when(turns.len() == 1, |this| this.h(px(32.0)).flex_none())
                    .when(turns.len() > 1, |this| {
                        this.flex_1()
                            .min_h_0()
                            .max_h(px(AGENT_TURN_PREVIEW_ITEM_MAX_HEIGHT))
                    })
                    .cursor_pointer()
                    .focusable()
                    .tab_stop(true)
                    .role(Role::Button)
                    .aria_label(aria_label)
                    .focus_visible(move |style| style.bg(ring.opacity(0.08)))
                    .on_hover(cx.listener(move |this, hovered, _, cx| {
                        this.set_turn_preview_active_index(preview_index, *hovered, cx)
                    }))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.timeline_scroll_wheel_idle_task = None;
                        this.timeline_follow.set_following_bottom(false);
                        this.timeline_scroll_to_latest_pending = false;
                        this.timeline_scroll
                            .scroll_to_item(row_index, ScrollStrategy::Center);
                        cx.notify();
                    }))
                    .child(
                        div()
                            .ml(px(5.6))
                            .w(px(line_width))
                            .h(px(line_height))
                            .flex_none()
                            .rounded_full()
                            .bg(line_color),
                    )
                    .when_some(preview_card, |this, card| this.child(card))
                    .into_any_element()
            })
            .collect::<Vec<_>>();

        let list = v_flex()
            .relative()
            .size_full()
            .min_h_0()
            .justify_center()
            .gap_0()
            .children(items);
        let list = if reduced_motion {
            list.into_any_element()
        } else {
            Transition::new(AGENT_TURN_PREVIEW_RAIL_TRANSITION_DURATION)
                .ease(ease_out_cubic)
                .slide_x(px(-5.6), px(0.0))
                .fade(0.0, 1.0)
                .apply(list, "agent-turn-preview-rail-open")
                .into_any_element()
        };
        let navigation_label = match locale {
            locale::ResolvedLocale::En => "Conversation turn preview",
            locale::ResolvedLocale::ZhCn => "对话轮次预览",
            locale::ResolvedLocale::ZhTw => "對話輪次預覽",
        };

        div()
            .id("agent-turn-preview-rail")
            .absolute()
            .top_0()
            .bottom_0()
            .left_0()
            .w(px(AGENT_TURN_PREVIEW_RAIL_WIDTH))
            .role(Role::Navigation)
            .aria_label(navigation_label)
            .on_hover(
                cx.listener(|this, hovered, _, cx| {
                    this.handle_turn_preview_rail_hover(*hovered, cx)
                }),
            )
            .child(
                div()
                    .id("agent-turn-preview-edge-trigger")
                    .absolute()
                    .top_0()
                    .bottom_0()
                    .left_0()
                    .w(px(AGENT_TURN_PREVIEW_EDGE_TRIGGER_WIDTH))
                    .on_hover(cx.listener(|this, hovered, _, cx| {
                        if *hovered {
                            this.show_turn_preview_rail(cx);
                        }
                    })),
            )
            .when(self.turn_preview_rail_visible, |this| {
                this.child(
                    div()
                        .absolute()
                        .top(px(24.0))
                        .bottom(px(24.0))
                        .left(px(7.2))
                        .right_0()
                        .child(list),
                )
            })
            .into_any_element()
    }

    fn render_agent_workbench(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        self.sync_selected_composer_draft(window, cx);
        self.prune_elicitation_forms();
        self.apply_pending_timeline_row_heights();
        self.apply_pending_timeline_scroll();
        let selected = self.selected_session().cloned();
        let mut turns = self.conversation_turns_cached();
        if timeline_virtual_rows_need_rebuild(turns.len(), self.timeline_row_sizes.len()) {
            self.rebuild_timeline_sizes();
            turns = self.conversation_turns_cached();
        }
        let turns_summary = self.conversation_turns_summary;
        self.sync_timeline_duration_tick(turns_summary.has_incomplete_turn, cx);
        let rendered_turns = turns.clone();
        let row_sizes = self.timeline_row_sizes.clone();
        let rendered_row_sizes = row_sizes.clone();
        let strings = self.strings();
        let content_max_width = session_content_max_width(self.ui_state.session.content_width);
        let pending_permission = turns_summary.has_pending_permission;
        self.sync_timeline_bottom_control(self.timeline_scroll.max_offset().y > px(0.0), cx);
        let timeline_bottom_control_visible = self.timeline_bottom_control_visible;
        let timeline_bottom_control_mounted = self.timeline_bottom_control_mounted;
        let turn_preview_rail = (self.ui_state.session.turn_preview_rail && !turns.is_empty())
            .then(|| self.render_agent_turn_preview_rail(turns.as_slice(), cx));
        let timeline_layout_entity = cx.weak_entity();
        let timeline_surface = div()
            .relative()
            .flex_1()
            .min_h_0()
            .min_w_0()
            .overflow_hidden()
            .on_prepaint(move |bounds, _, cx| {
                let width = f32::from(bounds.size.width);
                let _ = timeline_layout_entity.update(cx, |this, cx| {
                    this.sync_timeline_layout_width(width, cx);
                });
            })
            .when(turns.is_empty(), |this| {
                this.child(
                    v_flex()
                        .size_full()
                        .items_center()
                        .justify_center()
                        .gap_2()
                        .p_6()
                        .child(
                            div()
                                .text_lg()
                                .font_semibold()
                                .child(if self.agent_loading {
                                    strings.agent_loading_session
                                } else if selected.is_some() {
                                    strings.agent_start_conversation
                                } else {
                                    strings.agent_select_session
                                }),
                        )
                        .when(!self.agent_loading, |this| {
                            this.child(
                                div()
                                    .max_w(px(460.0))
                                    .text_center()
                                    .text_sm()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(strings.agent_timeline_description),
                            )
                        }),
                )
            })
            .when(!turns.is_empty(), |this| {
                this.child(
                    v_flex()
                        .size_full()
                        .min_h_0()
                        .min_w_0()
                        .overflow_hidden()
                        .capture_any_mouse_down(cx.listener(
                            |this, event: &MouseDownEvent, _, cx| {
                                this.begin_timeline_scrollbar_interaction(event, cx)
                            },
                        ))
                        .on_mouse_up(
                            MouseButton::Left,
                            cx.listener(|this, _, _, cx| {
                                this.finish_timeline_scrollbar_interaction(cx)
                            }),
                        )
                        .on_mouse_up_out(
                            MouseButton::Left,
                            cx.listener(|this, _, _, cx| {
                                this.finish_timeline_scrollbar_interaction(cx)
                            }),
                        )
                        .on_scroll_wheel(cx.listener(|this, event: &ScrollWheelEvent, _, cx| {
                            this.handle_timeline_scroll_wheel(event, cx)
                        }))
                        .child(
                            v_virtual_list(
                                cx.entity().clone(),
                                "agent-timeline-turns",
                                row_sizes,
                                move |this, visible_range, window, cx| {
                                    let turn_count = rendered_turns.len();
                                    visible_range
                                        .filter_map(|index| {
                                            let turn = rendered_turns.get(index)?;
                                            let row_height = rendered_row_sizes.get(index)?.height;
                                            let measured_height_entity = cx.weak_entity();
                                            let measured_turn_id = turn.id.clone();
                                            let turn_content = this.render_timeline_turn(
                                                turn,
                                                index == 0,
                                                index + 1 == turn_count,
                                                window,
                                                cx,
                                            );
                                            Some(
                                                h_flex()
                                                    .w_full()
                                                    .h(row_height)
                                                    .justify_center()
                                                    // `h_flex` defaults to items_center; rows must
                                                    // top-align so estimation slack stays below the
                                                    // content instead of re-centering it.
                                                    .items_start()
                                                    .overflow_hidden()
                                                    .child(
                                                        div()
                                                            .w_full()
                                                            .min_w_0()
                                                            .when_some(
                                                                content_max_width,
                                                                |this, max_width| {
                                                                    this.max_w(px(max_width))
                                                                },
                                                            )
                                                            .on_prepaint(move |bounds, _, cx| {
                                                                let measured_height =
                                                                    f32::from(bounds.size.height);
                                                                let _ = measured_height_entity
                                                                    .update(cx, |this, cx| {
                                                                        this.record_timeline_turn_height(
                                                                            index,
                                                                            measured_turn_id.clone(),
                                                                            measured_height,
                                                                            cx,
                                                                        )
                                                                    });
                                                            })
                                                            .child(turn_content),
                                                    )
                                                    .into_any_element(),
                                            )
                                        })
                                        .collect()
                                },
                            )
                            .size_full()
                            .track_scroll(&self.timeline_scroll)
                            .px_4()
                            .py_4()
                            .gap_0(),
                        )
                        .scrollbar(&self.timeline_scroll, ScrollbarAxis::Vertical),
                )
            })
            .when_some(turn_preview_rail, |this, rail| this.child(rail));
        let runtime_controls = self.render_runtime_controls(cx);
        let conversation_find = self.render_conversation_find(cx);
        let composer = self.render_composer(cx);
        // Terminal mode routes its own near-fullscreen expansion through the
        // same timeline-collapse path as the input composer's expanded state.
        let composer_fullscreen = if self.composer_terminal_mode {
            self.composer_terminal_expanded
        } else {
            self.composer_expanded
        };
        v_flex()
            .id("agent-workbench")
            .size_full()
            .min_h_0()
            .min_w_0()
            .justify_end()
            .overflow_hidden()
            .bg(cx.theme().background)
            .child(
                v_flex()
                    .when(!composer_fullscreen, |this| this.flex_1())
                    .when(composer_fullscreen, |this| this.h_0().flex_none())
                    .min_h_0()
                    .min_w_0()
                    .overflow_hidden()
                    .child(runtime_controls)
                    .when(pending_permission, |this| {
                        // Tauri parity: "Permission waiting for review" alert above the timeline.
                        this.child(
                            h_flex()
                                .w_full()
                                .flex_none()
                                .justify_center()
                                .px_4()
                                .pt_2()
                                .child(
                                    h_flex()
                                        .w_full()
                                        .when_some(content_max_width, |this, max_width| {
                                            this.max_w(px(max_width))
                                        })
                                        .min_h(px(44.0))
                                        .items_start()
                                        .gap_2()
                                        .rounded_lg()
                                        .border_1()
                                        .border_color(cx.theme().border)
                                        .bg(cx.theme().background)
                                        .px_3()
                                        .py_2()
                                        .child(
                                            Icon::default()
                                                .path("icons/vibex/shield-alert.svg")
                                                .size(px(16.0))
                                                .text_color(cx.theme().foreground),
                                        )
                                        .child(
                                            v_flex()
                                                .min_w_0()
                                                .flex_1()
                                                .child(
                                                    div().text_sm().font_medium().child(
                                                        locale::text(
                                                            "Permission waiting for review",
                                                            "权限等待审核",
                                                            "權限等待審核",
                                                        ),
                                                    ),
                                                )
                                                .child(
                                                    div()
                                                        .text_xs()
                                                        .text_color(cx.theme().muted_foreground)
                                                        .child(locale::text(
                                                            "Review the requested action in the timeline card before the Agent continues.",
                                                            "在 Agent 继续前，先查看时间线卡片中的请求操作。",
                                                            "在 Agent 繼續前，先查看時間線卡片中的請求操作。",
                                                        )),
                                                ),
                                        ),
                                ),
                        )
                    })
                    .child(timeline_surface),
            )
            .when(timeline_bottom_control_mounted && !composer_fullscreen, |this| {
                let button = Button::new("follow-agent-bottom").small().primary();
                let button = if self.timeline_follow.unread_count > 0 {
                    button.label(match self.resolved_locale() {
                        locale::ResolvedLocale::En => {
                            format!("{} new", self.timeline_follow.unread_count)
                        }
                        locale::ResolvedLocale::ZhCn => {
                            format!("{} 条新消息", self.timeline_follow.unread_count)
                        }
                        locale::ResolvedLocale::ZhTw => {
                            format!("{} 條新訊息", self.timeline_follow.unread_count)
                        }
                    })
                } else {
                    button
                        .icon(Icon::new(IconName::ArrowDown).size(px(14.0)))
                        .tooltip(match self.resolved_locale() {
                            locale::ResolvedLocale::En => "Scroll to conversation bottom",
                            locale::ResolvedLocale::ZhCn => "滚动到会话底部",
                            locale::ResolvedLocale::ZhTw => "捲動到會話底部",
                        })
                };
                let control = h_flex()
                    .flex_none()
                    .h(px(AGENT_TIMELINE_BOTTOM_CONTROL_HEIGHT_PX))
                    .items_center()
                    .justify_center()
                    .overflow_hidden()
                    .child(button.on_click(cx.listener(|this, _, _, cx| {
                        this.timeline_scroll_wheel_idle_task = None;
                        this.timeline_follow.set_following_bottom(true);
                        this.request_timeline_scroll_to_latest();
                        cx.notify();
                    })));
                let control = if self.ui_state.appearance.reduced_motion {
                    control.into_any_element()
                } else if timeline_bottom_control_visible {
                    Transition::new(AGENT_TIMELINE_BOTTOM_CONTROL_TRANSITION_DURATION)
                        .ease(ease_out_cubic)
                        .height(px(0.0), px(AGENT_TIMELINE_BOTTOM_CONTROL_HEIGHT_PX))
                        .fade(0.0, 1.0)
                        .apply(control, "agent-timeline-bottom-control-open")
                        .into_any_element()
                } else {
                    Transition::new(AGENT_TIMELINE_BOTTOM_CONTROL_TRANSITION_DURATION)
                        .ease(ease_out_cubic)
                        .height(px(AGENT_TIMELINE_BOTTOM_CONTROL_HEIGHT_PX), px(0.0))
                        .fade(1.0, 0.0)
                        .apply(control, "agent-timeline-bottom-control-close")
                        .into_any_element()
                };
                this.child(control)
            })
            .when_some(conversation_find, |this, find| this.child(find))
            .child(composer)
            .into_any_element()
    }

    fn render_runtime_controls(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let Some(state) = self.runtime_selection.clone() else {
            return div().into_any_element();
        };
        if self.selected_session_id.as_ref().is_some_and(|session_id| {
            self.optimistic_runtime_selections
                .contains_key(session_id.as_str())
        }) {
            return div().into_any_element();
        }
        if self.agent_turn_pending
            && matches!(
                state.status,
                SessionRuntimeSelectionStatus::Preparing
                    | SessionRuntimeSelectionStatus::WaitingForCurrentWork
            )
        {
            return div().into_any_element();
        }
        // The selected runtime is already visible in the composer selectors;
        // avoid reserving a persistent banner for the normal ready state.
        if !runtime_status_banner_is_visible(state.status) {
            return div().into_any_element();
        }
        let strings = self.strings();
        let display_label = |selection: &SessionRuntimeSelection| {
            self.runtime_catalog
                .as_ref()
                .and_then(|catalog| {
                    catalog
                        .options
                        .iter()
                        .find(|option| option.selection == *selection)
                })
                .map(|option| {
                    format!(
                        "{} / {} / {}",
                        option.agent_label,
                        runtime_auth_source_selection_label(
                            &selection.auth_source,
                            &option.auth_source_label,
                        ),
                        option.model_label
                    )
                })
                .unwrap_or_else(|| {
                    format!(
                        "{} / {} / {}",
                        selection.agent_id,
                        selection.auth_source.id(),
                        runtime_model_selection_label(&selection.model)
                    )
                })
        };
        let effective_label = display_label(&state.effective);
        let desired_label = display_label(&state.desired);
        let (icon, accent, title) = match state.status {
            SessionRuntimeSelectionStatus::Ready => (
                IconName::Check,
                cx.theme().success,
                format!("{} {effective_label}", strings.runtime_using),
            ),
            SessionRuntimeSelectionStatus::WaitingForCurrentWork => (
                IconName::Cpu,
                cx.theme().warning,
                format!("{} {desired_label}", strings.runtime_waiting),
            ),
            SessionRuntimeSelectionStatus::Preparing => (
                IconName::Cpu,
                cx.theme().warning,
                format!("{} {desired_label}", strings.runtime_preparing),
            ),
            SessionRuntimeSelectionStatus::FailedUsingPrevious => (
                IconName::TriangleAlert,
                cx.theme().danger,
                state
                    .actionable_error
                    .as_ref()
                    .map(|error| {
                        locale::localize_error_message(&format!(
                            "{}: {}",
                            error.code, error.message
                        ))
                    })
                    .unwrap_or_else(|| {
                        format!("{} {effective_label}", strings.runtime_still_using)
                    }),
            ),
        };
        let recovery_hint = state
            .actionable_error
            .as_ref()
            .and_then(|error| error.recovery_hint.as_deref())
            .map(locale::localize_ui_message);
        let show_retry = state.status == SessionRuntimeSelectionStatus::FailedUsingPrevious;
        let show_cancel = state.pending_switch_id.is_some();
        let can_reset = state.desired != state.effective;
        let content_max_width = session_content_max_width(self.ui_state.session.content_width);

        h_flex()
            .w_full()
            .flex_none()
            .justify_center()
            .px_4()
            .pt_2()
            .child(
                h_flex()
                    .w_full()
                    .when_some(content_max_width, |this, max_width| {
                        this.max_w(px(max_width))
                    })
                    .min_h(px(36.0))
                    .items_center()
                    .gap_2()
                    .rounded_lg()
                    .border_1()
                    .border_color(if show_retry {
                        cx.theme().danger.opacity(0.55)
                    } else {
                        cx.theme().border
                    })
                    .bg(cx.theme().secondary.opacity(0.35))
                    .px_3()
                    .py_2()
                    .child(Icon::new(icon).small().text_color(accent))
                    .child(
                        v_flex()
                            .min_w_0()
                            .flex_1()
                            .child(div().truncate().text_xs().font_medium().child(title))
                            .when_some(recovery_hint, |this, hint| {
                                this.child(
                                    div()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(hint),
                                )
                            }),
                    )
                    .when(show_cancel, |this| {
                        this.child(
                            Button::new("cancel-runtime-switch")
                                .xsmall()
                                .ghost()
                                .label(strings.sidebar_cancel)
                                .disabled(self.active_runtime_controls_pending())
                                .on_click(
                                    cx.listener(|this, _, _, cx| this.cancel_runtime_switch(cx)),
                                ),
                        )
                    })
                    .when(show_retry, |this| {
                        this.child(
                            Button::new("retry-runtime-selection")
                                .xsmall()
                                .outline()
                                .label(strings.retry)
                                .disabled(self.active_runtime_controls_pending())
                                .on_click(
                                    cx.listener(|this, _, _, cx| this.retry_runtime_selection(cx)),
                                ),
                        )
                        .child(
                            Button::new("reset-runtime-selection")
                                .xsmall()
                                .ghost()
                                .label(strings.runtime_use_current)
                                .disabled(self.active_runtime_controls_pending() || !can_reset)
                                .on_click(
                                    cx.listener(|this, _, _, cx| this.reset_runtime_selection(cx)),
                                ),
                        )
                    }),
            )
            .into_any_element()
    }

    #[allow(clippy::too_many_arguments)]
    fn render_composer_runtime_choice(
        &mut self,
        id: String,
        label: String,
        icon: AnyElement,
        choices: Vec<RuntimeCascadeChoice>,
        selected_value: String,
        compact: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_label = choices
            .iter()
            .find(|choice| choice.value == selected_value)
            .map(|choice| choice.label.clone())
            .unwrap_or_else(|| label.to_string());
        let tooltip = format!("{label}: {selected_label}");
        let content = runtime_selector_dropdown_content(icon, selected_label, compact, cx);
        let menu_id = format!("composer-runtime-choice-{id}");
        let menu_max_height = (self.last_visibility.layout.viewport_height as f32 - 128.0)
            .clamp(160.0, COMPOSER_RUNTIME_MENU_MAX_HEIGHT);
        let choices_empty = choices.is_empty();
        let controls_pending = self.active_runtime_controls_pending();
        let trigger = Button::new(format!("composer-runtime-{id}"))
            .xsmall()
            .ghost()
            .h(px(32.0))
            .when(compact, |button| button.compact().w(px(32.0)))
            .when(!compact, |button| button.px_2())
            .tooltip(tooltip)
            .child(content)
            .disabled(choices_empty || controls_pending);
        let items = choices
            .into_iter()
            .map(|choice| RuntimeChoiceMenuItem {
                selected: choice.value == selected_value,
                id: choice.value,
                label: choice.label,
                action: RuntimeChoiceMenuAction::ActiveSession(choice.selection),
            })
            .collect::<Vec<_>>();
        self.render_runtime_choice_popover(
            menu_id,
            trigger,
            items,
            self.composer_geometry,
            menu_max_height,
            cx,
        )
    }

    fn render_composer_runtime_cascade(
        &mut self,
        desired: SessionRuntimeSelection,
        catalog: SessionRuntimeOptionCatalog,
        compact: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_option = catalog.options.iter().find(|option| {
            option.selection.agent_id == desired.agent_id
                && option.selection.auth_source == desired.auth_source
                && option.selection.model == desired.model
        });
        let selected_provider_model_label = runtime_provider_model_label(selected_option, &desired);
        let tooltip = format!(
            "{}: {selected_provider_model_label}",
            locale::text(
                "Authentication source / Model",
                "认证方式 / 模型",
                "認證方式 / 模型",
            )
        );
        let model_icon = desired
            .model_id()
            .and_then(|model_id| {
                model_brand_icon(
                    model_id,
                    px(16.0),
                    Some(cx.theme().foreground.opacity(0.88)),
                )
            })
            .unwrap_or_else(|| {
                new_session_selector_icon(
                    "icons/vibex/sparkles.svg",
                    theme::semantic_color("chart-2", cx.theme().is_dark()),
                )
            });
        let content = runtime_selector_dropdown_content(
            model_icon,
            selected_provider_model_label,
            compact,
            cx,
        );
        let trigger_bounds_entity = cx.weak_entity();
        let tracked_content = div()
            .when(compact, |this| this.size_full())
            .when(!compact, |this| this.flex_none())
            .on_prepaint(move |bounds, _, cx| {
                let _ = trigger_bounds_entity.update(cx, |this, cx| {
                    if this.composer_geometry.runtime_trigger_bounds != Some(bounds) {
                        this.composer_geometry.runtime_trigger_bounds = Some(bounds);
                        if this.composer_runtime_menu_open
                            || this.runtime_choice_menu_open.is_some()
                        {
                            cx.notify();
                        }
                    }
                });
            })
            .child(content);
        let trigger = Button::new("composer-runtime-model")
            .xsmall()
            .ghost()
            .h(px(32.0))
            .when(compact, |button| button.compact().w(px(32.0)))
            .when(!compact, |button| button.px_2())
            .tooltip(tooltip)
            .child(tracked_content)
            .disabled(self.active_runtime_controls_pending());

        let menu_agent_id = self
            .composer_runtime_menu_agent_id
            .clone()
            .unwrap_or_else(|| desired.agent_id.clone());
        let menu_auth_source = self
            .composer_runtime_menu_auth_source
            .clone()
            .unwrap_or_else(|| desired.auth_source.clone());
        let agent_choices = runtime_menu_agents(&self.agent_snapshots);
        let mut auth_source_choices = runtime_auth_sources_for_agent(&catalog, &menu_agent_id);
        auth_source_choices
            .sort_by_key(|source| !matches!(source.kind, RuntimeAuthSourceKind::AgentAccount));
        let preferred_model_selection = if desired.agent_id == menu_agent_id {
            Some(desired.clone())
        } else {
            self.ui_state
                .composer
                .runtime_selections_by_agent
                .get(&menu_agent_id)
                .cloned()
        };
        let model_choices = runtime_model_choices(
            &catalog,
            &menu_agent_id,
            &menu_auth_source,
            preferred_model_selection.as_ref(),
            &self.ui_state.composer.runtime_selections_by_model,
        );
        let menu_width = (self.last_visibility.layout.viewport_width as f32 - 32.0)
            .clamp(220.0, COMPOSER_RUNTIME_MENU_WIDTH);
        let menu_max_height = (self.last_visibility.layout.viewport_height as f32 - 128.0)
            .clamp(160.0, COMPOSER_RUNTIME_MENU_MAX_HEIGHT);
        let menu_view = self.composer_runtime_menu_view;
        let menu_row_count = match menu_view {
            ComposerRuntimeMenuView::Agent => agent_choices.len(),
            ComposerRuntimeMenuView::AuthSource => {
                runtime_provider_model_menu_row_count(&catalog, &menu_agent_id)
            }
            ComposerRuntimeMenuView::Authentication => self
                .runtime_authentication_menu
                .as_ref()
                .and_then(|state| state.catalog.as_ref())
                .map(|catalog| catalog.methods.len().saturating_add(2))
                .unwrap_or(2),
            ComposerRuntimeMenuView::Model => model_choices.len(),
        };
        let menu_height = composer_runtime_menu_height(menu_view, menu_row_count, menu_max_height);
        let menu_placement = composer_runtime_menu_placement(
            self.composer_geometry.runtime_trigger_bounds,
            self.last_visibility.layout.viewport_height as f32,
            menu_height,
            menu_max_height,
        );
        let separator = || {
            div()
                .mx(px(2.0))
                .my_1()
                .h(px(1.0))
                .flex_none()
                .bg(cx.theme().border.opacity(0.70))
        };
        let menu_content = match self.composer_runtime_menu_view {
            ComposerRuntimeMenuView::Agent => {
                let edit_agent_id = menu_agent_id.clone();
                let edit_label = locale::text("Edit Agent", "编辑 Agent", "編輯 Agent");
                let rows = agent_choices
                    .into_iter()
                    .map(|agent| {
                        let auth_source_count =
                            runtime_auth_sources_for_agent(&catalog, &agent.id).len();
                        let identity = agent_brand_identity(&agent);
                        let selected = agent.id == desired.agent_id;
                        let agent_id = agent.id;
                        Button::new(format!("composer-runtime-agent:{agent_id}"))
                            .small()
                            .ghost()
                            .w_full()
                            .h(px(40.0))
                            .flex_none()
                            .px_2()
                            .justify_start()
                            .selected(selected)
                            .rounded(gpui_component::button::ButtonRounded::Size(px(6.0)))
                            .child(
                                h_flex()
                                    .size_full()
                                    .min_w_0()
                                    .gap_2()
                                    .child(runtime_agent_icon(&identity))
                                    .child(
                                        div()
                                            .min_w_0()
                                            .flex_1()
                                            .truncate()
                                            .text_sm()
                                            .child(agent.label),
                                    )
                                    .when(selected, |this| {
                                        this.child(new_session_selector_icon(
                                            "icons/vibex/crosshair.svg",
                                            cx.theme().primary,
                                        ))
                                    })
                                    .child(
                                        div()
                                            .flex_none()
                                            .text_xs()
                                            .text_color(cx.theme().muted_foreground)
                                            .child(runtime_profile_count_label(auth_source_count)),
                                    )
                                    .child(
                                        Icon::new(IconName::ChevronRight)
                                            .size(px(14.0))
                                            .text_color(cx.theme().muted_foreground),
                                    ),
                            )
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.navigate_composer_runtime_menu(
                                    ComposerRuntimeMenuView::AuthSource,
                                    Some(agent_id.clone()),
                                    None,
                                    cx,
                                )
                            }))
                    })
                    .collect::<Vec<_>>();
                v_flex()
                    .h_full()
                    .min_h_0()
                    .child(
                        div()
                            .flex_none()
                            .px_2()
                            .py(px(6.0))
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child("Agent"),
                    )
                    .child(separator())
                    .child(
                        v_flex()
                            .min_h_0()
                            .flex_1()
                            .overflow_y_scrollbar()
                            .when(rows.is_empty(), |this| {
                                this.child(runtime_menu_empty_state(cx))
                            })
                            .children(rows),
                    )
                    .child(separator())
                    .child(
                        h_flex().w_full().flex_none().p_1().child(
                            Button::new("composer-runtime-edit-agent")
                                .small()
                                .ghost()
                                .w_full()
                                .justify_start()
                                .icon(IconName::Settings)
                                .label(edit_label)
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.open_agent_auth_management(edit_agent_id.clone(), cx)
                                })),
                        ),
                    )
                    .into_any_element()
            }
            ComposerRuntimeMenuView::AuthSource => self.render_provider_model_groups(
                &menu_agent_id,
                &catalog,
                Some(&desired),
                preferred_model_selection.as_ref(),
                self.composer_runtime_search.clone(),
                false,
                cx,
            ),
            ComposerRuntimeMenuView::Authentication => {
                self.render_runtime_authentication_menu(menu_agent_id, menu_auth_source, false, cx)
            }
            ComposerRuntimeMenuView::Model => {
                let agent_label = runtime_agent_label(&self.agent_snapshots, &menu_agent_id);
                let auth_source_label = runtime_auth_source_label(&catalog, &menu_auth_source);
                let agent_identity = format!("{} {agent_label}", menu_agent_id);
                let breadcrumb_agent_id = menu_agent_id.clone();
                let rows = model_choices
                    .into_iter()
                    .map(|choice| {
                        let selected = choice.selection.agent_id == desired.agent_id
                            && choice.selection.auth_source == desired.auth_source
                            && choice.selection.model == desired.model;
                        let selection = choice.selection;
                        let icon = selection
                            .model_id()
                            .and_then(|model_id| {
                                model_brand_icon(
                                    model_id,
                                    px(16.0),
                                    Some(cx.theme().foreground.opacity(0.88)),
                                )
                            })
                            .unwrap_or_else(|| {
                                new_session_selector_icon(
                                    "icons/vibex/sparkles.svg",
                                    theme::semantic_color("chart-2", cx.theme().is_dark()),
                                )
                            });
                        Button::new(format!(
                            "composer-runtime-model:{}",
                            runtime_model_selection_key(&selection.model)
                        ))
                        .small()
                        .ghost()
                        .w_full()
                        .h(px(48.0))
                        .flex_none()
                        .px_2()
                        .justify_start()
                        .selected(selected)
                        .rounded(gpui_component::button::ButtonRounded::Size(px(6.0)))
                        .child(
                            h_flex()
                                .size_full()
                                .min_w_0()
                                .gap_2()
                                .child(icon)
                                .child(
                                    v_flex()
                                        .min_w_0()
                                        .flex_1()
                                        .child(div().truncate().text_sm().child(choice.label))
                                        .child(
                                            div()
                                                .truncate()
                                                .text_xs()
                                                .text_color(cx.theme().muted_foreground)
                                                .child(format!(
                                                    "{agent_label} / {auth_source_label}"
                                                )),
                                        ),
                                )
                                .when(selected, |this| {
                                    this.child(Icon::new(IconName::Check).size(px(14.0)))
                                }),
                        )
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.choose_runtime_selection(selection.clone(), cx)
                        }))
                    })
                    .collect::<Vec<_>>();
                v_flex()
                    .h_full()
                    .min_h_0()
                    .child(
                        h_flex()
                            .w_full()
                            .min_w_0()
                            .h(px(34.0))
                            .flex_none()
                            .items_center()
                            .gap_1()
                            .px_1()
                            .child(
                                Button::new("composer-runtime-breadcrumb-agent")
                                    .xsmall()
                                    .ghost()
                                    .h(px(28.0))
                                    .max_w(px(132.0))
                                    .min_w_0()
                                    .px_1()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(
                                        h_flex()
                                            .min_w_0()
                                            .gap(px(5.0))
                                            .child(Icon::new(IconName::ArrowLeft).size(px(14.0)))
                                            .child(runtime_agent_icon(&agent_identity))
                                            .child(div().min_w_0().truncate().child(agent_label)),
                                    )
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.navigate_composer_runtime_menu(
                                            ComposerRuntimeMenuView::Agent,
                                            None,
                                            None,
                                            cx,
                                        )
                                    })),
                            )
                            .child(
                                Icon::new(IconName::ChevronRight)
                                    .size(px(14.0))
                                    .text_color(cx.theme().muted_foreground.opacity(0.70)),
                            )
                            .child(
                                Button::new("composer-runtime-breadcrumb-auth-source")
                                    .xsmall()
                                    .ghost()
                                    .h(px(28.0))
                                    .min_w_0()
                                    .flex_1()
                                    .px_1()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(
                                        h_flex()
                                            .min_w_0()
                                            .gap(px(5.0))
                                            .child(new_session_selector_icon(
                                                "icons/vibex/database.svg",
                                                theme::semantic_color(
                                                    "chart-2",
                                                    cx.theme().is_dark(),
                                                ),
                                            ))
                                            .child(
                                                div().min_w_0().truncate().child(auth_source_label),
                                            ),
                                    )
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.navigate_composer_runtime_menu(
                                            ComposerRuntimeMenuView::AuthSource,
                                            Some(breadcrumb_agent_id.clone()),
                                            None,
                                            cx,
                                        )
                                    })),
                            ),
                    )
                    .child(separator())
                    .child(
                        v_flex()
                            .min_h_0()
                            .flex_1()
                            .overflow_y_scrollbar()
                            .when(rows.is_empty(), |this| {
                                this.child(runtime_menu_empty_state(cx))
                            })
                            .children(rows),
                    )
                    .into_any_element()
            }
        };
        let menu_panel = v_flex()
            .id("composer-runtime-cascade-content")
            .w(px(menu_width))
            .h(px(menu_placement.height))
            .min_h_0()
            .overflow_hidden()
            .rounded(px(8.0))
            .border_1()
            .border_color(cx.theme().border.opacity(0.70))
            .bg(cx.theme().popover)
            .p(px(6.0))
            .shadow_lg()
            .child(menu_content);
        let menu_open = self.composer_runtime_menu_open;

        let popover = Popover::new("composer-runtime-cascade")
            .anchor(menu_placement.anchor)
            .appearance(false)
            .open(menu_open)
            .on_open_change(
                cx.listener(|this, open, _, cx| this.set_composer_runtime_menu_open(*open, cx)),
            )
            .trigger(trigger)
            .child(menu_panel)
            .map(|popover| match menu_placement.anchor {
                Anchor::TopLeft | Anchor::TopCenter | Anchor::TopRight => {
                    popover.top(px(menu_placement.trigger_offset))
                }
                _ => popover.bottom(px(menu_placement.trigger_offset)),
            });
        div().flex_none().child(popover).into_any_element()
    }

    fn render_composer_terminal_menu(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let tooltip = if self.composer_terminals.is_empty() {
            "Create Composer terminal"
        } else {
            "Switch to terminal mode"
        };
        Button::new("composer-terminal-menu")
            .ghost()
            .compact()
            .size(px(32.0))
            .icon(IconName::SquareTerminal)
            .tooltip(tooltip)
            .disabled(self.agent_action_pending || self.selected_session_id.is_none())
            .on_click(cx.listener(|this, _, window, cx| {
                this.switch_to_composer_terminal(window.window_handle(), window, cx)
            }))
            .into_any_element()
    }

    fn render_composer_terminal_tab(
        &mut self,
        terminal: TerminalSession,
        terminal_ids: Vec<TerminalId>,
        selected_id: Option<&TerminalId>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let terminal_id = terminal.id.clone();
        let terminal_id_string = terminal_id.as_str().to_string();
        let title = terminal_tab_title(&terminal, &self.ui_state.terminal_tab_titles);
        let active = selected_id == Some(&terminal_id);
        let other_ids = terminal_ids
            .iter()
            .filter(|candidate| *candidate != &terminal_id)
            .cloned()
            .collect::<Vec<_>>();
        let mutation_pending = self.agent_action_pending;
        let drop_target = self.composer_terminal_drop_target.clone();
        let drag_target_id = terminal_id_string.clone();
        let drag_drop_id = terminal_id_string.clone();
        let drag_payload = ComposerTerminalDrag {
            terminal_id: terminal_id_string.clone(),
            label: title.clone().into(),
        };
        let hover_group: SharedString =
            format!("composer-terminal-tab:{terminal_id_string}").into();
        let select_id = terminal_id.clone();
        let keyboard_select_id = terminal_id.clone();
        let close_id = terminal_id.clone();
        let middle_close_id = terminal_id.clone();
        let context_entity = cx.weak_entity();
        let context_close_id = terminal_id.clone();
        let context_other_ids = other_ids.clone();
        let context_all_ids = terminal_ids.clone();
        let context_rename_id = terminal_id.clone();

        h_flex()
            .id(format!("composer-terminal-tab:{terminal_id_string}"))
            .h_full()
            .min_w(px(120.0))
            .max_w(px(220.0))
            .flex_none()
            .relative()
            .items_center()
            .gap_1p5()
            .px_2()
            .border_r_1()
            .border_color(cx.theme().border.opacity(0.72))
            .cursor_pointer()
            .focusable()
            .tab_stop(true)
            .role(Role::Button)
            .aria_label(title.clone())
            .aria_selected(active)
            .group(hover_group.clone())
            .text_xs()
            .text_color(if active {
                cx.theme().foreground
            } else {
                cx.theme().muted_foreground
            })
            .bg(if active {
                cx.theme().background
            } else {
                cx.theme().transparent
            })
            .hover(|style| {
                style
                    .bg(cx
                        .theme()
                        .background
                        .opacity(if active { 1.0 } else { 0.62 }))
                    .text_color(cx.theme().foreground)
            })
            .focus_visible(|style| {
                style.shadow(vec![
                    gpui::BoxShadow::new(px(0.0), px(0.0), cx.theme().ring).spread_radius(px(1.0)),
                ])
            })
            .on_click(cx.listener(move |this, _, window, cx| {
                this.select_composer_terminal(select_id.clone(), window, cx)
            }))
            .on_key_down(cx.listener(move |this, event: &KeyDownEvent, window, cx| {
                if event.keystroke.key == "enter" || event.keystroke.key == "space" {
                    this.select_composer_terminal(keyboard_select_id.clone(), window, cx);
                    cx.stop_propagation();
                }
            }))
            .on_mouse_down(
                MouseButton::Middle,
                cx.listener(move |this, _, _, cx| {
                    this.kill_composer_terminal(middle_close_id.clone(), cx);
                    cx.stop_propagation();
                }),
            )
            .on_drag(drag_payload, |drag, _, _, cx| cx.new(|_| drag.clone()))
            .on_drag_move(cx.listener(
                move |this, event: &DragMoveEvent<ComposerTerminalDrag>, _, cx| {
                    let drag = event.drag(cx);
                    let next = (drag.terminal_id != drag_target_id).then_some(
                        ComposerTerminalDropTarget {
                            terminal_id: drag_target_id.clone(),
                            after: event.event.position.x >= event.bounds.center().x,
                        },
                    );
                    if this.composer_terminal_drop_target != next {
                        this.composer_terminal_drop_target = next;
                        cx.notify();
                    }
                },
            ))
            .on_drop(
                cx.listener(move |this, drag: &ComposerTerminalDrag, _, cx| {
                    let target = this.composer_terminal_drop_target.take();
                    if let Some(target) = target
                        && target.terminal_id == drag_drop_id
                    {
                        this.move_composer_terminal_relative(
                            &drag.terminal_id,
                            &target.terminal_id,
                            target.after,
                            cx,
                        );
                    } else {
                        cx.notify();
                    }
                }),
            )
            .child(
                Icon::new(IconName::SquareTerminal)
                    .size(px(14.0))
                    .flex_none(),
            )
            .child(div().min_w_0().flex_1().truncate().child(title.clone()))
            .child(
                div()
                    .size(px(22.0))
                    .flex_none()
                    .opacity(if active { 0.72 } else { 0.0 })
                    .group_hover(&hover_group, |style| style.opacity(1.0))
                    .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                    .on_mouse_down(MouseButton::Middle, |_, _, cx| cx.stop_propagation())
                    .child(
                        Button::new(format!("close-composer-terminal:{terminal_id_string}"))
                            .xsmall()
                            .ghost()
                            .compact()
                            .size(px(22.0))
                            .icon(IconName::Close)
                            .tooltip(format!(
                                "{}{}",
                                locale::text("Close ", "关闭", "關閉"),
                                title
                            ))
                            .disabled(mutation_pending)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.kill_composer_terminal(close_id.clone(), cx);
                                cx.stop_propagation();
                            })),
                    ),
            )
            .when(active, |tab| {
                tab.child(
                    div()
                        .absolute()
                        .bottom_0()
                        .left(px(8.0))
                        .right(px(8.0))
                        .h(px(2.0))
                        .rounded_full()
                        .bg(cx.theme().primary),
                )
            })
            .when_some(
                (cx.has_active_drag())
                    .then_some(drop_target)
                    .flatten()
                    .filter(|target| target.terminal_id == terminal_id_string)
                    .map(|target| target.after),
                |tab, after| {
                    tab.child(
                        div()
                            .absolute()
                            .top(px(4.0))
                            .bottom(px(4.0))
                            .w(px(2.0))
                            .rounded_full()
                            .bg(cx.theme().drag_border)
                            .map(|line| if after { line.right_0() } else { line.left_0() }),
                    )
                },
            )
            .context_menu(move |menu, _, _| {
                let close_entity = context_entity.clone();
                let close_id = context_close_id.clone();
                let other_entity = context_entity.clone();
                let other_ids = context_other_ids.clone();
                let all_entity = context_entity.clone();
                let all_ids = context_all_ids.clone();
                let rename_entity = context_entity.clone();
                let rename_id = context_rename_id.clone();
                menu.item(
                    PopupMenuItem::new(locale::text("Close terminal", "关闭终端", "關閉終端機"))
                        .icon(IconName::Close)
                        .disabled(mutation_pending)
                        .on_click(move |_, _, cx| {
                            let _ = close_entity.update(cx, |this, cx| {
                                this.kill_composer_terminal(close_id.clone(), cx)
                            });
                        }),
                )
                .item(
                    PopupMenuItem::new(locale::text(
                        "Close other terminals",
                        "关闭其他终端",
                        "關閉其他終端機",
                    ))
                    .disabled(mutation_pending || other_ids.is_empty())
                    .on_click(move |_, _, cx| {
                        let ids = other_ids.clone();
                        let _ = other_entity
                            .update(cx, |this, cx| this.kill_composer_terminals(ids, cx));
                    }),
                )
                .item(
                    PopupMenuItem::new(locale::text(
                        "Close all terminals",
                        "关闭所有终端",
                        "關閉所有終端機",
                    ))
                    .disabled(mutation_pending || all_ids.is_empty())
                    .on_click(move |_, _, cx| {
                        let ids = all_ids.clone();
                        let _ =
                            all_entity.update(cx, |this, cx| this.kill_composer_terminals(ids, cx));
                    }),
                )
                .separator()
                .item(
                    PopupMenuItem::new(locale::text(
                        "Rename terminal",
                        "重命名终端",
                        "重新命名終端機",
                    ))
                    .on_click(move |_, window, cx| {
                        let _ = rename_entity.update(cx, |this, cx| {
                            this.prompt_rename_composer_terminal(rename_id.clone(), window, cx)
                        });
                    }),
                )
            })
            .into_any_element()
    }

    fn render_composer_terminal(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let terminals = order_terminal_sessions(
            self.composer_terminals.clone(),
            &self.ui_state.terminal.tab_order,
        );
        let terminal_ids = terminals
            .iter()
            .map(|terminal| terminal.id.clone())
            .collect::<Vec<_>>();
        let selected_id = self.selected_composer_terminal_id.clone();
        let selected_terminal = selected_id.as_ref().and_then(|selected| {
            terminals
                .iter()
                .find(|terminal| &terminal.id == selected)
                .cloned()
        });
        let selected_surface = selected_id.as_ref().and_then(|selected| {
            self.composer_terminal_surfaces
                .get(selected.as_str())
                .cloned()
        });
        let selected_shell = selected_terminal
            .as_ref()
            .map(|terminal| terminal.shell.clone())
            .unwrap_or_default();
        let selected_shell_label = if selected_shell.is_empty() {
            "Shell".to_string()
        } else {
            terminal_shell_label(&selected_shell)
        };
        let shell_options = composer_terminal_shell_options(
            (!selected_shell.is_empty()).then_some(selected_shell.as_str()),
        );
        let shell_entity = cx.weak_entity();
        let shell_terminal_id = selected_id.clone();
        let selected_shell_path = selected_shell.clone();
        let card_color = theme::semantic_color("card", cx.theme().is_dark());
        let shell_menu = Button::new("composer-terminal-shell")
            .xsmall()
            .ghost()
            .max_w(px(260.0))
            .tooltip(if selected_shell.is_empty() {
                locale::text(
                    "Select a terminal shell",
                    "选择终端 Shell",
                    "選擇終端機 Shell",
                )
                .to_string()
            } else {
                selected_shell.clone()
            })
            .disabled(
                self.agent_action_pending || selected_id.is_none() || shell_options.is_empty(),
            )
            .child(
                h_flex()
                    .min_w_0()
                    .gap_2()
                    .child(Icon::new(IconName::SquareTerminal).small())
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_xs()
                            .child(selected_shell_label),
                    )
                    .child(Icon::new(IconName::ChevronDown).size(px(13.0))),
            )
            .dropdown_menu(move |menu, _, _| {
                let mut menu = menu;
                for (label, path) in &shell_options {
                    let entity = shell_entity.clone();
                    let terminal_id = shell_terminal_id.clone();
                    let shell = path.clone();
                    menu = menu.item(
                        PopupMenuItem::new(format!("{label}  {path}"))
                            .checked(path == &selected_shell_path)
                            .on_click(move |_, _, cx| {
                                if let Some(terminal_id) = terminal_id.clone() {
                                    let _ = entity.update(cx, |this, cx| {
                                        this.switch_composer_terminal_shell(
                                            terminal_id,
                                            shell.clone(),
                                            cx,
                                        )
                                    });
                                }
                            }),
                    );
                }
                menu
            });
        let tabs = terminals
            .iter()
            .cloned()
            .map(|terminal| {
                self.render_composer_terminal_tab(
                    terminal,
                    terminal_ids.clone(),
                    selected_id.as_ref(),
                    cx,
                )
            })
            .collect::<Vec<_>>();
        let (min_terminal_height, max_terminal_height) = self.composer_terminal_height_limits();
        let terminal_height = self
            .composer_terminal_height
            .clamp(min_terminal_height, max_terminal_height);
        let content_max_width = session_content_max_width(self.ui_state.session.content_width);
        let resize_handle = if self.composer_terminal_expanded {
            None
        } else {
            Some(self.render_composer_terminal_resize_handle(cx))
        };

        v_flex()
            .id("agent-composer-terminal")
            .relative()
            .when(!self.composer_terminal_expanded, |this| this.flex_none())
            .when(self.composer_terminal_expanded, |this| {
                this.flex_1().min_h_0().pt_4()
            })
            .items_center()
            .bg(cx.theme().background)
            .px_4()
            .py_2()
            .when_some(resize_handle, |this, handle| this.child(handle))
            .child(
                v_flex()
                    .w_full()
                    .when_some(content_max_width, |this, max_width| {
                        this.max_w(px(max_width))
                    })
                    .when(!self.composer_terminal_expanded, |this| {
                        this.h(px(terminal_height))
                    })
                    .when(self.composer_terminal_expanded, |this| {
                        this.flex_1().min_h_0()
                    })
                    .min_w_0()
                    .overflow_hidden()
                    .rounded(px(8.0))
                    .border_1()
                    .border_color(cx.theme().border)
                    .bg(card_color)
                    .child(
                        h_flex()
                            .h(px(38.0))
                            .flex_none()
                            .min_w_0()
                            .bg(cx.theme().muted.opacity(0.24))
                            .border_b_1()
                            .border_color(cx.theme().border)
                            .child(
                                h_flex()
                                    .h_full()
                                    .min_w_0()
                                    .flex_1()
                                    .overflow_x_scrollbar()
                                    .children(tabs),
                            )
                            .child(
                                Button::new("new-composer-terminal")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .h_full()
                                    .w(px(38.0))
                                    .rounded_none()
                                    .border_l_1()
                                    .border_color(cx.theme().border)
                                    .icon(IconName::Plus)
                                    .tooltip(locale::text("New terminal", "新建终端", "新增終端機"))
                                    .disabled(
                                        self.agent_action_pending
                                            || self.selected_session_id.is_none(),
                                    )
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.create_composer_terminal(window.window_handle(), cx)
                                    })),
                            ),
                    )
                    .child(
                        h_flex()
                            .h(px(34.0))
                            .flex_none()
                            .min_w_0()
                            .items_center()
                            .gap_2()
                            .border_b_1()
                            .border_color(cx.theme().border)
                            .px_2()
                            .child(shell_menu)
                            .child(div().flex_1())
                            .child(
                                Button::new("back-to-conversation")
                                    .xsmall()
                                    .ghost()
                                    .icon(IconName::ArrowLeft)
                                    .label(locale::text(
                                        "Back to conversation",
                                        "返回对话框",
                                        "返回對話框",
                                    ))
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.composer_terminal_mode = false;
                                        this.sync_composer_terminal_surface_activity(cx);
                                        cx.notify();
                                    })),
                            )
                            .child(
                                Button::new("toggle-composer-terminal-expanded")
                                    .xsmall()
                                    .ghost()
                                    .compact()
                                    .icon(if self.composer_terminal_expanded {
                                        IconName::Minimize
                                    } else {
                                        IconName::Maximize
                                    })
                                    .tooltip(if self.composer_terminal_expanded {
                                        locale::text("Collapse terminal", "收起终端", "收合終端機")
                                    } else {
                                        locale::text("Expand terminal", "展开终端", "展開終端機")
                                    })
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.composer_terminal_expanded =
                                            !this.composer_terminal_expanded;
                                        cx.notify();
                                    })),
                            ),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_h_0()
                            .min_w_0()
                            .when_some(selected_surface, |surface, terminal| {
                                surface
                                    .child(terminal.cached(StyleRefinement::default().size_full()))
                            })
                            .when(selected_terminal.is_none(), |surface| {
                                surface.child(
                                    v_flex()
                                        .size_full()
                                        .items_center()
                                        .justify_center()
                                        .gap_2()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(locale::text(
                                            "No Composer terminal",
                                            "暂无编辑器终端",
                                            "暫無編輯器終端機",
                                        ))
                                        .child(
                                            Button::new("create-first-composer-terminal")
                                                .small()
                                                .primary()
                                                .icon(IconName::Plus)
                                                .label(locale::text(
                                                    "New terminal",
                                                    "新建终端",
                                                    "新增終端機",
                                                ))
                                                .disabled(
                                                    self.agent_action_pending
                                                        || self.selected_session_id.is_none(),
                                                )
                                                .on_click(cx.listener(|this, _, window, cx| {
                                                    this.create_composer_terminal(
                                                        window.window_handle(),
                                                        cx,
                                                    )
                                                })),
                                        ),
                                )
                            }),
                    ),
            )
            .into_any_element()
    }

    fn render_composer_terminal_resize_handle(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let resize_active = self.composer_terminal_resize_drag.is_some();
        let (min_height, max_height) = self.composer_terminal_height_limits();
        let drag_target = cx.weak_entity();
        div()
            .id("composer-terminal-resize-handle")
            .role(Role::Splitter)
            .aria_label(locale::text(
                "Resize terminal height",
                "调整终端高度",
                "調整終端機高度",
            ))
            .aria_orientation(Orientation::Vertical)
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .h(px(COMPOSER_TERMINAL_RESIZE_HANDLE_HEIGHT_PX))
            .cursor_row_resize()
            .group("composer-terminal-resize-handle")
            .occlude()
            .when(resize_active, |this| {
                this.bg(cx.theme().drag_border.opacity(0.14))
            })
            .hover(|style| style.bg(cx.theme().drag_border.opacity(0.10)))
            .flex()
            .items_center()
            .justify_center()
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|_, _: &MouseDownEvent, window, cx| {
                    window.prevent_default();
                    cx.stop_propagation();
                }),
            )
            .on_drag(ComposerTerminalResizeDrag, move |_, _, window, cx| {
                let start_window_y = f32::from(window.mouse_position().y);
                let _ = drag_target.update(cx, |this, cx| {
                    this.composer_terminal_resize_drag = Some(ComposerTerminalResizeDragState {
                        start_window_y,
                        start_height: this.composer_terminal_height.clamp(min_height, max_height),
                        min_height,
                        max_height,
                    });
                    cx.notify();
                });
                cx.new(|_| ComposerTerminalResizeDrag)
            })
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| this.finish_composer_terminal_resize(cx)),
            )
            .on_mouse_up_out(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| this.finish_composer_terminal_resize(cx)),
            )
            .child(
                div()
                    .w(px(48.0))
                    .h(px(3.0))
                    .rounded_full()
                    .bg(cx.theme().border)
                    .group_hover("composer-terminal-resize-handle", |style| {
                        style.bg(cx.theme().drag_border.opacity(0.78))
                    }),
            )
            .into_any_element()
    }

    fn render_inline_composer_attachments(&mut self, cx: &mut Context<Self>) -> Vec<AnyElement> {
        if !matches!(
            self.runtime_status,
            RuntimeStatus::Starting | RuntimeStatus::Ready
        ) {
            return Vec::new();
        }
        let (input, attachments, input_bounds) = if self.composer_queue_editing_id.is_some() {
            (
                self.composer_queue_edit_input.clone(),
                self.composer_queue_edit_attachments.clone(),
                self.composer_queue_edit_geometry.input_bounds,
            )
        } else if let Some(edit) = self.inline_user_message_edit.as_ref() {
            (
                self.user_message_edit_input.clone(),
                edit.attachments.clone(),
                edit.geometry.input_bounds,
            )
        } else if self.new_session_open {
            (
                self.new_session_input.clone(),
                self.new_session_attachments.clone(),
                self.new_session_composer_geometry.input_bounds,
            )
        } else if self.ui_state.workbench.active_tab == "agent"
            && !self.composer_terminal_mode
            && self.selected_session_id.is_some()
        {
            (
                self.composer_input.clone(),
                self.composer_attachments.clone(),
                self.composer_geometry.input_bounds,
            )
        } else {
            return Vec::new();
        };
        let Some(input_bounds) = input_bounds else {
            return Vec::new();
        };
        if attachments.is_empty() {
            return Vec::new();
        }

        let text = input.read(cx).value().to_string();
        let visible_rows = input.read(cx).visible_row_range();
        let (preview_width, preview_height) = composer_image_hover_preview_max_size(
            self.last_visibility.layout.viewport_width as f32,
            self.last_visibility.layout.viewport_height as f32,
        );
        attachments
            .into_iter()
            .filter_map(|inline_attachment| {
                let range = inline_attachment.range_in(&text)?;
                let row = composer_buffer_row_for_offset(&text, range.start);
                if !visible_rows
                    .as_ref()
                    .is_some_and(|rows| rows.contains(&row))
                {
                    return None;
                }
                let bounds = input.read(cx).range_to_bounds(&range)?;
                if !composer_attachment_bounds_are_visible(bounds, input_bounds) {
                    return None;
                }
                let attachment = inline_attachment.attachment;
                let attachment_id = attachment.id.clone();
                let label = attachment.label.clone();
                let is_image = attachment.is_image();
                let preview_attachment = attachment.clone();
                let tab_attachment = attachment.clone();
                let tab_path = (!is_image)
                    .then(|| self.composer_attachment_tab_path(&attachment))
                    .flatten();
                let preview_source = attachment.path.as_ref().filter(|_| is_image).map(|path| {
                    Arc::<std::path::Path>::from(std::path::PathBuf::from(path).into_boxed_path())
                });
                let token_width = f32::from(bounds.size.width).max(24.0);
                let action_label = format!(
                    "{}: {label}",
                    if is_image {
                        locale::text("Preview image", "预览图片", "預覽圖片")
                    } else {
                        locale::text("Open attachment", "打开附件", "開啟附件")
                    }
                );

                Some(
                    h_flex()
                        .id(format!("inline-composer-attachment-{attachment_id}"))
                        .absolute()
                        .left(bounds.origin.x)
                        .top(bounds.origin.y)
                        .w(px(token_width))
                        .h(bounds.size.height)
                        .min_w_0()
                        .items_center()
                        .gap(px(5.5))
                        .overflow_hidden()
                        .rounded(px(6.0))
                        .border_1()
                        .border_color(cx.theme().border)
                        .bg(cx.theme().muted)
                        .px(px(7.0))
                        .text_sm()
                        .font_weight(FontWeight(600.0))
                        .text_color(cx.theme().foreground)
                        .role(Role::Button)
                        .aria_label(action_label)
                        .hover(|style| {
                            style
                                .bg(cx.theme().accent)
                                .border_color(cx.theme().primary.opacity(0.45))
                                .text_color(cx.theme().accent_foreground)
                        })
                        .child(
                            if is_image {
                                Icon::default().path("icons/vibex/image.svg")
                            } else {
                                Icon::new(IconName::File)
                            }
                            .size(px(13.0))
                            .text_color(cx.theme().foreground.opacity(0.80)),
                        )
                        .child(div().min_w_0().flex_1().truncate().child(label.clone()))
                        .when_some(preview_source, |this, image_source| {
                            let tooltip_source = image_source.clone();
                            this.cursor_pointer()
                                .tooltip(move |window, cx| {
                                    let image_source = tooltip_source.clone();
                                    Tooltip::element(move |_, cx| {
                                        div()
                                            .max_w(px(preview_width
                                                - COMPOSER_IMAGE_HOVER_PREVIEW_PADDING * 2.0))
                                            .max_h(px(preview_height
                                                - COMPOSER_IMAGE_HOVER_PREVIEW_PADDING * 2.0))
                                            .overflow_hidden()
                                            .rounded(px(9.0))
                                            .bg(cx.theme().popover)
                                            .child(
                                                img(image_source.clone())
                                                    .max_w_full()
                                                    .max_h(px(preview_height
                                                        - COMPOSER_IMAGE_HOVER_PREVIEW_PADDING
                                                            * 2.0))
                                                    .object_fit(ObjectFit::Contain),
                                            )
                                    })
                                    .m_0()
                                    .rounded(px(12.0))
                                    .p(px(6.0))
                                    .shadow_lg()
                                    .build(window, cx)
                                })
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    this.open_attachment_preview(
                                        preview_attachment.clone(),
                                        true,
                                        window,
                                        cx,
                                    )
                                }))
                        })
                        .when_some(tab_path, |this, _| {
                            this.cursor_pointer().on_click(cx.listener(
                                move |this, _, window, cx| {
                                    this.open_composer_attachment_in_tab(
                                        &tab_attachment,
                                        window,
                                        cx,
                                    )
                                },
                            ))
                        })
                        .into_any_element(),
                )
            })
            .collect()
    }

    fn render_attachment_image_preview(&mut self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let preview = self.attachment_image_preview.clone()?;
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let layout = attachment_image_preview_layout(
            preview.intrinsic_size,
            preview.zoom,
            viewport_width,
            viewport_height,
        );
        let image_width = layout.image_width;
        let image_height = layout.image_height;
        let (pan_x, pan_y) = layout.clamp_pan(preview.pan_x, preview.pan_y);
        let can_pan = layout.can_pan();
        let dragging = preview.drag.is_some();
        let zoom_label = format!("{}%", (preview.zoom * 100.0).round() as u32);
        let save_source = preview.attachment.path.clone().unwrap_or_default();
        let save_label = preview.attachment.label.clone();
        let copy_source = save_source.clone();
        let copy_mime_type = preview.attachment.mime_type.clone();
        let copy_entity = cx.weak_entity();
        let image_source = preview.image_source;
        let rendered_image = preview.edited_image;
        let image_element = rendered_image
            .map(|image| {
                img(image)
                    .size_full()
                    .object_fit(ObjectFit::Contain)
                    .into_any_element()
            })
            .unwrap_or_else(|| {
                img(image_source)
                    .size_full()
                    .object_fit(ObjectFit::Contain)
                    .into_any_element()
            });
        let editable = preview.editable;
        let editing = preview.editing;
        let selected_tool = preview.tool;
        let can_undo = preview
            .edit_session
            .as_ref()
            .is_some_and(|session| session.can_undo());
        let can_redo = preview
            .edit_session
            .as_ref()
            .is_some_and(|session| session.can_redo());
        let text_input = self.image_editor_text_input.clone();

        Some(
            div()
                .id("attachment-image-preview")
                .absolute()
                .inset_0()
                .occlude()
                .overflow_hidden()
                .bg(gpui::black().opacity(0.80))
                .on_mouse_down(
                    MouseButton::Left,
                    cx.listener(|this, _, _, cx| {
                        if this
                            .attachment_image_preview
                            .as_ref()
                            .is_some_and(|preview| preview.editing)
                        {
                            cx.stop_propagation();
                        } else {
                            this.close_attachment_preview(cx);
                        }
                    }),
                )
                .on_mouse_move(cx.listener(|this, event: &MouseMoveEvent, window, cx| {
                    if event.dragging()
                        && this
                            .attachment_image_preview
                            .as_ref()
                            .is_some_and(|preview| preview.editing && preview.edit_drag.is_some())
                    {
                        this.update_attachment_edit_gesture(
                            f32::from(event.position.x),
                            f32::from(event.position.y),
                            cx,
                        );
                        window.prevent_default();
                        cx.stop_propagation();
                    } else if event.dragging()
                        && this
                            .attachment_image_preview
                            .as_ref()
                            .is_some_and(|preview| preview.drag.is_some())
                    {
                        this.update_attachment_preview_drag(
                            f32::from(event.position.x),
                            f32::from(event.position.y),
                            cx,
                        );
                        window.prevent_default();
                        cx.stop_propagation();
                    }
                }))
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(|this, _, _, cx| {
                        if this
                            .attachment_image_preview
                            .as_ref()
                            .is_some_and(|preview| preview.edit_drag.is_some())
                        {
                            this.finish_attachment_edit_gesture(cx);
                        } else {
                            this.finish_attachment_preview_drag(cx);
                        }
                    }),
                )
                .on_mouse_up_out(
                    MouseButton::Left,
                    cx.listener(|this, _, _, cx| {
                        if this
                            .attachment_image_preview
                            .as_ref()
                            .is_some_and(|preview| preview.edit_drag.is_some())
                        {
                            this.finish_attachment_edit_gesture(cx);
                        } else {
                            this.finish_attachment_preview_drag(cx);
                        }
                    }),
                )
                .on_scroll_wheel(cx.listener(|this, event: &ScrollWheelEvent, _, cx| {
                    let y = match event.delta {
                        ScrollDelta::Lines(point) => point.y,
                        ScrollDelta::Pixels(point) => f32::from(point.y),
                    };
                    if y != 0.0 {
                        this.adjust_attachment_preview_zoom(if y > 0.0 { 0.12 } else { -0.12 }, cx);
                    }
                    cx.stop_propagation();
                }))
                .child(
                    div()
                        .absolute()
                        .inset_0()
                        .flex()
                        .items_center()
                        .justify_center()
                        .overflow_hidden()
                        .px(px(IMAGE_PREVIEW_HORIZONTAL_PADDING))
                        .pt(px(IMAGE_PREVIEW_VERTICAL_PADDING))
                        .pb(px(IMAGE_PREVIEW_VERTICAL_PADDING))
                        .child(
                            div()
                                .flex_none()
                                .w(px(image_width))
                                .h(px(image_height))
                                .relative()
                                .left(px(pan_x))
                                .top(px(pan_y))
                                .when(editing, |this| this.cursor_crosshair())
                                .when(can_pan && !editing && !dragging, |this| this.cursor_grab())
                                .when(can_pan && !editing && dragging, |this| {
                                    this.cursor_grabbing()
                                })
                                .on_mouse_down(
                                    MouseButton::Left,
                                    cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                                        if this
                                            .attachment_image_preview
                                            .as_ref()
                                            .is_some_and(|preview| preview.editing)
                                        {
                                            this.begin_attachment_edit_gesture(
                                                f32::from(event.position.x),
                                                f32::from(event.position.y),
                                                cx,
                                            );
                                        } else if can_pan {
                                            this.begin_attachment_preview_drag(
                                                f32::from(event.position.x),
                                                f32::from(event.position.y),
                                                cx,
                                            );
                                        }
                                        window.prevent_default();
                                        cx.stop_propagation();
                                    }),
                                )
                                .context_menu(move |menu, _, _| {
                                    let copy_entity = copy_entity.clone();
                                    let source = copy_source.clone();
                                    let mime_type = copy_mime_type.clone();
                                    menu.item(
                                        PopupMenuItem::new(locale::text(
                                            "Copy image",
                                            "复制图片",
                                            "複製圖片",
                                        ))
                                        .icon(IconName::Copy)
                                        .on_click(
                                            move |_, _, cx| {
                                                let _ = copy_entity.update(cx, |this, cx| {
                                                    this.copy_attachment_preview_image(
                                                        &source,
                                                        mime_type.as_deref(),
                                                        cx,
                                                    );
                                                });
                                            },
                                        ),
                                    )
                                })
                                .child(image_element),
                        ),
                )
                .child(
                    h_flex()
                        .absolute()
                        .top(px(16.0))
                        .right(px(16.0))
                        .items_center()
                        .gap_2()
                        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                        .when(editable && !editing, |this| {
                            this.child(
                                Button::new("edit-attachment-preview")
                                    .ghost()
                                    .compact()
                                    .size(px(40.0))
                                    .rounded(gpui_component::button::ButtonRounded::Size(px(999.0)))
                                    .bg(cx.theme().foreground.opacity(0.12))
                                    .text_color(cx.theme().foreground)
                                    .icon(Icon::default().path("icons/vibex/pencil.svg"))
                                    .tooltip(locale::text("Edit image", "编辑图片", "編輯圖片"))
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.toggle_attachment_editor(cx)
                                    })),
                            )
                        })
                        .when(editing, |this| {
                            this.child(
                                h_flex()
                                    .items_center()
                                    .gap(px(2.0))
                                    .rounded(px(10.0))
                                    .bg(cx.theme().foreground.opacity(0.12))
                                    .p(px(3.0))
                                    .children(ImageEditTool::ALL.into_iter().map(|tool| {
                                        let selected = selected_tool == tool;
                                        Button::new(format!("attachment-edit-tool-{}", tool.id()))
                                            .ghost()
                                            .compact()
                                            .size(px(32.0))
                                            .when(selected, |button| button.primary())
                                            .icon(match tool {
                                                ImageEditTool::Crop => {
                                                    Icon::default().path("icons/vibex/scissors.svg")
                                                }
                                                ImageEditTool::Brush => {
                                                    Icon::default().path("icons/vibex/pencil.svg")
                                                }
                                                ImageEditTool::Text => {
                                                    Icon::new(IconName::CaseSensitive)
                                                }
                                                ImageEditTool::Rectangle => Icon::default()
                                                    .path("icons/vibex/rectangle-outline.svg"),
                                                ImageEditTool::Circle => Icon::default()
                                                    .path("icons/vibex/circle-outline.svg"),
                                                ImageEditTool::Arrow => {
                                                    Icon::new(IconName::ArrowUp)
                                                }
                                                ImageEditTool::Mosaic => {
                                                    Icon::default().path("icons/vibex/mosaic.svg")
                                                }
                                            })
                                            .tooltip(match tool {
                                                ImageEditTool::Crop => {
                                                    locale::text("Crop", "裁剪", "裁剪")
                                                }
                                                ImageEditTool::Brush => {
                                                    locale::text("Brush", "笔画", "筆畫")
                                                }
                                                ImageEditTool::Text => {
                                                    locale::text("Text", "文字", "文字")
                                                }
                                                ImageEditTool::Rectangle => {
                                                    locale::text("Rectangle", "矩形框", "矩形框")
                                                }
                                                ImageEditTool::Circle => {
                                                    locale::text("Circle", "圆形框", "圓形框")
                                                }
                                                ImageEditTool::Arrow => {
                                                    locale::text("Arrow", "箭头", "箭頭")
                                                }
                                                ImageEditTool::Mosaic => {
                                                    locale::text("Mosaic", "马赛克", "馬賽克")
                                                }
                                            })
                                            .on_click(cx.listener(move |this, _, _, cx| {
                                                this.select_attachment_edit_tool(tool, cx)
                                            }))
                                    }))
                                    .when(selected_tool == ImageEditTool::Text, |this| {
                                        this.child(
                                            div()
                                                .w(px(120.0))
                                                .h(px(30.0))
                                                .rounded(px(6.0))
                                                .bg(cx.theme().background)
                                                .child(
                                                    Input::new(&text_input)
                                                        .appearance(false)
                                                        .size_full(),
                                                ),
                                        )
                                    })
                                    .child(
                                        Button::new("undo-attachment-edit")
                                            .ghost()
                                            .compact()
                                            .size(px(32.0))
                                            .icon(IconName::Undo2)
                                            .disabled(!can_undo)
                                            .tooltip(locale::text(
                                                "Undo edit",
                                                "撤销编辑",
                                                "復原編輯",
                                            ))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.undo_attachment_edit(cx)
                                            })),
                                    )
                                    .child(
                                        Button::new("redo-attachment-edit")
                                            .ghost()
                                            .compact()
                                            .size(px(32.0))
                                            .icon(IconName::Redo2)
                                            .disabled(!can_redo)
                                            .tooltip(locale::text(
                                                "Redo edit",
                                                "重做编辑",
                                                "重做編輯",
                                            ))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.redo_attachment_edit(cx)
                                            })),
                                    )
                                    .child(
                                        Button::new("cancel-attachment-edit")
                                            .ghost()
                                            .compact()
                                            .size(px(32.0))
                                            .icon(IconName::Close)
                                            .tooltip(locale::text(
                                                "Cancel editing",
                                                "取消编辑",
                                                "取消編輯",
                                            ))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.cancel_attachment_editor(cx)
                                            })),
                                    )
                                    .child(
                                        Button::new("finish-attachment-edit")
                                            .primary()
                                            .compact()
                                            .size(px(32.0))
                                            .icon(IconName::Check)
                                            .tooltip(locale::text(
                                                "Finish editing",
                                                "完成编辑",
                                                "完成編輯",
                                            ))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.toggle_attachment_editor(cx)
                                            })),
                                    ),
                            )
                        })
                        .child(
                            Button::new("save-attachment-preview")
                                .ghost()
                                .compact()
                                .size(px(40.0))
                                .rounded(gpui_component::button::ButtonRounded::Size(px(999.0)))
                                .bg(cx.theme().foreground.opacity(0.12))
                                .text_color(cx.theme().foreground)
                                .icon(
                                    Icon::default()
                                        .path("icons/vibex/download.svg")
                                        .size(px(18.0)),
                                )
                                .tooltip(locale::text("Save image", "保存图片", "儲存圖片"))
                                .disabled(self.composer_attachment_task.is_some())
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.choose_attachment_save_copy(
                                        save_source.clone(),
                                        save_label.clone(),
                                        cx,
                                    )
                                })),
                        )
                        .child(
                            Button::new("close-attachment-preview")
                                .ghost()
                                .compact()
                                .size(px(40.0))
                                .rounded(gpui_component::button::ButtonRounded::Size(px(999.0)))
                                .bg(cx.theme().foreground.opacity(0.12))
                                .text_color(cx.theme().foreground)
                                .icon(IconName::Close)
                                .tooltip(locale::text(
                                    "Close image preview",
                                    "关闭图片预览",
                                    "關閉圖片預覽",
                                ))
                                .on_click(
                                    cx.listener(|this, _, _, cx| this.close_attachment_preview(cx)),
                                ),
                        ),
                )
                .child(
                    h_flex()
                        .absolute()
                        .left_0()
                        .right_0()
                        .bottom(px(24.0))
                        .justify_center()
                        .px_6()
                        .child(
                            h_flex()
                                .items_center()
                                .gap(px(5.0))
                                .rounded(px(999.0))
                                .border_1()
                                .border_color(cx.theme().border.opacity(0.80))
                                .bg(cx.theme().popover.opacity(0.72))
                                .p(px(5.0))
                                .shadow_lg()
                                .text_color(cx.theme().popover_foreground)
                                .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                                .child(
                                    Button::new("attachment-preview-zoom-out")
                                        .ghost()
                                        .compact()
                                        .size(px(32.0))
                                        .rounded(gpui_component::button::ButtonRounded::Size(px(
                                            999.0,
                                        )))
                                        .icon(IconName::Minus)
                                        .tooltip(locale::text("Zoom out", "缩小", "縮小"))
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.adjust_attachment_preview_zoom(-0.25, cx)
                                        })),
                                )
                                .child(
                                    Button::new("attachment-preview-reset-zoom")
                                        .ghost()
                                        .compact()
                                        .h(px(32.0))
                                        .min_w(px(68.0))
                                        .px(px(7.0))
                                        .label(zoom_label)
                                        .tooltip(locale::text("Reset zoom", "重置缩放", "重設縮放"))
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.set_attachment_preview_zoom(1.0, cx)
                                        })),
                                )
                                .child(
                                    Button::new("attachment-preview-zoom-in")
                                        .ghost()
                                        .compact()
                                        .size(px(32.0))
                                        .rounded(gpui_component::button::ButtonRounded::Size(px(
                                            999.0,
                                        )))
                                        .icon(IconName::Plus)
                                        .tooltip(locale::text("Zoom in", "放大", "放大"))
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.adjust_attachment_preview_zoom(0.25, cx)
                                        })),
                                ),
                        ),
                )
                .into_any_element(),
        )
    }

    fn render_conversation_find(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        if !self.conversation_find_open {
            return None;
        }
        let match_count = self.conversation_find_matches(cx).len();
        let current = if match_count == 0 {
            "0/0".to_string()
        } else {
            format!(
                "{}/{}",
                self.conversation_find_active_index + 1,
                match_count
            )
        };
        let previous_label = locale::text("Previous match", "上一项", "上一項");
        let next_label = locale::text("Next match", "下一项", "下一項");
        let close_label = locale::text("Close find", "关闭查找", "關閉尋找");
        Some(
            h_flex()
                .id("conversation-find-bar")
                .w_full()
                .flex_none()
                .justify_center()
                .border_b_1()
                .border_color(cx.theme().border)
                .bg(cx.theme().background)
                .px_4()
                .py_2()
                .child(
                    h_flex()
                        .w_full()
                        .max_w(px(720.0))
                        .items_center()
                        .gap_2()
                        .child(
                            div()
                                .h(px(34.0))
                                .min_w_0()
                                .flex_1()
                                .rounded(px(6.0))
                                .bg(cx.theme().muted.opacity(0.42))
                                .child(
                                    Input::new(&self.conversation_find)
                                        .h_full()
                                        .w_full()
                                        .appearance(false)
                                        .prefix(
                                            Icon::new(IconName::Search)
                                                .small()
                                                .text_color(cx.theme().muted_foreground),
                                        ),
                                ),
                        )
                        .child(
                            div()
                                .w(px(54.0))
                                .flex_none()
                                .text_center()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(current),
                        )
                        .child(
                            Button::new("conversation-find-previous")
                                .small()
                                .ghost()
                                .compact()
                                .size(px(32.0))
                                .icon(IconName::ArrowUp)
                                .tooltip(previous_label)
                                .disabled(match_count == 0)
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.select_next_conversation_find_match(-1, cx)
                                })),
                        )
                        .child(
                            Button::new("conversation-find-next")
                                .small()
                                .ghost()
                                .compact()
                                .size(px(32.0))
                                .icon(IconName::ArrowDown)
                                .tooltip(next_label)
                                .disabled(match_count == 0)
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.select_next_conversation_find_match(1, cx)
                                })),
                        )
                        .child(
                            Button::new("conversation-find-close")
                                .small()
                                .ghost()
                                .compact()
                                .size(px(32.0))
                                .icon(IconName::Close)
                                .tooltip(close_label)
                                .on_click(cx.listener(|this, _, window, cx| {
                                    this.close_conversation_find(window, cx)
                                })),
                        ),
                )
                .into_any_element(),
        )
    }

    fn render_timeline_turn(
        &mut self,
        turn: &TimelineConversationTurn,
        is_first: bool,
        is_last: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let strings = self.strings();
        let reasoning_display_mode = self.ui_state.session.reasoning_display_mode;
        let runtime_hover_group: SharedString = format!("timeline-runtime-{}", turn.id).into();
        let execution_attribution = self.timeline_turn_execution_attribution(turn);
        let runtime_attribution = if let Some(attribution) = execution_attribution.as_ref() {
            Some(self.render_timeline_runtime_header(&turn.id, attribution.clone(), cx))
        } else {
            let runtime = turn.runtime_attribution.as_ref().map(|attribution| {
                let runtime_label = attribution
                    .split(" · ")
                    .skip(1)
                    .collect::<Vec<_>>()
                    .join(" · ");
                div()
                    .min_w_0()
                    .truncate()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground.opacity(0.80))
                    .child(if runtime_label.is_empty() {
                        attribution.clone()
                    } else {
                        runtime_label
                    })
                    .into_any_element()
            });
            runtime
        };
        let process_expanded = timeline_turn_process_expanded(
            turn,
            self.timeline_process_expansion.get(&turn.id).copied(),
        );
        let process_collapsible = turn.complete
            || (timeline_turn_conclusion_row(turn).is_some() && !turn.process_rows.is_empty());
        let process_toggle_id = turn.id.clone();
        let agent_identity = execution_attribution
            .as_ref()
            .map(|attribution| self.agent_identity_for_label(&attribution.agent_label))
            .or_else(|| {
                turn.runtime_attribution.as_deref().and_then(|attribution| {
                    attribution
                        .split(" · ")
                        .next()
                        .filter(|label| !label.is_empty())
                        .map(str::to_owned)
                })
            });
        let render_header_agent_icon = |identity: &String| {
            div()
                .size(px(16.0))
                .flex_none()
                .child(runtime_agent_icon(identity))
                .into_any_element()
        };
        let duration = format_compact_duration(
            turn.started_at_ms,
            timeline_turn_duration_end(turn.complete, turn.ended_at_ms),
        );
        let header_label = format!("{} {duration}", strings.agent_worked_for);
        let mut content = v_flex()
            .id(turn.id.clone())
            .w_full()
            .min_w_0()
            .gap_3()
            .when(!is_first, |this| this.pt_5())
            .pb_5();

        if let Some(user_row) = turn.user_row.as_ref() {
            let user_message = self.render_user_message_row(
                user_row,
                Some(&turn.id),
                is_last,
                turn.complete,
                window,
                cx,
            );
            content = content.child(self.highlight_session_search_rows(
                std::slice::from_ref(user_row),
                user_message,
                cx,
            ));
        }

        let mut file_changes = if turn.complete && !self.rendering_child_agent_timeline() {
            self.render_turn_file_changes_card(turn, is_last, cx)
        } else {
            None
        };

        if !turn.process_rows.is_empty() || turn.conclusion_row.is_some() || !turn.complete {
            let mut response = v_flex()
                .w_full()
                .min_w_0()
                .gap_3()
                .group(runtime_hover_group.clone());
            let header_left = if process_collapsible {
                h_flex()
                    .id(format!("turn-process:{}", turn.id))
                    .items_center()
                    .gap(px(6.0))
                    .rounded_md()
                    .py_1()
                    .cursor_pointer()
                    .text_color(cx.theme().muted_foreground)
                    .hover(|style| style.text_color(cx.theme().foreground))
                    .when_some(agent_identity.as_ref(), |this, identity| {
                        this.child(render_header_agent_icon(identity))
                    })
                    .child(header_label)
                    .child(
                        Icon::new(if process_expanded {
                            IconName::ChevronDown
                        } else {
                            IconName::ChevronRight
                        })
                        .size(px(14.0)),
                    )
                    .tooltip({
                        let tooltip_text = if process_expanded {
                            strings.agent_collapse_process
                        } else {
                            strings.agent_expand_process
                        };
                        move |window, cx| Tooltip::new(tooltip_text).build(window, cx)
                    })
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.invalidate_timeline_turn_measurement(&process_toggle_id);
                        this.timeline_process_expansion
                            .insert(process_toggle_id.clone(), !process_expanded);
                        this.rebuild_timeline_sizes();
                        cx.notify();
                    }))
                    .into_any_element()
            } else {
                h_flex()
                    .items_center()
                    .gap(px(6.0))
                    .py_1()
                    .text_color(cx.theme().muted_foreground)
                    .when_some(agent_identity.as_ref(), |this, identity| {
                        this.child(render_header_agent_icon(identity))
                    })
                    .child(header_label)
                    .into_any_element()
            };
            response = response.child(
                v_flex()
                    .w_full()
                    .min_w_0()
                    .border_b_1()
                    .border_color(cx.theme().border.opacity(0.60))
                    .pb_2()
                    .child(
                        h_flex()
                            .w_full()
                            .min_w_0()
                            .items_center()
                            .justify_between()
                            .gap_2()
                            .text_sm()
                            .child(header_left)
                            .when_some(runtime_attribution, |this, attribution| {
                                this.child(
                                    div()
                                        .min_w_0()
                                        .opacity(0.0)
                                        .group_hover(runtime_hover_group, |style| {
                                            style.opacity(1.0)
                                        })
                                        .child(attribution),
                                )
                            }),
                    ),
            );
            if process_expanded {
                for row in self.render_timeline_process_rows(turn, window, cx) {
                    response = response.child(row);
                }
            }
            if let Some(conclusion_row) = timeline_turn_conclusion_row(turn) {
                let content_before_actions = file_changes.take();
                let answer_metadata = (!self.rendering_child_agent_timeline())
                    .then(|| {
                        self.render_agent_answer_metadata(
                            turn,
                            conclusion_row,
                            execution_attribution.as_ref(),
                            cx,
                        )
                    })
                    .flatten();
                response = response.child(self.render_timeline_row(
                    conclusion_row,
                    true,
                    content_before_actions,
                    answer_metadata,
                    window,
                    cx,
                ));
            } else if !turn.complete
                && !(reasoning_display_mode == ReasoningDisplayMode::Timeline
                    && turn
                        .process_rows
                        .iter()
                        .any(|row| row.kind == TimelineRowKind::Reasoning && row.streaming))
            {
                if reasoning_display_mode == ReasoningDisplayMode::LatestAtBottom
                    && let Some(reasoning) = turn.live_status.as_deref()
                {
                    response = response.child(self.render_live_reasoning(turn, reasoning, cx));
                } else {
                    let pending_label = if turn.pending_permission {
                        strings.agent_waiting_confirmation.to_string()
                    } else {
                        turn.live_status
                            .as_deref()
                            .unwrap_or(strings.agent_pending_response)
                            .to_string()
                    };
                    let pending_tooltip =
                        agent_progress_tooltip(&pending_label, strings.agent_pending_response);
                    response = response.child(render_agent_thinking_indicator(
                        &turn.id,
                        &agent_progress_label(&pending_label, strings.agent_pending_response),
                        &pending_tooltip,
                        cx,
                    ));
                }
            }
            content = content.child(response);
        }

        if let Some(file_changes) = file_changes {
            content = content.child(file_changes);
        }

        content.into_any_element()
    }

    fn render_turn_file_changes_card(
        &mut self,
        turn: &TimelineConversationTurn,
        is_latest_turn: bool,
        cx: &mut Context<Self>,
    ) -> Option<AnyElement> {
        let session = self.selected_session()?.clone();
        let mut summary = self.agent_turn_file_changes_cached(turn).as_ref().clone();
        if summary.files.is_empty() {
            return None;
        }
        if is_latest_turn {
            let code_workbench = self.code_workbench.read(cx);
            if let Some(status) = code_workbench.git_status()
                && status.workspace_id == session.workspace_id
            {
                apply_git_status_to_turn_file_changes(&mut summary, status);
            }
        }

        let expanded = self
            .timeline_file_changes_expansion
            .get(&turn.id)
            .copied()
            .unwrap_or(false);
        let visible_count = if expanded {
            summary.files.len()
        } else {
            summary.files.len().min(TURN_FILE_CHANGES_VISIBLE_COUNT)
        };
        let remaining_count = summary.files.len().saturating_sub(visible_count);
        let total_added = summary
            .files
            .iter()
            .map(|file| file.added_lines)
            .sum::<usize>();
        let total_removed = summary
            .files
            .iter()
            .map(|file| file.removed_lines)
            .sum::<usize>();
        let first_review = summary.files.iter().find_map(|file| {
            file.review_path
                .clone()
                .map(|path| (path, file.review_staged))
        });
        let card_bg = theme::semantic_color("card", cx.theme().is_dark());
        let title = format!(
            "{} {}",
            summary.files.len(),
            locale::text("files changed", "个文件变更", "個檔案變更")
        );
        let mut rows = v_flex().w_full().min_w_0();
        for (index, file) in summary.files.iter().take(visible_count).enumerate() {
            let review = file
                .review_path
                .clone()
                .map(|path| (path, file.review_staged));
            let row_id = format!("turn-file-change:{}:{index}", turn.id);
            let mut row = h_flex()
                .id(row_id)
                .w_full()
                .min_w_0()
                .h(px(36.0))
                .flex_none()
                .items_center()
                .gap_2()
                .px_3()
                .border_t_1()
                .border_color(cx.theme().border.opacity(0.72))
                .child(
                    Icon::default()
                        .path("icons/vibex/file-text.svg")
                        .size(px(14.0))
                        .flex_none()
                        .text_color(cx.theme().muted_foreground),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .truncate()
                        .text_sm()
                        .font_family(cx.theme().mono_font_family.clone())
                        .font_weight(code_font_weight(cx))
                        .child(file.display_path.clone()),
                )
                .when(file.removed_lines > 0, |this| {
                    this.child(
                        div()
                            .flex_none()
                            .text_xs()
                            .font_family(cx.theme().mono_font_family.clone())
                            .font_weight(code_font_weight(cx))
                            .text_color(cx.theme().danger)
                            .child(format!("-{}", file.removed_lines)),
                    )
                })
                .when(file.added_lines > 0, |this| {
                    this.child(
                        div()
                            .flex_none()
                            .text_xs()
                            .font_family(cx.theme().mono_font_family.clone())
                            .font_weight(code_font_weight(cx))
                            .text_color(cx.theme().success)
                            .child(format!("+{}", file.added_lines)),
                    )
                });
            if let Some((path, staged)) = review {
                let tooltip_text = locale::text("Review this file", "审查此文件", "檢閱此檔案");
                let aria_label = format!("{tooltip_text}: {}", file.display_path);
                row = row
                    .cursor_pointer()
                    .focusable()
                    .tab_stop(true)
                    .role(Role::Button)
                    .aria_label(aria_label)
                    .hover(|style| style.bg(cx.theme().muted.opacity(0.32)))
                    .focus_visible(|style| style.bg(cx.theme().muted.opacity(0.40)))
                    .tooltip(move |window, cx| Tooltip::new(tooltip_text).build(window, cx))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.review_turn_file_changes(path.clone(), staged, cx)
                    }));
            }
            rows = rows.child(row);
        }

        let turn_id = turn.id.clone();
        let resolved_locale = self.resolved_locale();
        let disclosure = (summary.files.len() > TURN_FILE_CHANGES_VISIBLE_COUNT).then(|| {
            let label = if expanded {
                locale::text("Show fewer", "收起", "收合").to_string()
            } else {
                match resolved_locale {
                    locale::ResolvedLocale::En => {
                        format!("Show {remaining_count} more files")
                    }
                    locale::ResolvedLocale::ZhCn => {
                        format!("再显示 {remaining_count} 个文件")
                    }
                    locale::ResolvedLocale::ZhTw => {
                        format!("再顯示 {remaining_count} 個檔案")
                    }
                }
            };
            Button::new(format!("toggle-turn-file-changes:{}", turn.id))
                .small()
                .ghost()
                .compact()
                .icon(if expanded {
                    IconName::ChevronUp
                } else {
                    IconName::ChevronDown
                })
                .label(label)
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.invalidate_timeline_turn_measurement(&turn_id);
                    this.timeline_file_changes_expansion
                        .insert(turn_id.clone(), !expanded);
                    this.rebuild_timeline_sizes();
                    cx.notify();
                }))
        });
        let has_disclosure = disclosure.is_some();
        let review_button = {
            let review = first_review.clone();
            Button::new(format!("review-turn-file-changes:{}", turn.id))
                .small()
                .primary()
                .icon(IconName::Eye)
                .label(locale::text("Review", "审查", "檢閱"))
                .disabled(review.is_none())
                .on_click(cx.listener(move |this, _, _, cx| {
                    if let Some((path, staged)) = review.as_ref() {
                        this.review_turn_file_changes(path.clone(), *staged, cx);
                    }
                }))
        };
        Some(
            v_flex()
                .id(format!("turn-file-changes-card:{}", turn.id))
                .w_full()
                .min_w_0()
                .flex_none()
                .overflow_hidden()
                .rounded_lg()
                .border_1()
                .border_color(cx.theme().border)
                .bg(card_bg.opacity(0.72))
                .child(
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .h(px(42.0))
                        .flex_none()
                        .items_center()
                        .gap_2()
                        .px_3()
                        .child(
                            Icon::new(IconName::File)
                                .size(px(15.0))
                                .flex_none()
                                .text_color(cx.theme().muted_foreground),
                        )
                        .child(div().min_w_0().flex_1().font_medium().child(title))
                        .when(total_removed > 0, |this| {
                            this.child(
                                div()
                                    .flex_none()
                                    .text_xs()
                                    .font_family(cx.theme().mono_font_family.clone())
                                    .font_weight(code_font_weight(cx))
                                    .text_color(cx.theme().danger)
                                    .child(format!("-{total_removed}")),
                            )
                        })
                        .when(total_added > 0, |this| {
                            this.child(
                                div()
                                    .flex_none()
                                    .text_xs()
                                    .font_family(cx.theme().mono_font_family.clone())
                                    .font_weight(code_font_weight(cx))
                                    .text_color(cx.theme().success)
                                    .child(format!("+{total_added}")),
                            )
                        }),
                )
                .child(rows)
                .child(
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .h(px(42.0))
                        .flex_none()
                        .items_center()
                        .justify_between()
                        .gap_2()
                        .px_2()
                        .border_t_1()
                        .border_color(cx.theme().border.opacity(0.72))
                        .when_some(disclosure, |this, disclosure| this.child(disclosure))
                        .when(!has_disclosure, |this| this.child(div().flex_1()))
                        .child(h_flex().items_center().gap_2().child(review_button)),
                )
                .into_any_element(),
        )
    }

    fn review_turn_file_changes(&mut self, path: String, staged: bool, cx: &mut Context<Self>) {
        let Some(session) = self.selected_session().cloned() else {
            return;
        };
        let review_ready = if let Some(runtime) = self.runtime.clone() {
            let workspace_id = session.workspace_id.clone();
            self.ui_state.workbench.selected_workspace_id = Some(workspace_id.as_str().to_string());
            let review_ready = self.code_workbench.update(cx, |workbench, cx| {
                workbench.sync_workspace(
                    runtime,
                    workspace_id.clone(),
                    std::path::PathBuf::from(session.workspace_root),
                    cx,
                );
                if !workbench.workspace_is_active(&workspace_id) {
                    return false;
                }
                workbench.set_git_mode(GitWorkbenchMode::Changes, cx);
                workbench.open_diff(GitSelectionKey { path, staged }, cx);
                true
            });
            self.queue_ui_state();
            review_ready
        } else {
            false
        };
        self.open_right_rail_mode(RightRailMode::Git, cx);
        if review_ready {
            self.reveal_code_preview(cx);
        }
    }

    fn timeline_turn_execution_attribution(
        &self,
        turn: &TimelineConversationTurn,
    ) -> Option<vibex_core::TurnExecutionAttributionView> {
        turn.runtime_attribution.as_ref()?;
        turn.process_rows
            .iter()
            .chain(turn.conclusion_row.iter())
            .find_map(|row| {
                self.timeline_row_latest_item(row)
                    .and_then(|item| item.execution_attribution.as_ref())
            })
            .cloned()
    }

