    fn render_agent_answer_metadata(
        &self,
        turn: &TimelineConversationTurn,
        row: &TimelineRow,
        attribution: Option<&vibex_core::TurnExecutionAttributionView>,
        cx: &App,
    ) -> Option<AnyElement> {
        if !turn.complete || row.kind != TimelineRowKind::AgentMessage || row.body.trim().is_empty()
        {
            return None;
        }
        let attribution = attribution?;
        let agent_identity = self.agent_identity_for_label(&attribution.agent_label);
        let muted_foreground = cx.theme().muted_foreground;
        let runtime_label = format!(
            "{} · {}",
            attribution.auth_source_label, attribution.model_label
        );
        let duration = format_compact_duration(
            turn.started_at_ms,
            timeline_turn_duration_end(turn.complete, turn.ended_at_ms),
        );
        let tooltip_label = attribution.agent_label.clone();
        Some(
            h_flex()
                .id(SharedString::from(format!(
                    "agent-answer-metadata:{}",
                    row.id
                )))
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .text_xs()
                .text_color(muted_foreground)
                .child(
                    div()
                        .id(SharedString::from(format!("agent-answer-logo:{}", row.id)))
                        .size(px(16.0))
                        .flex_none()
                        .child(runtime_agent_icon(&agent_identity))
                        .tooltip(move |window, cx| {
                            Tooltip::new(tooltip_label.clone()).build(window, cx)
                        }),
                )
                .child(div().min_w_0().truncate().child(runtime_label))
                .child(Icon::default().path("icons/vibex/clock.svg").size(px(14.0)))
                .child(div().flex_none().child(duration))
                .into_any_element(),
        )
    }

    fn render_timeline_process_rows(
        &mut self,
        turn: &TimelineConversationTurn,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Vec<AnyElement> {
        let mut elements = Vec::new();
        let mut row_index = 0;
        let mut group_index = 0;
        let enhanced_command_display = self.ui_state.session.enhanced_command_execution_display;
        let process_activity_groups = timeline_process_activity_groups_for_display(
            turn,
            enhanced_command_display,
            self.ui_state.session.enhanced_file_operation_display,
        );

        while row_index < turn.process_rows.len() {
            while process_activity_groups
                .get(group_index)
                .is_some_and(|group| group.end_row <= row_index)
            {
                group_index += 1;
            }
            if !self.rendering_child_agent_timeline()
                && enhanced_command_display
                && let (Some(command_row), Some(permission_row)) = (
                    turn.process_rows.get(row_index),
                    turn.process_rows.get(row_index + 1),
                )
                && self.command_permission_rows_are_linked(command_row, permission_row)
            {
                let pair_rows = &turn.process_rows[row_index..row_index + 2];
                let element =
                    self.render_command_execution_card(command_row, Some(permission_row), cx);
                elements.push(self.highlight_session_search_rows(pair_rows, element, cx));
                row_index += 2;
                continue;
            }
            let group = process_activity_groups.get(group_index).filter(|group| {
                group.start_row == row_index
                    && group.end_row <= turn.process_rows.len()
                    && group.end_row > group.start_row
            });
            if let Some(group) = group {
                let group_rows = &turn.process_rows[group.start_row..group.end_row];
                let group_element = self.render_process_activity_group(group, group_rows, cx);
                elements.push(self.highlight_session_search_rows(group_rows, group_element, cx));
                row_index = group.end_row;
                group_index += 1;
            } else {
                elements.push(self.render_timeline_row(
                    &turn.process_rows[row_index],
                    false,
                    None,
                    None,
                    window,
                    cx,
                ));
                row_index += 1;
            }
        }

        elements
    }

    fn command_permission_rows_are_linked(
        &self,
        command_row: &TimelineRow,
        permission_row: &TimelineRow,
    ) -> bool {
        command_row.kind == TimelineRowKind::Command
            && permission_row.kind == TimelineRowKind::PermissionRequest
            && command_row.turn_id.is_some()
            && command_row.turn_id == permission_row.turn_id
            && self
                .permission_request_for_row(permission_row)
                .is_some_and(|request| {
                    request.risk_category == vibex_core::PermissionRiskCategory::Command
                })
    }

    fn permission_request_for_row(
        &self,
        row: &TimelineRow,
    ) -> Option<vibex_core::PermissionRequest> {
        self.timeline_row_latest_item(row)
            .and_then(|item| match &item.payload {
                vibex_core::TimelinePayload::PermissionRequest(request) => Some(request.clone()),
                _ => None,
            })
    }

    fn elicitation_request_for_row(&self, row: &TimelineRow) -> Option<ElicitationRequest> {
        self.timeline_row_latest_item(row)
            .and_then(|item| match &item.payload {
                vibex_core::TimelinePayload::ElicitationRequest(request) => Some(request.clone()),
                _ => None,
            })
    }

    fn render_child_agent_status_badge(status: vibex_core::ToolCallStatus, cx: &App) -> AnyElement {
        let (label, color) = match status {
            vibex_core::ToolCallStatus::Started => ("Starting", cx.theme().warning),
            vibex_core::ToolCallStatus::Progress => ("Working", cx.theme().warning),
            vibex_core::ToolCallStatus::Completed => ("Completed", cx.theme().success),
            vibex_core::ToolCallStatus::Failed => ("Failed", cx.theme().danger),
        };
        div()
            .flex_none()
            .rounded(px(5.0))
            .bg(color.opacity(if cx.theme().is_dark() { 0.20 } else { 0.12 }))
            .px_2()
            .py(px(2.0))
            .text_xs()
            .font_medium()
            .text_color(color)
            .child(label)
            .into_any_element()
    }

    fn child_agent_session_label(&self, session_id: &VibexSessionId) -> String {
        self.child_agent_timelines
            .get(session_id.as_str())
            .and_then(|state| state.session.as_ref())
            .map(|session| session.title.clone())
            .filter(|title| !title.trim().is_empty())
            .unwrap_or_else(|| {
                let suffix = session_id
                    .as_str()
                    .chars()
                    .rev()
                    .take(8)
                    .collect::<Vec<_>>()
                    .into_iter()
                    .rev()
                    .collect::<String>();
                format!("Child Agent {suffix}")
            })
    }

    fn render_agent_delegation_card(
        &mut self,
        row: &TimelineRow,
        delegation: &TimelineDelegationProjection,
        surface_id: &str,
        nesting: u8,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let delegation_id = delegation.delegation_id.as_str().to_string();
        let child_session_id = delegation.child_session_id.clone();
        let expanded = self
            .child_agent_expanded_delegations
            .contains(&delegation_id);
        let title = delegation
            .agent_label
            .clone()
            .filter(|label| !label.trim().is_empty())
            .unwrap_or_else(|| "Child Agent".to_string());
        let agent_identity = self.agent_identity_for_label(&title);
        let card_id = format!("{surface_id}:delegation-card:{}", row.id);
        let toggle_id = format!("{card_id}:toggle");
        let preview_snapshot = if expanded {
            self.child_agent_timeline_snapshot(&child_session_id)
        } else {
            None
        };
        let hidden_count = preview_snapshot
            .as_ref()
            .filter(|snapshot| snapshot.error.is_none())
            .map(|snapshot| {
                snapshot
                    .rows
                    .len()
                    .saturating_sub(CHILD_AGENT_TIMELINE_PREVIEW_ROW_LIMIT)
            })
            .unwrap_or_default();
        let preview = preview_snapshot.map(|snapshot| {
            let preview_surface = format!("{surface_id}:delegation-preview:{delegation_id}");
            self.render_child_agent_timeline_content(
                snapshot,
                &preview_surface,
                true,
                nesting.saturating_add(1),
                cx,
            )
        });
        let toggle_delegation = delegation.clone();
        let title_session_id = child_session_id.clone();
        let mut header = h_flex()
            .w_full()
            .min_w_0()
            .items_center()
            .gap_1()
            .child(
                Button::new(toggle_id)
                    .ghost()
                    .w_7()
                    .px_0()
                    .icon(if expanded {
                        IconName::ChevronDown
                    } else {
                        IconName::ChevronRight
                    })
                    .tooltip(if expanded {
                        locale::text(
                            "Collapse child timeline",
                            "收起子 Agent 时间线",
                            "收起子 Agent 時間線",
                        )
                    } else {
                        locale::text(
                            "Expand child timeline",
                            "展开子 Agent 时间线",
                            "展開子 Agent 時間線",
                        )
                    })
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.toggle_child_agent_delegation(&toggle_delegation, cx)
                    })),
            )
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .truncate()
                    .text_sm()
                    .font_medium()
                    .child(title.clone()),
            )
            .child(Self::render_child_agent_status_badge(delegation.status, cx));
        if !delegation.action.trim().is_empty() && delegation.action != title {
            header = header.child(
                div()
                    .min_w_0()
                    .max_w(px(180.0))
                    .truncate()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(delegation.action.clone()),
            );
        }
        let mut details = v_flex().min_w_0().flex_1().gap_2().child(header).child(
            div()
                .w_full()
                .min_w_0()
                .text_xs()
                .line_height(gpui::relative(1.4))
                .text_color(cx.theme().muted_foreground)
                .whitespace_normal()
                .child(delegation.summary.clone()),
        );
        if let Some(preview) = preview {
            details = details.child(div().w_full().min_w_0().pt_1().child(preview));
        }
        if hidden_count > 0 {
            details = details.child(
                div()
                    .w_full()
                    .min_w_0()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!("+{hidden_count} more...")),
            );
        }
        details = details.child(
            Button::new(format!("{card_id}:open"))
                .small()
                .ghost()
                .compact()
                .icon(IconName::ExternalLink)
                .label(locale::text(
                    "Open child Agent task",
                    "打开子 Agent 任务",
                    "開啟子 Agent 任務",
                ))
                .tooltip(locale::text(
                    "Open the full child Agent timeline in the right rail",
                    "在右侧栏打开子 Agent 完整时间线",
                    "在右側欄開啟子 Agent 完整時間線",
                ))
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.open_child_agent_timeline(title_session_id.clone(), cx)
                })),
        );
        h_flex()
            .id(card_id)
            .w_full()
            .min_w_0()
            .items_stretch()
            .gap_2()
            .py_2()
            .child(
                v_flex()
                    .w(px(20.0))
                    .flex_none()
                    .items_center()
                    .text_color(cx.theme().muted_foreground)
                    .child(
                        div()
                            .size(px(18.0))
                            .flex_none()
                            .child(runtime_agent_icon(&agent_identity)),
                    )
                    .child(
                        div()
                            .mt(px(3.0))
                            .w(px(1.0))
                            .flex_1()
                            .bg(cx.theme().muted_foreground.opacity(0.46)),
                    ),
            )
            .child(details)
            .into_any_element()
    }

    fn render_child_agent_timeline_row(
        &mut self,
        projection: &ChildAgentTimelineRowProjection,
        surface_id: &str,
        compact: bool,
        nesting: u8,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if let Some(delegation) = projection.delegation.as_ref()
            && nesting < CHILD_AGENT_TIMELINE_MAX_NESTING
        {
            return self.render_agent_delegation_card(
                &projection.row,
                delegation,
                surface_id,
                nesting,
                cx,
            );
        }
        let row = &projection.row;
        let (icon, tone) = match row.kind {
            TimelineRowKind::UserMessage => (Icon::new(IconName::User), cx.theme().foreground),
            TimelineRowKind::AgentMessage => (Icon::new(IconName::Bot), cx.theme().foreground),
            TimelineRowKind::Error => (Icon::new(IconName::CircleX), cx.theme().danger),
            TimelineRowKind::PermissionRequest | TimelineRowKind::ElicitationRequest => {
                (Icon::new(IconName::Info), cx.theme().warning)
            }
            TimelineRowKind::Collaboration => {
                (Icon::new(IconName::Bot), cx.theme().muted_foreground)
            }
            _ => (Icon::new(IconName::Info), cx.theme().muted_foreground),
        };
        let body = if compact {
            compact_agent_turn_preview_message(&row.body)
        } else {
            row.body.trim().to_string()
        };
        let row_id = format!("{surface_id}:timeline-row:{}", row.id);
        v_flex()
            .id(row_id)
            .w_full()
            .min_w_0()
            .gap_1()
            .rounded(px(5.0))
            .px_2()
            .py(px(6.0))
            .when(row.failed, |this| {
                this.bg(cx
                    .theme()
                    .danger
                    .opacity(if cx.theme().is_dark() { 0.13 } else { 0.08 }))
            })
            .child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_2()
                    .text_xs()
                    .text_color(tone)
                    .child(icon.size(px(14.0)).flex_none())
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .truncate()
                            .font_medium()
                            .child(row.title.clone()),
                    )
                    .when(row.streaming, |this| this.child(Spinner::new().xsmall()))
                    .when(row.pending_permission, |this| {
                        this.child(
                            div()
                                .flex_none()
                                .rounded(px(4.0))
                                .bg(cx.theme().warning.opacity(0.16))
                                .px_1()
                                .py(px(1.0))
                                .text_xs()
                                .text_color(cx.theme().warning)
                                .child("Input required"),
                        )
                    }),
            )
            .when(!body.is_empty(), |this| {
                this.child(
                    div()
                        .w_full()
                        .min_w_0()
                        .pl_5()
                        .text_xs()
                        .line_height(gpui::relative(1.4))
                        .text_color(cx.theme().muted_foreground)
                        .whitespace_normal()
                        .child(body),
                )
            })
            .into_any_element()
    }

    fn render_child_agent_timeline_content(
        &mut self,
        snapshot: ChildAgentTimelineSnapshot,
        surface_id: &str,
        compact: bool,
        nesting: u8,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if snapshot.rows.is_empty() && snapshot.loading {
            return h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .py_2()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(Spinner::new().xsmall())
                .child("Loading timeline")
                .into_any_element();
        }
        if let Some(error) = snapshot.error {
            return div()
                .w_full()
                .min_w_0()
                .rounded(px(5.0))
                .bg(cx
                    .theme()
                    .danger
                    .opacity(if cx.theme().is_dark() { 0.14 } else { 0.08 }))
                .px_2()
                .py_2()
                .text_xs()
                .text_color(cx.theme().danger)
                .whitespace_normal()
                .child(error)
                .into_any_element();
        }
        if snapshot.rows.is_empty() {
            return div()
                .w_full()
                .min_w_0()
                .py_2()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(if snapshot.loaded {
                    "No timeline activity"
                } else {
                    "Waiting for child Agent"
                })
                .into_any_element();
        }
        let start = compact
            .then(|| {
                snapshot
                    .rows
                    .len()
                    .saturating_sub(CHILD_AGENT_TIMELINE_PREVIEW_ROW_LIMIT)
            })
            .unwrap_or_default();
        let rows = snapshot.rows.into_iter().skip(start).collect::<Vec<_>>();
        v_flex()
            .w_full()
            .min_w_0()
            .gap(if compact { px(2.0) } else { px(6.0) })
            .children(rows.iter().map(|row| {
                self.render_child_agent_timeline_row(row, surface_id, compact, nesting, cx)
            }))
            .into_any_element()
    }

    fn render_child_agent_full_timeline(
        &mut self,
        session_id: &VibexSessionId,
        snapshot: ChildAgentTimelineSnapshot,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if snapshot.error.is_some() || snapshot.turns.is_empty() {
            return self.render_child_agent_timeline_content(
                snapshot,
                &format!("child-agent-panel:{}", session_id.as_str()),
                false,
                0,
                cx,
            );
        }
        let turns = snapshot.turns;
        let turn_count = turns.len();
        let previous = self.child_agent_render_session.replace(session_id.clone());
        let mut content = v_flex().w_full().min_w_0().gap_0();
        for (index, turn) in turns.iter().enumerate() {
            content = content.child(self.render_timeline_turn(
                turn,
                index == 0,
                index + 1 == turn_count,
                window,
                cx,
            ));
        }
        self.child_agent_render_session = previous;
        content.into_any_element()
    }

    fn render_child_agent_timeline_panel(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let tabs = self.child_agent_tabs.clone();
        let active_session_id = self
            .child_agent_active_tab
            .clone()
            .filter(|session_id| tabs.contains(session_id))
            .or_else(|| tabs.last().cloned());
        let active_snapshot = active_session_id
            .as_ref()
            .and_then(|session_id| self.child_agent_timeline_snapshot(session_id));
        let tab_elements = tabs
            .into_iter()
            .map(|session_id| {
                let active = active_session_id.as_ref() == Some(&session_id);
                let label = self.child_agent_session_label(&session_id);
                let select_session_id = session_id.clone();
                let close_session_id = session_id.clone();
                h_flex()
                    .id(format!("child-agent-tab:{}", session_id.as_str()))
                    .h(px(30.0))
                    .min_w(px(112.0))
                    .max_w(px(220.0))
                    .items_center()
                    .gap_1()
                    .rounded(px(5.0))
                    .border_1()
                    .border_color(if active {
                        cx.theme().accent
                    } else {
                        cx.theme().border
                    })
                    .bg(if active {
                        cx.theme()
                            .accent
                            .opacity(if cx.theme().is_dark() { 0.18 } else { 0.10 })
                    } else {
                        cx.theme().muted.opacity(0.32)
                    })
                    .child(
                        Button::new(format!("select-child-agent-tab:{}", session_id.as_str()))
                            .ghost()
                            .min_w_0()
                            .flex_1()
                            .h_full()
                            .px_2()
                            .justify_start()
                            .label(label)
                            .tooltip(session_id.as_str().to_string())
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.select_child_agent_tab(select_session_id.clone(), cx)
                            })),
                    )
                    .child(
                        Button::new(format!("close-child-agent-tab:{}", session_id.as_str()))
                            .ghost()
                            .w_7()
                            .px_0()
                            .icon(IconName::Close)
                            .tooltip(locale::text(
                                "Close child Agent tab",
                                "关闭子 Agent 标签页",
                                "關閉子 Agent 分頁",
                            ))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.close_child_agent_tab(&close_session_id, cx)
                            })),
                    )
                    .into_any_element()
            })
            .collect::<Vec<_>>();
        let body = if let (Some(session_id), Some(snapshot)) =
            (active_session_id.as_ref(), active_snapshot)
        {
            self.render_child_agent_full_timeline(session_id, snapshot, window, cx)
        } else {
            div()
                .w_full()
                .min_w_0()
                .py_4()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child("Open a child Agent from the timeline")
                .into_any_element()
        };
        v_flex()
            .id("child-agent-right-rail")
            .size_full()
            .min_w_0()
            .min_h_0()
            .bg(cx.theme().background)
            .child(
                h_flex()
                    .w_full()
                    .h(px(42.0))
                    .flex_none()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .px_3()
                    .border_b_1()
                    .border_color(cx.theme().border)
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .font_medium()
                            .child("Child Agents"),
                    )
                    .child(
                        Button::new("close-child-agent-right-rail")
                            .ghost()
                            .w_8()
                            .px_0()
                            .icon(IconName::Close)
                            .tooltip(locale::text("Close panel", "关闭面板", "關閉面板"))
                            .on_click(cx.listener(|this, _, _, cx| this.close_right_rail(cx))),
                    ),
            )
            .when(!tab_elements.is_empty(), |this| {
                this.child(
                    h_flex()
                        .id("child-agent-tabs-scroll")
                        .w_full()
                        .flex_none()
                        .min_w_0()
                        .gap_1()
                        .overflow_x_scroll()
                        .px_2()
                        .py_2()
                        .border_b_1()
                        .border_color(cx.theme().border)
                        .children(tab_elements),
                )
            })
            .child(
                div()
                    .id("child-agent-timeline-scroll")
                    .flex_1()
                    .min_w_0()
                    .min_h_0()
                    .overflow_y_scroll()
                    .p_3()
                    .track_scroll(&self.child_agent_timeline_scroll)
                    .scrollbar(&self.child_agent_timeline_scroll, ScrollbarAxis::Vertical)
                    .child(body),
            )
            .into_any_element()
    }

    fn render_timeline_row(
        &mut self,
        row: &TimelineRow,
        conversation_conclusion: bool,
        content_before_actions: Option<AnyElement>,
        answer_metadata: Option<AnyElement>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if let Some(delegation) = timeline_row_delegation(row, &self.active_timeline().items) {
            let surface_id = if self.rendering_child_agent_timeline() {
                "child-agent-full"
            } else {
                "main"
            };
            return self.render_agent_delegation_card(row, &delegation, surface_id, 0, cx);
        }
        // Keep prose in the document flow and lightweight activity on compact
        // lines. Structured commands use cards only when the session preference
        // enables their enhanced display.
        let mut content_before_actions = content_before_actions;
        let mut answer_metadata = answer_metadata;
        let element = match row.kind {
            TimelineRowKind::UserMessage => {
                self.render_user_message_row(row, None, false, false, window, cx)
            }
            TimelineRowKind::AgentMessage => self.render_agent_message_row(
                row,
                conversation_conclusion,
                content_before_actions.take(),
                answer_metadata.take(),
                cx,
            ),
            TimelineRowKind::Reasoning | TimelineRowKind::Plan => {
                self.render_thought_process_row(row, cx)
            }
            TimelineRowKind::Error => self.render_error_row(row, conversation_conclusion, cx),
            TimelineRowKind::PermissionRequest if self.rendering_child_agent_timeline() => {
                self.render_fallback_process_row(row, cx)
            }
            TimelineRowKind::PermissionRequest => self.render_permission_request_card(row, cx),
            TimelineRowKind::ElicitationRequest => {
                if self.rendering_child_agent_timeline() {
                    self.render_fallback_process_row(row, cx)
                } else {
                    self.render_elicitation_request_card(row, window, cx)
                }
            }
            TimelineRowKind::Command
                if !self.rendering_child_agent_timeline()
                    && self.ui_state.session.enhanced_command_execution_display =>
            {
                self.render_command_execution_card(row, None, cx)
            }
            TimelineRowKind::Command => self.render_process_activity_line(row, cx),
            TimelineRowKind::FileOperation
                if !self.rendering_child_agent_timeline()
                    && self.ui_state.session.enhanced_file_operation_display =>
            {
                self.render_file_operation_card(row, cx)
            }
            TimelineRowKind::FileOperation => self.render_process_activity_line(row, cx),
            TimelineRowKind::ImageGeneration => self.render_image_generation_card(row, cx),
            TimelineRowKind::ToolCall
            | TimelineRowKind::WebSearch
            | TimelineRowKind::TodoUpdate
            | TimelineRowKind::Collaboration
            | TimelineRowKind::Retry => self.render_process_activity_line(row, cx),
            TimelineRowKind::GitNotice
            | TimelineRowKind::SystemNotice
            | TimelineRowKind::PermissionResolution
            | TimelineRowKind::ElicitationResolution => self.render_fallback_process_row(row, cx),
        };
        let element = if let Some(content) = content_before_actions {
            v_flex()
                .w_full()
                .min_w_0()
                .gap_3()
                .child(element)
                .child(content)
                .into_any_element()
        } else {
            element
        };
        self.highlight_session_search_rows(std::slice::from_ref(row), element, cx)
    }

    fn highlight_session_search_rows(
        &self,
        rows: &[TimelineRow],
        element: AnyElement,
        cx: &App,
    ) -> AnyElement {
        if self.session_search_highlight_query_for_rows(rows).is_some() {
            let active = self.conversation_find_open
                && self
                    .conversation_find_active_item_id
                    .as_ref()
                    .is_some_and(|active_id| {
                        rows.iter()
                            .any(|row| row.item_ids.iter().any(|id| id == active_id))
                    });
            div()
                .w_full()
                .min_w_0()
                .rounded(px(6.0))
                .bg(cx.theme().warning.opacity(if active { 0.20 } else { 0.10 }))
                .child(element)
                .into_any_element()
        } else {
            element
        }
    }

    fn session_search_highlight_query_for_rows<'a>(
        &'a self,
        rows: &[TimelineRow],
    ) -> Option<&'a str> {
        if self.conversation_find_open && !self.conversation_find_query.is_empty() {
            return rows
                .iter()
                .any(|row| {
                    !session_search_match_ranges(
                        &session_search_row_text(row),
                        &self.conversation_find_query,
                    )
                    .is_empty()
                })
                .then_some(self.conversation_find_query.as_str());
        }
        let query = self.session_search_highlight_query.as_deref()?;
        let item_id = self.session_search_highlight_item_id.as_deref()?;
        rows.iter()
            .any(|row| row.item_ids.iter().any(|candidate| candidate == item_id))
            .then_some(query)
    }

    fn session_search_highlighted_row_text(
        &self,
        row: &TimelineRow,
        text: String,
        cx: &App,
    ) -> StyledText {
        let query = self
            .session_search_highlight_query_for_rows(std::slice::from_ref(row))
            .unwrap_or_default();
        session_search_highlighted_text(
            text,
            query,
            HighlightStyle {
                background_color: Some(cx.theme().warning.opacity(0.42)),
                font_weight: Some(FontWeight::BOLD),
                ..Default::default()
            },
        )
    }

    /// Tool/command card projection for a row, memoized per row revision.
    ///
    /// Building one clones the payload strings (command output, tool summaries),
    /// and an expanded turn renders hundreds of these rows on every frame.
    fn tool_card_projection_cached(&mut self, row: &TimelineRow) -> Rc<ToolCardProjection> {
        if let Some((sequence, projection)) = self.timeline_tool_card_projections.get(&row.id)
            && *sequence == row.last_sequence
        {
            return projection.clone();
        }
        let projection = {
            let payload = self.timeline_row_latest_item(row).map(|item| &item.payload);
            Rc::new(tool_card_projection(row, payload))
        };
        insert_bounded_timeline_projection(
            &mut self.timeline_tool_card_projections,
            row.id.clone(),
            row.last_sequence,
            projection.clone(),
            TIMELINE_TOOL_PROJECTION_CACHE_LIMIT,
            TIMELINE_TOOL_PROJECTION_CACHE_BYTES,
            |projection| projection.approximate_bytes(),
        );
        projection
    }

    fn agent_turn_file_changes_cached(
        &mut self,
        turn: &TimelineConversationTurn,
    ) -> Rc<TurnFileChangesSummary> {
        // Reasoning chunks advance the turn's end sequence but cannot change
        // its file summary. Key this cache by the latest file-operation row so
        // thought streaming reuses the existing diff projection.
        let sequence = timeline_turn_file_changes_cache_sequence(turn);
        if let Some((cached_sequence, summary)) = self.timeline_turn_file_changes.get(&turn.id)
            && *cached_sequence == sequence
        {
            return summary.clone();
        }
        let workspace_root = self
            .selected_session()
            .map(|session| session.workspace_root.clone());
        let summary = {
            let timeline = self.active_timeline();
            Rc::new(agent_turn_file_changes(
                turn,
                &timeline.items,
                workspace_root.as_deref(),
            ))
        };
        insert_bounded_timeline_projection(
            &mut self.timeline_turn_file_changes,
            turn.id.clone(),
            sequence,
            summary.clone(),
            TIMELINE_TURN_FILE_CHANGES_CACHE_LIMIT,
            TIMELINE_TURN_FILE_CHANGES_CACHE_BYTES,
            |summary| summary.approximate_bytes(),
        );
        summary
    }

    /// File snapshots can be large, and a line diff is substantially more expensive than
    /// rendering its bounded preview. Reuse the projection until the timeline row changes.
    fn agent_file_diff_preview_cached(
        &mut self,
        row: &TimelineRow,
        operation: &vibex_core::FileOperationPayload,
    ) -> Rc<AgentFileDiffPreview> {
        if let Some((sequence, preview)) = self.timeline_file_diff_previews.get(&row.id)
            && *sequence == row.last_sequence
        {
            return preview.clone();
        }
        let preview = Rc::new(agent_file_operation_diff_preview(operation));
        insert_bounded_timeline_projection(
            &mut self.timeline_file_diff_previews,
            row.id.clone(),
            row.last_sequence,
            preview.clone(),
            TIMELINE_FILE_DIFF_PREVIEW_CACHE_LIMIT,
            TIMELINE_FILE_DIFF_PREVIEW_CACHE_BYTES,
            |preview| preview.approximate_bytes(),
        );
        preview
    }

    fn agent_file_diff_scroll_handle(&mut self, row_id: &str) -> gpui::ScrollHandle {
        if let Some(scroll) = self.timeline_file_diff_scrolls.get(row_id) {
            return scroll.clone();
        }
        if self.timeline_file_diff_scrolls.len() >= TIMELINE_FILE_DIFF_SCROLL_CACHE_LIMIT
            && let Some(evicted) = self.timeline_file_diff_scrolls.keys().next().cloned()
        {
            self.timeline_file_diff_scrolls.remove(&evicted);
        }
        let scroll = gpui::ScrollHandle::new();
        self.timeline_file_diff_scrolls
            .insert(row_id.to_string(), scroll.clone());
        scroll
    }

    /// Shared body text for a markdown row.
    ///
    /// `MarkdownInput` takes an `Arc<str>`, so handing it `row.body.clone()`
    /// copies the whole message twice per frame per visible row. Reusing one
    /// allocation also lets the markdown view settle on a pointer comparison
    /// instead of a full memcmp when nothing changed.
    fn timeline_markdown_source(&mut self, row: &TimelineRow) -> (Arc<str>, i64) {
        let allow_throttle = self.streaming_row_state.as_ref().is_some_and(|state| {
            row.turn_id.as_deref() == Some(state.turn_id.as_str())
                && state.row_id == row.id
                && state.body_len == row.body.len()
        });
        timeline_markdown_source_snapshot(
            &mut self.timeline_markdown_sources,
            row,
            Instant::now(),
            allow_throttle,
        )
    }

    fn rendering_child_agent_timeline(&self) -> bool {
        self.child_agent_render_session.is_some()
    }

    fn active_timeline(&self) -> &TimelineModel {
        self.child_agent_render_session
            .as_ref()
            .and_then(|session_id| self.child_agent_timelines.get(session_id.as_str()))
            .map(|state| &state.timeline)
            .unwrap_or(&self.timeline)
    }

    fn timeline_scroll_handle(&self) -> ScrollHandle {
        if self.rendering_child_agent_timeline() {
            self.child_agent_timeline_scroll.clone()
        } else {
            self.timeline_scroll.base_handle().clone()
        }
    }

    /// Refresh the id → position lookup when the timeline identity moved on.
    fn sync_timeline_item_index(&self) {
        let mut index = self.timeline_item_index.borrow_mut();
        index.sync(&self.timeline);
    }

    fn timeline_row_latest_item(&self, row: &TimelineRow) -> Option<&vibex_core::TimelineItem> {
        if self.rendering_child_agent_timeline() {
            let timeline = self.active_timeline();
            return row
                .item_ids
                .iter()
                .filter_map(|id| timeline.items.iter().find(|item| item.id.as_str() == id))
                .max_by_key(|item| item.sequence);
        }
        self.sync_timeline_item_index();
        let index = self.timeline_item_index.borrow();
        row.item_ids
            .iter()
            .filter_map(|id| index.positions.get(id).copied())
            .filter_map(|position| self.timeline.items.get(position))
            .max_by_key(|item| item.sequence)
    }

    fn timeline_row_timestamp(&self, row: &TimelineRow) -> Option<i64> {
        self.timeline_row_latest_item(row)
            .map(|item| item.timestamp_ms)
    }

    // Height estimation provides the first virtual-list layout. Visible turns
    // report their intrinsic height after layout so rich Markdown spacing does
    // not depend on this approximation.
    fn estimated_timeline_row_height_projected(&self, row: &TimelineRow, conclusion: bool) -> f32 {
        let payload = self.timeline_row_latest_item(row).map(|item| &item.payload);
        match row.kind {
            TimelineRowKind::UserMessage => {
                let lines = estimated_wrapped_lines(&row.body, 56) as f32;
                // bubble padding + text + gap + always-reserved hover action row
                let base_height = lines * 24.0 + 20.0 + 4.0 + 26.0;
                if self
                    .inline_user_message_edit
                    .as_ref()
                    .is_some_and(|edit| edit.matches(&row.id, self.selected_session_id.as_ref()))
                {
                    base_height + 40.0
                } else {
                    base_height
                }
            }
            TimelineRowKind::AgentMessage => {
                let mut height = estimated_markdown_body_height(&row.body, 72) + 8.0;
                if row.body.contains("](") {
                    height += 30.0;
                }
                if conclusion && !row.streaming {
                    // Answer metadata and hover actions share one footer row.
                    height += 36.0;
                }
                height
            }
            TimelineRowKind::Reasoning => {
                if row.body.is_empty() {
                    4.0
                } else if self.reasoning_row_expanded(&row.id) {
                    estimated_markdown_body_height(&row.body, 72) + 4.0
                } else {
                    28.0
                }
            }
            TimelineRowKind::Plan => {
                if row.body.is_empty() {
                    4.0
                } else {
                    ((estimated_wrapped_lines(&row.body, 72) as f32) * 24.0).min(288.0) + 4.0
                }
            }
            TimelineRowKind::Error => {
                let text = if row.body.is_empty() {
                    &row.title
                } else {
                    &row.body
                };
                let lines = estimated_wrapped_lines(text, 72) as f32;
                if conclusion {
                    lines * 24.0 + 25.0
                } else {
                    16.0 + lines * 20.0
                }
            }
            TimelineRowKind::GitNotice
            | TimelineRowKind::SystemNotice
            | TimelineRowKind::PermissionResolution
            | TimelineRowKind::ElicitationResolution => 24.0,
            TimelineRowKind::PermissionRequest => {
                let Some(vibex_core::TimelinePayload::PermissionRequest(request)) = payload else {
                    return 24.0;
                };
                let mut height = 37.0 + 20.0;
                let lower_labels = request
                    .details
                    .iter()
                    .map(|detail| detail.label.to_ascii_lowercase())
                    .collect::<Vec<_>>();
                if let Some(index) = lower_labels
                    .iter()
                    .position(|label| matches!(label.as_str(), "command" | "cmd" | "args" | "cwd"))
                {
                    height += estimated_pre_block_height(&request.details[index].value) + 8.0;
                }
                if let Some(index) = lower_labels.iter().position(|label| label.contains("env")) {
                    height += (estimated_wrapped_lines(&request.details[index].value, 72) as f32)
                        * 20.0
                        + 16.0
                        + 8.0;
                }
                height += 8.0;
                for detail in &request.details {
                    height += (estimated_wrapped_lines(&detail.value, 60) as f32) * 20.0 + 6.0;
                }
                if row.pending_permission
                    && request.status == vibex_core::PermissionRequestStatus::Pending
                {
                    height += 12.0 + 28.0;
                }
                height
            }
            TimelineRowKind::ElicitationRequest => {
                let Some(vibex_core::TimelinePayload::ElicitationRequest(request)) = payload else {
                    return 48.0;
                };
                let mut height =
                    88.0 + (estimated_wrapped_lines(&request.message, 64) as f32) * 20.0 + 44.0;
                for field in &request.fields {
                    height += 30.0;
                    if field.description.is_some() {
                        height += 20.0;
                    }
                    height += match &field.kind {
                        ElicitationFieldKind::Text { options, .. } if !options.is_empty() => {
                            options.len().max(1).div_ceil(2) as f32 * 48.0
                        }
                        ElicitationFieldKind::MultiSelect { options, .. } => {
                            options.len().max(1).div_ceil(2) as f32 * 48.0
                        }
                        ElicitationFieldKind::Text { .. }
                        | ElicitationFieldKind::Number { .. }
                        | ElicitationFieldKind::Integer { .. } => 38.0,
                        ElicitationFieldKind::Boolean { .. }
                        | ElicitationFieldKind::Unsupported { .. } => 32.0,
                    };
                }
                height
            }
            TimelineRowKind::Command
                if self.ui_state.session.enhanced_command_execution_display =>
            {
                let Some(vibex_core::TimelinePayload::Command(command)) = payload else {
                    return 40.0;
                };
                let expanded = self
                    .timeline_command_expansion
                    .get(&row.id)
                    .copied()
                    .unwrap_or(false);
                if !expanded {
                    return 40.0;
                }
                let mut height = 40.0 + 24.0 + estimated_pre_block_height(&command.command);
                if let Some(output) = command.output_summary.as_deref() {
                    height += 20.0 + estimated_detail_block_height(output);
                }
                if command.cwd.is_some() {
                    height += 28.0;
                }
                if command.exit_code.is_some() {
                    height += 24.0;
                }
                height
            }
            TimelineRowKind::FileOperation
                if self.ui_state.session.enhanced_file_operation_display =>
            {
                let Some(vibex_core::TimelinePayload::FileOperation(_)) = payload else {
                    return 40.0;
                };
                let expanded = self
                    .timeline_command_expansion
                    .get(&row.id)
                    .copied()
                    .unwrap_or(false);
                if !expanded {
                    return 40.0;
                }
                // Visible turns replace this conservative first layout with their measured height.
                360.0
            }
            TimelineRowKind::ImageGeneration => {
                let Some(vibex_core::TimelinePayload::ImageGeneration(_)) = payload else {
                    return 40.0;
                };
                let expanded = self
                    .timeline_command_expansion
                    .get(&row.id)
                    .copied()
                    .unwrap_or(false);
                if expanded { 312.0 } else { 40.0 }
            }
            TimelineRowKind::Command
            | TimelineRowKind::FileOperation
            | TimelineRowKind::ToolCall
            | TimelineRowKind::WebSearch
            | TimelineRowKind::TodoUpdate
            | TimelineRowKind::Collaboration
            | TimelineRowKind::Retry => {
                let projection = tool_card_projection(row, payload);
                let mut height = 24.0;
                let expanded = !projection.details.is_empty()
                    && self
                        .timeline_command_expansion
                        .get(&row.id)
                        .copied()
                        .unwrap_or(false);
                if expanded {
                    height += 8.0;
                    for (index, (_, value)) in projection.details.iter().enumerate() {
                        if index > 0 {
                            height += 8.0;
                        }
                        height += estimated_detail_block_height(value);
                    }
                    if row.file_path.is_some() {
                        height += 28.0 + 8.0;
                    }
                }
                height
            }
        }
    }

    fn estimated_process_activity_group_height(
        &self,
        turn: &TimelineConversationTurn,
        group: &TimelineProcessActivityGroup,
    ) -> f32 {
        let mut height = 24.0;
        let expanded = self
            .timeline_command_expansion
            .get(&group.id)
            .copied()
            .unwrap_or(false);
        if !expanded || group.end_row > turn.process_rows.len() {
            return height;
        }

        height += 8.0;
        for (index, row) in turn.process_rows[group.start_row..group.end_row]
            .iter()
            .enumerate()
        {
            if index > 0 {
                height += 8.0;
            }
            height += self.estimated_timeline_row_height_projected(row, false);
        }
        height
    }

    fn estimated_timeline_process_rows_height(&self, turn: &TimelineConversationTurn) -> f32 {
        let mut height = 0.0;
        let mut row_index = 0;
        let mut group_index = 0;
        let enhanced_command_display = self.ui_state.session.enhanced_command_execution_display;
        let process_activity_groups = timeline_process_activity_groups_for_display(
            turn,
            enhanced_command_display,
            self.ui_state.session.enhanced_file_operation_display,
        );

        while row_index < turn.process_rows.len() {
            while process_activity_groups
                .get(group_index)
                .is_some_and(|group| group.end_row <= row_index)
            {
                group_index += 1;
            }
            if enhanced_command_display
                && let (Some(command_row), Some(permission_row)) = (
                    turn.process_rows.get(row_index),
                    turn.process_rows.get(row_index + 1),
                )
                && self.command_permission_rows_are_linked(command_row, permission_row)
            {
                let permission_height = self
                    .permission_request_for_row(permission_row)
                    .map(|request| {
                        if permission_request_is_pending(permission_row, &request) {
                            92.0
                        } else {
                            48.0
                        }
                    })
                    .unwrap_or(48.0);
                height += self.estimated_timeline_row_height_projected(command_row, false)
                    + permission_height
                    + 12.0;
                row_index += 2;
                continue;
            }
            let group = process_activity_groups.get(group_index).filter(|group| {
                group.start_row == row_index
                    && group.end_row <= turn.process_rows.len()
                    && group.end_row > group.start_row
            });
            if let Some(group) = group {
                height += self.estimated_process_activity_group_height(turn, group) + 12.0;
                row_index = group.end_row;
                group_index += 1;
            } else {
                height += self
                    .estimated_timeline_row_height_projected(&turn.process_rows[row_index], false)
                    + 12.0;
                row_index += 1;
            }
        }

        height
    }

    fn estimated_timeline_turn_height_projected(
        &mut self,
        turn: &TimelineConversationTurn,
        explicit_process_expansion: Option<bool>,
    ) -> f32 {
        let mut height = 40.0;
        if let Some(user_row) = turn.user_row.as_ref() {
            height += self.estimated_timeline_row_height_projected(user_row, false) + 12.0;
        }
        let has_response =
            !turn.process_rows.is_empty() || turn.conclusion_row.is_some() || !turn.complete;
        if has_response {
            // header row + rule
            height += 40.0 + 12.0;
            let process_expanded = timeline_turn_process_expanded(turn, explicit_process_expansion);
            if process_expanded {
                height += self.estimated_timeline_process_rows_height(turn);
            }
            if let Some(conclusion_row) = timeline_turn_conclusion_row(turn) {
                height += self.estimated_timeline_row_height_projected(conclusion_row, true) + 12.0;
            } else if !turn.complete {
                let timeline_has_live_reasoning = self.ui_state.session.reasoning_display_mode
                    == ReasoningDisplayMode::Timeline
                    && turn
                        .process_rows
                        .iter()
                        .any(|row| row.kind == TimelineRowKind::Reasoning && row.streaming);
                if !timeline_has_live_reasoning {
                    let live_reasoning_height = turn
                        .live_status
                        .as_deref()
                        .filter(|_| {
                            self.ui_state.session.reasoning_display_mode
                                == ReasoningDisplayMode::LatestAtBottom
                        })
                        .map(|body| {
                            let key = format!("reasoning-live:{}", turn.id);
                            if self.reasoning_row_expanded(&key) {
                                estimated_markdown_body_height(body, 72) + 4.0
                            } else {
                                28.0
                            }
                        })
                        .unwrap_or(34.0);
                    height += live_reasoning_height;
                }
            }
        }
        if turn.complete {
            let expanded = self
                .timeline_file_changes_expansion
                .get(&turn.id)
                .copied()
                .unwrap_or(false);
            let file_count = self.agent_turn_file_changes_cached(turn).files.len();
            if file_count > 0 {
                let visible_count = if expanded {
                    file_count
                } else {
                    file_count.min(TURN_FILE_CHANGES_VISIBLE_COUNT)
                };
                // Card header + file rows + action footer + surrounding turn gap.
                height += 42.0 + visible_count as f32 * 36.0 + 42.0 + 12.0;
            }
        }
        height.max(72.0)
    }

    fn render_inline_user_message_editor(
        &mut self,
        message_id: &str,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let attachments = self
            .inline_user_message_edit
            .as_ref()
            .map(|edit| edit.attachments.as_slice())
            .unwrap_or_default();
        let raw_text = self.user_message_edit_input.read(cx).value().to_string();
        let (_, submitted_attachments) = composer_submission_payload(&raw_text, attachments);
        let can_submit = !raw_text.trim().is_empty() || !submitted_attachments.is_empty();
        let pending = self.agent_action_pending
            || self
                .inline_user_message_edit
                .as_ref()
                .is_some_and(|edit| self.session_turn_pending(&edit.source_session_id));
        let geometry_entity = cx.entity().downgrade();
        v_flex()
            .w_full()
            .min_w_0()
            .gap_2()
            .child(
                div()
                    .w_full()
                    .min_w_0()
                    .on_prepaint(move |bounds, _, cx| {
                        let _ = geometry_entity.update(cx, |this, cx| {
                            if let Some(edit) = this.inline_user_message_edit.as_mut()
                                && edit.geometry.input_bounds != Some(bounds)
                            {
                                edit.geometry.input_bounds = Some(bounds);
                                cx.notify();
                            }
                        });
                    })
                    .capture_action(cx.listener(|this, _: &InputBackspace, window, cx| {
                        this.capture_user_message_inline_attachment_edit(
                            InlineAttachmentEdit::Backspace,
                            window,
                            cx,
                        )
                    }))
                    .capture_action(cx.listener(|this, _: &InputDelete, window, cx| {
                        this.capture_user_message_inline_attachment_edit(
                            InlineAttachmentEdit::Delete,
                            window,
                            cx,
                        )
                    }))
                    .capture_action(cx.listener(|this, _: &InputMoveLeft, window, cx| {
                        this.capture_user_message_inline_attachment_edit(
                            InlineAttachmentEdit::Left,
                            window,
                            cx,
                        )
                    }))
                    .capture_action(cx.listener(|this, _: &InputMoveRight, window, cx| {
                        this.capture_user_message_inline_attachment_edit(
                            InlineAttachmentEdit::Right,
                            window,
                            cx,
                        )
                    }))
                    .capture_action(cx.listener(|this, _: &InputPaste, window, cx| {
                        this.capture_user_message_edit_paste(window, cx)
                    }))
                    .child(
                        Input::new(&self.user_message_edit_input)
                            .appearance(false)
                            .w_full()
                            .disabled(pending),
                    ),
            )
            .child(
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_end()
                    .gap_1()
                    .child(
                        Button::new(format!("cancel-inline-message-edit:{message_id}"))
                            .xsmall()
                            .ghost()
                            .compact()
                            .h(px(26.0))
                            .icon(IconName::Close)
                            .label(locale::text("Cancel", "取消", "取消"))
                            .disabled(pending)
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.cancel_inline_user_message_edit(cx)
                            })),
                    )
                    .child(
                        Button::new(format!("submit-inline-message-edit:{message_id}"))
                            .xsmall()
                            .primary()
                            .compact()
                            .h(px(26.0))
                            .icon(IconName::Check)
                            .label(locale::text("Send", "发送", "傳送"))
                            .disabled(pending || !can_submit)
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.submit_inline_user_message_edit(window, cx)
                            })),
                    ),
            )
            .into_any_element()
    }

    fn render_user_message_row(
        &mut self,
        row: &TimelineRow,
        turn_id: Option<&str>,
        latest_user_message: bool,
        turn_complete: bool,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if self.rendering_child_agent_timeline() {
            return self.render_child_agent_user_message_row(row, cx);
        }
        self.sync_timeline_item_index();
        let attachments = {
            let timeline_item_index = self.timeline_item_index.borrow();
            row.item_ids
                .iter()
                .filter_map(|item_id| timeline_item_index.positions.get(item_id).copied())
                .filter_map(|position| self.timeline.items.get(position))
                .find_map(|item| match &item.payload {
                    vibex_core::TimelinePayload::UserMessage(message) => {
                        Some(message.attachments.clone())
                    }
                    _ => None,
                })
                .unwrap_or_default()
        };
        let attachments = if attachments.is_empty() {
            self.optimistic_user_message_attachments_for_row(row)
                .unwrap_or(attachments)
        } else {
            attachments
        };
        let copy_item = user_message_clipboard_item(&row.body, &attachments);
        let edit_attachments = attachments.clone();
        let timestamp = self.timeline_row_timestamp(row);
        let locale = self.resolved_locale();
        let editing = self
            .inline_user_message_edit
            .as_ref()
            .is_some_and(|edit| edit.matches(&row.id, self.selected_session_id.as_ref()));
        let search_query = self
            .session_search_highlight_query_for_rows(std::slice::from_ref(row))
            .map(str::to_string);
        let inline_content = if editing {
            self.render_inline_user_message_editor(&row.id, cx)
        } else {
            self.render_user_message_inline_content(
                &row.id,
                row.body.clone(),
                attachments,
                search_query.as_deref(),
                cx,
            )
        };
        let hover_group: SharedString = format!("timeline-user-{}", row.id).into();
        let edit_text = row.body.clone();
        let edit_turn_id = turn_id.unwrap_or(&row.id).to_string();
        let edit_row_id = row.id.clone();
        let edit_source_session_id = self.selected_session_id.clone();
        let edit_user_sequence = row.first_sequence;
        let edit_source_end_sequence = self.timeline.authoritative_end_sequence;
        let edit_action_state = user_message_edit_action_state(
            latest_user_message,
            turn_complete,
            self.timeline.needs_authoritative_refetch,
            self.selected_agent_session_state(),
            self.agent_action_pending
                || self
                    .selected_session_id
                    .as_ref()
                    .is_some_and(|session_id| self.session_turn_pending(session_id)),
        );
        div()
            .flex()
            .w_full()
            .justify_end()
            .group(hover_group.clone())
            .child(
                v_flex()
                    .min_w_0()
                    .w(relative(0.78))
                    .items_end()
                    .gap_1()
                    .child(
                        render_user_message_bubble(
                            inline_content,
                            cx.theme().muted,
                            cx.theme().foreground,
                        )
                        .id(row.id.clone())
                        .when(editing, |this| this.w_full()),
                    )
                    .when(!editing, |this| {
                        this.child(
                            h_flex()
                                .items_center()
                                .gap_2()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .opacity(0.0)
                                .group_hover(hover_group, |style| style.opacity(1.0))
                                .when_some(timestamp, |this, timestamp| {
                                    this.child(format_timeline_hover_time(timestamp, locale))
                                })
                                .child(
                                    Button::new(format!("copy-user-message:{}", row.id))
                                        .xsmall()
                                        .ghost()
                                        .compact()
                                        .size(px(24.0))
                                        .icon(IconName::Copy)
                                        .tooltip(locale::text("Copy", "复制", "複製"))
                                        .on_click(move |_, _, cx| {
                                            cx.write_to_clipboard(copy_item.clone());
                                        }),
                                )
                                .when(
                                    edit_action_state != UserMessageEditActionState::Hidden,
                                    |this| {
                                        this.child(
                                            Button::new(format!("edit-user-message:{}", row.id))
                                                .xsmall()
                                                .ghost()
                                                .compact()
                                                .size(px(24.0))
                                                .icon(
                                                    Icon::default().path("icons/vibex/pencil.svg"),
                                                )
                                                .tooltip(locale::text("Edit", "编辑", "編輯"))
                                                .disabled(
                                                    edit_action_state
                                                        != UserMessageEditActionState::Enabled,
                                                )
                                                .on_click(cx.listener(
                                                    move |this, _, window, cx| {
                                                        let (
                                                            Some(source_session_id),
                                                            Some(source_end_sequence),
                                                        ) = (
                                                            edit_source_session_id.clone(),
                                                            edit_source_end_sequence,
                                                        )
                                                        else {
                                                            return;
                                                        };
                                                        this.begin_inline_user_message_edit(
                                                            edit_turn_id.clone(),
                                                            edit_row_id.clone(),
                                                            source_session_id,
                                                            edit_user_sequence,
                                                            source_end_sequence,
                                                            edit_text.clone(),
                                                            edit_attachments.clone(),
                                                            window,
                                                            cx,
                                                        )
                                                    },
                                                )),
                                        )
                                    },
                                ),
                        )
                    }),
            )
            .into_any_element()
    }

    fn render_child_agent_user_message_row(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let attachments = self
            .timeline_row_latest_item(row)
            .and_then(|item| match &item.payload {
                vibex_core::TimelinePayload::UserMessage(message) => {
                    Some(message.attachments.clone())
                }
                _ => None,
            })
            .unwrap_or_default();
        let search_query = self
            .session_search_highlight_query_for_rows(std::slice::from_ref(row))
            .map(str::to_string);
        let inline_content = self.render_user_message_inline_content(
            &row.id,
            row.body.clone(),
            attachments,
            search_query.as_deref(),
            cx,
        );
        div()
            .flex()
            .w_full()
            .justify_end()
            .child(
                v_flex()
                    .min_w_0()
                    .w(relative(0.78))
                    .items_end()
                    .gap_1()
                    .child(
                        render_user_message_bubble(
                            inline_content,
                            cx.theme().muted,
                            cx.theme().foreground,
                        )
                        .id(row.id.clone()),
                    ),
            )
            .into_any_element()
    }

    fn render_agent_message_row(
        &mut self,
        row: &TimelineRow,
        conversation_conclusion: bool,
        content_before_actions: Option<AnyElement>,
        answer_metadata: Option<AnyElement>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let search_query = self
            .session_search_highlight_query_for_rows(std::slice::from_ref(row))
            .map(str::to_string);
        let (markdown_source, markdown_sequence) = self.timeline_markdown_source(row);
        let markdown_entity = cx.weak_entity();
        let markdown_view = MarkdownView::new(
            format!("markdown:{}", row.id),
            MarkdownInput::new(
                markdown_source.clone(),
                "",
                u64::try_from(markdown_sequence).unwrap_or_default(),
            )
            .surface(MarkdownSurface::Agent),
        )
        .presentation(MarkdownPresentation::Agent)
        .streaming(row.streaming)
        .allow_http_images(true)
        .scroll_handle(self.timeline_scroll_handle())
        .search_query(search_query)
        .on_open_resource(move |resource, window, cx| {
            let _ = markdown_entity.update(cx, |this, cx| {
                this.open_markdown_resource(resource, window, cx)
            });
        });
        let timestamp = conversation_conclusion
            .then(|| self.timeline_row_timestamp(row))
            .flatten();
        let locale = self.resolved_locale();
        let hover_group: SharedString = format!("timeline-conclusion-{}", row.id).into();
        let fork_sequence = row.last_sequence;
        let fork_disabled = self.agent_action_pending
            || self.fork_session_pending
            || self.timeline.needs_authoritative_refetch;
        let scroll_to_user_message_turn_id = row.turn_id.clone();
        let show_answer_actions = !self.rendering_child_agent_timeline()
            && show_agent_answer_actions(conversation_conclusion, row);
        let answer_actions = if show_answer_actions {
            agent_answer_actions(timestamp.is_some())
                .filter_map(|action| match action {
                    AgentAnswerAction::Copy => {
                        let copy_text = markdown_source.clone();
                        Some(
                            Button::new(format!("copy-conclusion:{}", row.id))
                                .xsmall()
                                .ghost()
                                .compact()
                                .size(px(24.0))
                                .icon(IconName::Copy)
                                .tooltip(locale::text("Copy", "复制", "複製"))
                                .on_click(move |_, _, cx| {
                                    cx.write_to_clipboard(ClipboardItem::new_string(
                                        copy_text.to_string(),
                                    ));
                                })
                                .into_any_element(),
                        )
                    }
                    AgentAnswerAction::ScrollToUserMessage => {
                        scroll_to_user_message_turn_id.clone().map(|turn_id| {
                            Button::new(format!("scroll-to-user-message:{}", row.id))
                                .xsmall()
                                .ghost()
                                .compact()
                                .size(px(24.0))
                                .icon(Icon::default().path("icons/vibex/arrow-to-top.svg"))
                                .tooltip(locale::text(
                                    "Scroll to User Message",
                                    "滚动到用户消息",
                                    "捲動到使用者訊息",
                                ))
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.scroll_to_timeline_turn_top(&turn_id, cx)
                                }))
                                .into_any_element()
                        })
                    }
                    AgentAnswerAction::Fork => Some(
                        Button::new(format!("fork-conclusion:{}", row.id))
                            .xsmall()
                            .ghost()
                            .compact()
                            .size(px(24.0))
                            .icon(Icon::default().path("icons/vibex/git-branch.svg"))
                            .tooltip(locale::text("Fork", "分叉会话", "分支會話"))
                            .disabled(fork_disabled)
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.fork_session_at(fork_sequence, window, cx)
                            }))
                            .into_any_element(),
                    ),
                    AgentAnswerAction::Timestamp => timestamp.map(|timestamp| {
                        div()
                            .ml_1()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format_timeline_hover_time(timestamp, locale))
                            .into_any_element()
                    }),
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let show_answer_footer = answer_metadata.is_some() || show_answer_actions;
        v_flex()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .gap_1()
            .py_1()
            .when(conversation_conclusion, |this| {
                this.group(hover_group.clone())
            })
            .when(!row.body.is_empty(), |this| {
                this.child(div().w_full().min_w_0().child(markdown_view))
            })
            .when_some(content_before_actions, |this, content| {
                this.child(div().w_full().min_w_0().mt_2().child(content))
            })
            .when(show_answer_footer, |this| {
                this.child(
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .items_center()
                        .justify_between()
                        .gap_2()
                        .mt_2()
                        .when_some(answer_metadata, |this, metadata| {
                            this.child(div().min_w_0().flex_1().child(metadata))
                        })
                        .when(show_answer_actions, |this| {
                            this.child(
                                h_flex()
                                    .flex_none()
                                    .items_center()
                                    .gap_1()
                                    .opacity(0.0)
                                    .group_hover(hover_group.clone(), |style| style.opacity(1.0))
                                    .children(answer_actions),
                            )
                        }),
                )
            })
            .into_any_element()
    }

    fn reasoning_row_expanded(&self, row_id: &str) -> bool {
        self.reasoning_expansion
            .get(row_id)
            .copied()
            .unwrap_or(self.ui_state.session.reasoning_expanded_by_default)
    }

    fn toggle_reasoning_expansion(
        &mut self,
        row_id: String,
        turn_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        let expanded = self.reasoning_row_expanded(&row_id);
        self.reasoning_expansion.insert(row_id, !expanded);
        if let Some(turn_id) = turn_id {
            self.invalidate_timeline_turn_measurement(&turn_id);
        }
        self.rebuild_timeline_sizes();
        cx.notify();
    }

    fn reasoning_markdown_view(
        &mut self,
        id: impl Into<ElementId>,
        source: Arc<str>,
        sequence: u64,
        streaming: bool,
        search_query: Option<String>,
        cx: &mut Context<Self>,
    ) -> MarkdownView {
        let markdown_entity = cx.weak_entity();
        MarkdownView::new(
            id,
            MarkdownInput::new(source, "", sequence).surface(MarkdownSurface::Agent),
        )
        .presentation(MarkdownPresentation::Thought)
        .streaming(streaming)
        .allow_http_images(true)
        .scroll_handle(self.timeline_scroll_handle())
        .search_query(search_query)
        .on_open_resource(move |resource, window, cx| {
            let _ = markdown_entity.update(cx, |this, cx| {
                this.open_markdown_resource(resource, window, cx)
            });
        })
    }

    fn render_expanded_reasoning_layout(
        &mut self,
        row_id: String,
        turn_id: Option<String>,
        first_line: AnyElement,
        remaining: Option<AnyElement>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let tooltip = self.strings().agent_collapse_process;
        let toggle_id = row_id.clone();
        let connector_color = cx.theme().muted_foreground.opacity(0.46);
        let first_line_row = h_flex()
            .min_w_0()
            .items_center()
            .gap_2()
            .child(
                div()
                    .size(px(16.0))
                    .flex_none()
                    .items_center()
                    .justify_center()
                    .text_color(cx.theme().muted_foreground)
                    .child(
                        Icon::default()
                            .path("icons/vibex/brain.svg")
                            .size(px(14.0))
                            .text_color(cx.theme().muted_foreground),
                    ),
            )
            .child(
                h_flex()
                    .min_w_0()
                    .flex_1()
                    .items_center()
                    .gap_1()
                    .child(first_line)
                    .child(Icon::new(IconName::ChevronDown).size(px(14.0)).flex_none()),
            );
        let mut content = v_flex().min_w_0().flex_1().child(first_line_row);
        if let Some(remaining) = remaining {
            content = content.child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_stretch()
                    .gap_2()
                    .child(
                        v_flex()
                            .w(px(16.0))
                            .flex_none()
                            .items_center()
                            .child(div().w(px(1.0)).flex_1().bg(connector_color)),
                    )
                    .child(remaining),
            );
        }

        h_flex()
            .id(row_id)
            .w_full()
            .min_w_0()
            .items_stretch()
            .cursor_pointer()
            .tooltip(move |window, cx| Tooltip::new(tooltip).build(window, cx))
            .child(content)
            .on_click(cx.listener(move |this, _, _, cx| {
                this.toggle_reasoning_expansion(toggle_id.clone(), turn_id.clone(), cx)
            }))
            .into_any_element()
    }

    fn render_live_reasoning(
        &mut self,
        turn: &TimelineConversationTurn,
        body: &str,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let row_id = format!("reasoning-live:{}", turn.id);
        let expanded = self.reasoning_row_expanded(&row_id);
        let tooltip = self.strings().agent_expand_process;
        let turn_id = turn.id.clone();
        if expanded {
            let (first_line_source, remaining_source) = reasoning_source_parts(body);
            let first_line = self
                .reasoning_markdown_view(
                    format!("thought:{row_id}:first-line"),
                    Arc::<str>::from(first_line_source),
                    u64::try_from(body.len()).unwrap_or_default(),
                    true,
                    None,
                    cx,
                )
                .w_auto()
                .min_w_0()
                .max_w_full()
                .flex_shrink(1.0)
                .whitespace_normal()
                .into_any_element();
            let remaining = remaining_source.map(|source| {
                self.reasoning_markdown_view(
                    format!("thought:{row_id}:remaining"),
                    Arc::<str>::from(source),
                    u64::try_from(body.len()).unwrap_or_default(),
                    true,
                    None,
                    cx,
                )
                .w_full()
                .min_w_0()
                .text_color(cx.theme().muted_foreground)
                .into_any_element()
            });
            return self.render_expanded_reasoning_layout(
                row_id,
                Some(turn_id),
                first_line,
                remaining,
                cx,
            );
        }
        let sequence = i64::try_from(self.active_timeline().revision).unwrap_or(i64::MAX);
        let summary = timeline_reasoning_summary_cached_at(
            &mut self.timeline_reasoning_summaries,
            row_id.clone(),
            sequence,
            body,
            true,
            Instant::now(),
        );
        let content =
            render_agent_thinking_indicator(&row_id, &summary.preview, &summary.tooltip, cx);
        let toggle_id = row_id.clone();
        let mut container = h_flex()
            .id(row_id.clone())
            .w_full()
            .min_w_0()
            .items_center()
            .gap_1()
            .child(content);
        if summary.has_more {
            container = container
                .cursor_pointer()
                .tooltip(move |window, cx| Tooltip::new(tooltip).build(window, cx))
                .child(Icon::new(IconName::ChevronRight).size(px(14.0)).flex_none())
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.toggle_reasoning_expansion(toggle_id.clone(), Some(turn_id.clone()), cx)
                }));
        }
        container.into_any_element()
    }

    fn render_reasoning_row(&mut self, row: &TimelineRow, cx: &mut Context<Self>) -> AnyElement {
        if row.body.trim().is_empty() {
            return div().id(row.id.clone()).into_any_element();
        }
        let row_id = row.id.clone();
        let turn_id = row.turn_id.clone();
        let expanded = self.reasoning_row_expanded(&row_id);
        if expanded {
            let search_query = self
                .session_search_highlight_query_for_rows(std::slice::from_ref(row))
                .map(str::to_string);
            let (markdown_source, markdown_sequence) = self.timeline_markdown_source(row);
            let (first_line_source, remaining_source) = reasoning_source_parts(&markdown_source);
            let first_line = self
                .reasoning_markdown_view(
                    format!("thought:{}:first-line", row.id),
                    Arc::<str>::from(first_line_source),
                    u64::try_from(markdown_sequence).unwrap_or_default(),
                    row.streaming,
                    search_query.clone(),
                    cx,
                )
                .w_auto()
                .min_w_0()
                .max_w_full()
                .flex_shrink(1.0)
                .whitespace_normal()
                .into_any_element();
            let remaining = remaining_source.map(|source| {
                self.reasoning_markdown_view(
                    format!("thought:{}:remaining", row.id),
                    Arc::<str>::from(source),
                    u64::try_from(markdown_sequence).unwrap_or_default(),
                    row.streaming,
                    search_query,
                    cx,
                )
                .w_full()
                .min_w_0()
                .text_color(cx.theme().muted_foreground)
                .into_any_element()
            });
            return self
                .render_expanded_reasoning_layout(row_id, turn_id, first_line, remaining, cx);
        }
        let summary = timeline_reasoning_summary_cached_at(
            &mut self.timeline_reasoning_summaries,
            row_id.clone(),
            row.last_sequence,
            &row.body,
            row.streaming,
            Instant::now(),
        );
        let disclosure_visible = summary.has_more;
        let content = if row.streaming {
            render_agent_thinking_indicator(&row_id, &summary.preview, &summary.tooltip, cx)
        } else {
            div()
                .id(format!("reasoning-preview:{row_id}"))
                .min_w_0()
                .truncate()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(summary.preview.to_string())
                .into_any_element()
        };
        let tooltip = self.strings().agent_expand_process;
        let toggle_id = row_id.clone();
        let toggle_turn_id = turn_id.clone();
        // Keep the disclosure chevron beside the text content instead of
        // pushing it to the far edge of the row. The content is shrinkable, so
        // long previews still truncate before the chevron.
        let mut container = h_flex()
            .id(format!("reasoning-row:{row_id}"))
            .w_full()
            .min_w_0()
            .items_center()
            .gap_1()
            .text_color(cx.theme().muted_foreground)
            .child(content);
        if disclosure_visible {
            container = container
                .cursor_pointer()
                .tooltip(move |window, cx| Tooltip::new(tooltip).build(window, cx))
                .child(Icon::new(IconName::ChevronRight).size(px(14.0)).flex_none())
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.toggle_reasoning_expansion(toggle_id.clone(), toggle_turn_id.clone(), cx)
                }));
        }
        container.into_any_element()
    }

    fn render_thought_process_row(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if row.kind == TimelineRowKind::Reasoning {
            return self.render_reasoning_row(row, cx);
        }
        // Plans retain the compact muted markdown presentation used by the
        // existing process timeline.
        if row.body.is_empty() {
            return div().id(row.id.clone()).into_any_element();
        }
        let search_query = self
            .session_search_highlight_query_for_rows(std::slice::from_ref(row))
            .map(str::to_string);
        let (markdown_source, markdown_sequence) = self.timeline_markdown_source(row);
        let markdown_entity = cx.weak_entity();
        let markdown_view = MarkdownView::new(
            format!("thought:{}", row.id),
            MarkdownInput::new(
                markdown_source,
                "",
                u64::try_from(markdown_sequence).unwrap_or_default(),
            )
            .surface(MarkdownSurface::Agent),
        )
        .presentation(MarkdownPresentation::Thought)
        .streaming(row.streaming)
        .allow_http_images(true)
        .scroll_handle(self.timeline_scroll_handle())
        .search_query(search_query)
        .on_open_resource(move |resource, window, cx| {
            let _ = markdown_entity.update(cx, |this, cx| {
                this.open_markdown_resource(resource, window, cx)
            });
        });
        div()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .text_color(cx.theme().muted_foreground)
            .child(markdown_view)
            .into_any_element()
    }

    fn render_process_activity_group(
        &mut self,
        group: &TimelineProcessActivityGroup,
        rows: &[TimelineRow],
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let Some(latest_row) = rows.last() else {
            return div().id(group.id.clone()).into_any_element();
        };
        let projection = self.tool_card_projection_cached(latest_row);
        let expanded = self
            .timeline_command_expansion
            .get(&group.id)
            .copied()
            .unwrap_or(false);
        let expanded_rows = if expanded {
            rows.iter()
                .map(|row| self.render_process_activity_line(row, cx))
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let group_id = group.id.clone();
        let measured_turn_id = latest_row.turn_id.clone();
        let line_color = if projection.failed {
            cx.theme().danger
        } else {
            cx.theme().muted_foreground
        };
        let tooltip_text = if expanded {
            self.strings().agent_collapse_process
        } else {
            self.strings().agent_expand_process
        };
        let group_query = self
            .session_search_highlight_query_for_rows(rows)
            .unwrap_or_default();
        let highlighted_title = session_search_highlighted_text(
            projection.title.clone(),
            group_query,
            HighlightStyle {
                background_color: Some(cx.theme().warning.opacity(0.42)),
                font_weight: Some(FontWeight::BOLD),
                ..Default::default()
            },
        );

        v_flex()
            .id(group.id.clone())
            .w_full()
            .min_w_0()
            .gap_2()
            .child(
                h_flex()
                    .id(SharedString::from(format!("activity-summary:{}", group.id)))
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_2()
                    .cursor_pointer()
                    .text_sm()
                    .text_color(line_color)
                    .hover(|style| style.text_color(cx.theme().foreground))
                    .tooltip(move |window, cx| Tooltip::new(tooltip_text).build(window, cx))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        if let Some(turn_id) = measured_turn_id.as_deref() {
                            this.invalidate_timeline_turn_measurement(turn_id);
                        }
                        this.timeline_command_expansion
                            .insert(group_id.clone(), !expanded);
                        this.rebuild_timeline_sizes();
                        cx.notify();
                    }))
                    .child(
                        process_activity_icon(projection.icon)
                            .size(px(14.0))
                            .flex_none(),
                    )
                    // Keep the disclosure control beside the activity label. The label is
                    // still shrinkable, so long tool summaries truncate before the icon.
                    .child(div().min_w_0().truncate().child(highlighted_title))
                    .child(
                        Icon::new(if expanded {
                            IconName::ChevronDown
                        } else {
                            IconName::ChevronRight
                        })
                        .size(px(14.0))
                        .flex_none(),
                    ),
            )
            .when(expanded, |this| {
                this.child(
                    v_flex()
                        .w_full()
                        .min_w_0()
                        .pl_5()
                        .gap_2()
                        .children(expanded_rows),
                )
            })
            .into_any_element()
    }

    fn render_process_activity_line(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        // Lightweight tool activity is a single muted line. Commands and file
        // operations also use this projection when their card display is disabled.
        let projection = self.tool_card_projection_cached(row);
        let icon = process_activity_icon(projection.icon);
        let has_details = !projection.details.is_empty();
        let expanded = has_details
            && self
                .timeline_command_expansion
                .get(&row.id)
                .copied()
                .unwrap_or(false);
        let toggle_id = row.id.clone();
        let measured_turn_id = row.turn_id.clone();
        let line_color = if projection.failed {
            cx.theme().danger
        } else {
            cx.theme().muted_foreground
        };
        v_flex()
            .w_full()
            .min_w_0()
            .gap_2()
            .child(
                h_flex()
                    .id(SharedString::from(format!("activity:{}", row.id)))
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_2()
                    .text_sm()
                    .text_color(line_color)
                    .when(has_details, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.text_color(cx.theme().foreground))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(turn_id) = measured_turn_id.as_deref() {
                                    this.invalidate_timeline_turn_measurement(turn_id);
                                }
                                let expanded = this
                                    .timeline_command_expansion
                                    .get(&toggle_id)
                                    .copied()
                                    .unwrap_or(false);
                                this.timeline_command_expansion
                                    .insert(toggle_id.clone(), !expanded);
                                this.rebuild_timeline_sizes();
                                cx.notify();
                            }))
                    })
                    .child(icon.size(px(14.0)).flex_none())
                    .child(div().min_w_0().flex_1().truncate().child(
                        self.session_search_highlighted_row_text(row, projection.title.clone(), cx),
                    )),
            )
            .when(expanded, |this| {
                this.child(
                    v_flex().w_full().min_w_0().pl_6().gap_2().children(
                        projection
                            .details
                            .iter()
                            .map(|(label, value)| {
                                self.render_process_detail(label.clone(), value.clone(), cx)
                            })
                            .collect::<Vec<_>>(),
                    ),
                )
            })
            .when_some(row.file_path.clone().filter(|_| expanded), |this, path| {
                this.child(
                    div().pl_6().child(
                        Button::new(format!("open-agent-file-operation:{}", row.id))
                            .xsmall()
                            .outline()
                            .icon(IconName::FolderOpen)
                            .label(path.clone())
                            .tooltip(locale::text(
                                "Open Agent file operation in Preview",
                                "在预览中打开 Agent 文件操作",
                                "在預覽中開啟 Agent 檔案操作",
                            ))
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.open_code_file(path.clone(), window, cx)
                            })),
                    ),
                )
            })
            .into_any_element()
    }

    fn render_command_execution_card(
        &mut self,
        row: &TimelineRow,
        permission_row: Option<&TimelineRow>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let Some(command) =
            self.timeline_row_latest_item(row)
                .and_then(|item| match &item.payload {
                    vibex_core::TimelinePayload::Command(command) => Some(command.clone()),
                    _ => None,
                })
        else {
            return self.render_process_activity_line(row, cx);
        };
        let has_details = command.cwd.is_some()
            || command.output_summary.is_some()
            || command.exit_code.is_some()
            || !command.command.is_empty();
        let expanded = has_details
            && self
                .timeline_command_expansion
                .get(&row.id)
                .copied()
                .unwrap_or(false);
        let toggle_id = row.id.clone();
        let measured_turn_id = row.turn_id.clone();
        let failed = command.status == vibex_core::CommandStatus::Failed;
        let in_progress = command.status == vibex_core::CommandStatus::Started;
        let linked_permission = permission_row.and_then(|permission_row| {
            self.permission_request_for_row(permission_row)
                .map(|request| (permission_row, request))
        });
        let waiting_for_confirmation =
            linked_permission
                .as_ref()
                .is_some_and(|(permission_row, request)| {
                    permission_request_is_pending(permission_row, request)
                });
        let permission_panel = linked_permission.as_ref().map(|(permission_row, request)| {
            self.render_permission_request_panel(permission_row, request, true, cx)
        });
        let output_summary = (!waiting_for_confirmation)
            .then(|| command.output_summary.clone())
            .flatten();
        let command_title = if command.command.trim().is_empty() {
            locale::text("Command", "命令", "命令").to_string()
        } else {
            command.command.clone()
        };
        let card_bg = theme::semantic_color("card", cx.theme().is_dark());

        v_flex()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .flex_none()
            .overflow_hidden()
            .rounded_lg()
            .border_1()
            .border_color(if failed {
                cx.theme().danger.opacity(0.38)
            } else if waiting_for_confirmation {
                cx.theme().warning.opacity(0.42)
            } else {
                cx.theme().border
            })
            .bg(card_bg.opacity(0.72))
            .child(
                h_flex()
                    .id(SharedString::from(format!(
                        "command-card-header:{}",
                        row.id
                    )))
                    .w_full()
                    .min_w_0()
                    .min_h(px(40.0))
                    .items_center()
                    .gap_2()
                    .px_3()
                    .py_2()
                    .when(has_details, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.bg(cx.theme().muted.opacity(0.35)))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(turn_id) = measured_turn_id.as_deref() {
                                    this.invalidate_timeline_turn_measurement(turn_id);
                                }
                                this.timeline_command_expansion
                                    .insert(toggle_id.clone(), !expanded);
                                this.rebuild_timeline_sizes();
                                cx.notify();
                            }))
                    })
                    .child(
                        Icon::new(IconName::SquareTerminal)
                            .size(px(15.0))
                            .flex_none()
                            .text_color(if failed {
                                cx.theme().danger
                            } else if waiting_for_confirmation {
                                cx.theme().warning
                            } else {
                                cx.theme().muted_foreground
                            }),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .font_family(cx.theme().mono_font_family.clone())
                            .text_size(cx.theme().mono_font_size)
                            .font_weight(code_font_weight(cx))
                            .child(command_title),
                    )
                    .when(has_details, |this| {
                        this.child(
                            Icon::new(if expanded {
                                IconName::ChevronDown
                            } else {
                                IconName::ChevronRight
                            })
                            .size(px(14.0))
                            .flex_none()
                            .text_color(cx.theme().muted_foreground),
                        )
                    })
                    .child(Self::render_process_status_badge(
                        if waiting_for_confirmation {
                            self.strings().agent_waiting_confirmation.to_string()
                        } else {
                            command_status_label(command.status).to_string()
                        },
                        failed,
                        in_progress || waiting_for_confirmation,
                        cx,
                    )),
            )
            .when(expanded, |this| {
                this.child(
                    v_flex()
                        .w_full()
                        .min_w_0()
                        .gap_2()
                        .border_t_1()
                        .border_color(cx.theme().border.opacity(0.72))
                        .px_3()
                        .py_3()
                        .when_some(command.cwd.clone(), |this, cwd| {
                            this.child(
                                h_flex()
                                    .min_w_0()
                                    .gap_2()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(locale::text(
                                        "Working directory",
                                        "工作目录",
                                        "工作目錄",
                                    ))
                                    .child(
                                        div()
                                            .min_w_0()
                                            .truncate()
                                            .font_family(cx.theme().mono_font_family.clone())
                                            .font_weight(code_font_weight(cx))
                                            .child(cwd),
                                    ),
                            )
                        })
                        .child(
                            self.render_process_detail_value(format!("$ {}", command.command), cx),
                        )
                        .when_some(output_summary, |this, output| {
                            this.child(self.render_process_detail(
                                locale::text("Output", "输出", "輸出").to_string(),
                                output,
                                cx,
                            ))
                        })
                        .when_some(command.exit_code, |this, exit_code| {
                            this.child(
                                div()
                                    .text_xs()
                                    .text_color(if exit_code == 0 {
                                        cx.theme().success
                                    } else {
                                        cx.theme().danger
                                    })
                                    .child(format!(
                                        "{}: {exit_code}",
                                        locale::text("Exit code", "退出码", "結束代碼")
                                    )),
                            )
                        }),
                )
            })
            .when_some(permission_panel, |this, panel| this.child(panel))
            .into_any_element()
    }

    fn render_file_operation_card(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let Some(operation) =
            self.timeline_row_latest_item(row)
                .and_then(|item| match &item.payload {
                    vibex_core::TimelinePayload::FileOperation(operation) => {
                        Some(operation.clone())
                    }
                    _ => None,
                })
        else {
            return self.render_process_activity_line(row, cx);
        };
        let preview = self.agent_file_diff_preview_cached(row, &operation);
        let preview_scroll = self.agent_file_diff_scroll_handle(&row.id);
        let has_diff = file_operation_has_diff(&operation);
        let expanded = has_diff
            && self
                .timeline_command_expansion
                .get(&row.id)
                .copied()
                .unwrap_or(false);
        let toggle_id = row.id.clone();
        let measured_turn_id = row.turn_id.clone();
        let open_path = agent_file_operation_preview_path(
            &operation.path,
            self.selected_session()
                .map(|session| session.workspace_root.as_str()),
        );
        let title = format!(
            "{} {}",
            file_operation_verb(operation.operation),
            agent_turn_preview_file_name(&operation.path)
        );
        let card_bg = theme::semantic_color("card", cx.theme().is_dark());

        v_flex()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .flex_none()
            .overflow_hidden()
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .bg(card_bg.opacity(0.72))
            .child(
                h_flex()
                    .id(SharedString::from(format!("file-card-header:{}", row.id)))
                    .w_full()
                    .min_w_0()
                    .min_h(px(40.0))
                    .items_center()
                    .gap_2()
                    .px_3()
                    .py_2()
                    .when(has_diff, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.bg(cx.theme().muted.opacity(0.35)))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(turn_id) = measured_turn_id.as_deref() {
                                    this.invalidate_timeline_turn_measurement(turn_id);
                                }
                                this.timeline_command_expansion
                                    .insert(toggle_id.clone(), !expanded);
                                this.rebuild_timeline_sizes();
                                cx.notify();
                            }))
                    })
                    .child(
                        Icon::default()
                            .path("icons/vibex/file-text.svg")
                            .size(px(15.0))
                            .flex_none()
                            .text_color(cx.theme().muted_foreground),
                    )
                    .child(div().min_w_0().truncate().font_medium().child(title))
                    .when(has_diff, |this| {
                        this.child(
                            Icon::new(if expanded {
                                IconName::ChevronDown
                            } else {
                                IconName::ChevronRight
                            })
                            .size(px(14.0))
                            .flex_none()
                            .text_color(cx.theme().muted_foreground),
                        )
                    })
                    .when(preview.removed_lines > 0, |this| {
                        this.child(
                            div()
                                .flex_none()
                                .text_xs()
                                .font_family(cx.theme().mono_font_family.clone())
                                .font_weight(code_font_weight(cx))
                                .text_color(cx.theme().danger)
                                .child(format!("-{}", preview.removed_lines)),
                        )
                    })
                    .when(preview.added_lines > 0, |this| {
                        this.child(
                            div()
                                .flex_none()
                                .text_xs()
                                .font_family(cx.theme().mono_font_family.clone())
                                .font_weight(code_font_weight(cx))
                                .text_color(cx.theme().success)
                                .child(format!("+{}", preview.added_lines)),
                        )
                    })
                    .when_some(open_path, |this, open_path| {
                        this.child(
                            Button::new(format!("open-agent-file-card:{}", row.id))
                                .xsmall()
                                .ghost()
                                .compact()
                                .size(px(28.0))
                                .icon(IconName::FolderOpen)
                                .tooltip(locale::text(
                                    "Open file in Preview",
                                    "在预览中打开文件",
                                    "在預覽中開啟檔案",
                                ))
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    cx.stop_propagation();
                                    this.open_code_file(open_path.clone(), window, cx)
                                })),
                        )
                    }),
            )
            .when(expanded, |this| {
                this.child(self.render_agent_file_diff_preview(&preview, &preview_scroll, cx))
            })
            .into_any_element()
    }

    fn render_agent_file_diff_preview(
        &self,
        preview: &AgentFileDiffPreview,
        scroll: &gpui::ScrollHandle,
        cx: &App,
    ) -> AnyElement {
        if preview.lines.is_empty() {
            return div()
                .border_t_1()
                .border_color(cx.theme().border.opacity(0.72))
                .px_3()
                .py_3()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(locale::text(
                    "No text changes",
                    "没有文本变化",
                    "沒有文字變更",
                ))
                .into_any_element();
        }
        let rows = preview
            .lines
            .iter()
            .map(|line| {
                let (prefix, background, foreground) = match line.kind {
                    AgentFileDiffLineKind::Context => (
                        " ",
                        cx.theme().transparent,
                        cx.theme().foreground.opacity(0.82),
                    ),
                    AgentFileDiffLineKind::Add => {
                        ("+", cx.theme().success.opacity(0.11), cx.theme().success)
                    }
                    AgentFileDiffLineKind::Delete => {
                        ("-", cx.theme().danger.opacity(0.11), cx.theme().danger)
                    }
                    AgentFileDiffLineKind::Omitted => (
                        "…",
                        cx.theme().muted.opacity(0.42),
                        cx.theme().muted_foreground,
                    ),
                };
                h_flex()
                    .min_w_full()
                    .flex_none()
                    .items_start()
                    .bg(background)
                    .px_2()
                    .font_family(cx.theme().mono_font_family.clone())
                    .text_size(cx.theme().mono_font_size)
                    .font_weight(code_font_weight(cx))
                    .line_height(gpui::relative(1.5))
                    .text_color(foreground)
                    .child(div().w(px(18.0)).flex_none().child(prefix))
                    .child(div().whitespace_nowrap().child(line.text.clone()))
                    .into_any_element()
            })
            .collect::<Vec<_>>();
        render_agent_file_diff_scroll_area(rows, scroll, cx)
    }

    fn render_image_generation_card(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let Some(image) = self
            .timeline_row_latest_item(row)
            .and_then(|item| match &item.payload {
                vibex_core::TimelinePayload::ImageGeneration(image) => Some(image.clone()),
                _ => None,
            })
        else {
            return self.render_process_activity_line(row, cx);
        };
        let workspace_root = self
            .selected_session_id
            .as_ref()
            .and_then(|session_id| {
                self.sessions
                    .iter()
                    .find(|session| &session.id == session_id)
            })
            .map(|session| session.workspace_root.as_str());
        let preview_source = image
            .image_reference
            .as_deref()
            .and_then(|reference| generated_image_preview_source(reference, workspace_root));
        let in_progress = matches!(
            image.status,
            vibex_core::ToolCallStatus::Started | vibex_core::ToolCallStatus::Progress
        );
        let failed = image.status == vibex_core::ToolCallStatus::Failed;
        let has_details = in_progress || failed || image.image_reference.is_some();
        let expanded = has_details
            && self
                .timeline_command_expansion
                .get(&row.id)
                .copied()
                .unwrap_or(false);
        let toggle_id = row.id.clone();
        let measured_turn_id = row.turn_id.clone();
        let card_bg = theme::semantic_color("card", cx.theme().is_dark());
        let summary = if image.summary.trim().is_empty() {
            locale::text("Image generation", "图片生成", "圖片生成").to_string()
        } else {
            image.summary.clone()
        };

        v_flex()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .flex_none()
            .overflow_hidden()
            .rounded_lg()
            .border_1()
            .border_color(if failed {
                cx.theme().danger.opacity(0.38)
            } else {
                cx.theme().border
            })
            .bg(card_bg.opacity(0.72))
            .child(
                h_flex()
                    .id(SharedString::from(format!("image-card-header:{}", row.id)))
                    .w_full()
                    .min_w_0()
                    .min_h(px(40.0))
                    .items_center()
                    .gap_2()
                    .px_3()
                    .py_2()
                    .when(has_details, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.bg(cx.theme().muted.opacity(0.35)))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(turn_id) = measured_turn_id.as_deref() {
                                    this.invalidate_timeline_turn_measurement(turn_id);
                                }
                                this.timeline_command_expansion
                                    .insert(toggle_id.clone(), !expanded);
                                this.rebuild_timeline_sizes();
                                cx.notify();
                            }))
                    })
                    .child(
                        Icon::default()
                            .path("icons/vibex/image.svg")
                            .size(px(15.0))
                            .flex_none()
                            .text_color(if failed {
                                cx.theme().danger
                            } else {
                                cx.theme().muted_foreground
                            }),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .font_medium()
                            .child(summary.clone()),
                    )
                    .when(has_details, |this| {
                        this.child(
                            Icon::new(if expanded {
                                IconName::ChevronDown
                            } else {
                                IconName::ChevronRight
                            })
                            .size(px(14.0))
                            .flex_none()
                            .text_color(cx.theme().muted_foreground),
                        )
                    })
                    .child(Self::render_process_status_badge(
                        agent_activity_status_label(image.status).to_string(),
                        failed,
                        in_progress,
                        cx,
                    )),
            )
            .when(expanded, |this| {
                this.child(
                    v_flex()
                        .w_full()
                        .min_w_0()
                        .gap_2()
                        .border_t_1()
                        .border_color(cx.theme().border.opacity(0.72))
                        .p_3()
                        .when(in_progress, |this| {
                            this.child(
                                h_flex()
                                    .h(px(120.0))
                                    .w_full()
                                    .items_center()
                                    .justify_center()
                                    .gap_2()
                                    .text_sm()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(
                                        ProgressCircle::new(format!(
                                            "image-generation-progress:{}",
                                            row.id
                                        ))
                                        .size(px(22.0)),
                                    )
                                    .child(summary.clone()),
                            )
                        })
                        .when_some(preview_source.clone(), |this, source| {
                            let preview = match source {
                                GeneratedImagePreviewSource::Local(path) => img(path),
                                GeneratedImagePreviewSource::Remote(url) => img(url),
                            };
                            this.child(
                                div()
                                    .w_full()
                                    .h(px(240.0))
                                    .overflow_hidden()
                                    .rounded_md()
                                    .border_1()
                                    .border_color(cx.theme().border.opacity(0.72))
                                    .bg(cx.theme().muted.opacity(0.28))
                                    .child(preview.size_full().object_fit(ObjectFit::Contain)),
                            )
                        })
                        .when(
                            !in_progress
                                && preview_source.is_none()
                                && image.image_reference.is_some(),
                            |this| {
                                this.child(
                                    self.render_process_detail(
                                        locale::text("Image reference", "图片引用", "圖片參照")
                                            .to_string(),
                                        image.image_reference.clone().unwrap_or_default(),
                                        cx,
                                    ),
                                )
                            },
                        )
                        .when(failed, |this| {
                            this.child(
                                div()
                                    .text_sm()
                                    .text_color(cx.theme().danger)
                                    .child(summary.clone()),
                            )
                        }),
                )
            })
            .into_any_element()
    }

    fn render_error_row(
        &mut self,
        row: &TimelineRow,
        conversation_conclusion: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let recoverable = match self.timeline_row_latest_item(row).map(|item| &item.payload) {
            Some(vibex_core::TimelinePayload::Error(error)) => error.recoverable,
            _ => false,
        };
        let message = if row.body.is_empty() {
            row.title.clone()
        } else {
            row.body.clone()
        };
        if conversation_conclusion {
            // Tauri parity: `AgentConclusion` error tone text block with hover timestamp.
            let timestamp = self.timeline_row_timestamp(row);
            let locale = self.resolved_locale();
            let hover_group: SharedString = format!("timeline-conclusion-{}", row.id).into();
            let tone = if recoverable {
                cx.theme().warning
            } else {
                cx.theme().danger
            };
            let highlighted_message = self.session_search_highlighted_row_text(row, message, cx);
            return v_flex()
                .id(row.id.clone())
                .w_full()
                .min_w_0()
                .gap_1()
                .group(hover_group.clone())
                .child(
                    div()
                        .min_w_0()
                        .text_sm()
                        .line_height(gpui::relative(1.5))
                        .text_color(tone)
                        .child(highlighted_message),
                )
                .when_some(timestamp, |this, timestamp| {
                    this.child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .opacity(0.0)
                            .group_hover(hover_group, |style| style.opacity(1.0))
                            .child(format_timeline_hover_time(timestamp, locale)),
                    )
                })
                .into_any_element();
        }
        // Tauri parity: `AgentProcessErrorEvent` — tinted warning/destructive block.
        let tone = if recoverable {
            cx.theme().warning
        } else {
            cx.theme().danger
        };
        let label = if recoverable {
            locale::text("Warning", "警告", "警告")
        } else {
            locale::text("Error", "错误", "錯誤")
        };
        let highlighted_message = self.session_search_highlighted_row_text(row, message, cx);
        div()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .rounded_lg()
            .border_1()
            .border_color(tone.opacity(0.30))
            .bg(tone.opacity(0.10))
            .px_3()
            .py_2()
            .text_sm()
            .line_height(gpui::relative(1.5))
            .text_color(tone)
            .child(
                h_flex()
                    .min_w_0()
                    .flex_wrap()
                    .items_baseline()
                    .gap_1()
                    .child(div().flex_none().font_medium().child(label))
                    .child(div().flex_none().opacity(0.70).child("·"))
                    .child(div().min_w_0().child(highlighted_message)),
            )
            .into_any_element()
    }

    fn render_fallback_process_row(
        &mut self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        // Codex-parity: notices render as a single muted icon line.
        let icon = match row.kind {
            TimelineRowKind::GitNotice => Icon::default().path("icons/vibex/git-branch.svg"),
            _ => Icon::new(IconName::Info),
        };
        let summary = if row.body.is_empty() {
            row.title.clone()
        } else {
            row.body.clone()
        };
        let highlighted_summary = self.session_search_highlighted_row_text(row, summary, cx);
        h_flex()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .items_center()
            .gap_2()
            .text_sm()
            .text_color(cx.theme().muted_foreground)
            .child(icon.size(px(14.0)).flex_none())
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .truncate()
                    .child(highlighted_summary),
            )
            .into_any_element()
    }

    fn render_process_status_badge(
        label: String,
        failed: bool,
        in_progress: bool,
        cx: &App,
    ) -> AnyElement {
        // Tauri parity: shadcn Badge — h-5 rounded-full px-2 text-[0.625rem] uppercase.
        let badge = div()
            .flex_none()
            .h(px(20.0))
            .flex()
            .items_center()
            .rounded_full()
            .px_2()
            .text_xs()
            .font_medium()
            .child(label.to_uppercase());
        if failed {
            let alpha = if cx.theme().is_dark() { 0.20 } else { 0.10 };
            badge
                .bg(cx.theme().danger.opacity(alpha))
                .text_color(cx.theme().danger)
                .into_any_element()
        } else if in_progress {
            badge
                .bg(cx.theme().secondary)
                .text_color(cx.theme().secondary_foreground)
                .into_any_element()
        } else {
            badge
                .border_1()
                .border_color(cx.theme().border)
                .bg(cx.theme().input.opacity(0.20))
                .text_color(cx.theme().foreground)
                .into_any_element()
        }
    }

