fn agent_brand_identity(agent: &AgentSnapshotEntry) -> String {
    let mut identity = format!("{} {}", agent.id.as_str(), agent.label);
    if let Some(command) = agent.command.as_ref() {
        identity.push(' ');
        identity.push_str(&command.command);
    }
    if let Some(preset) = agent.params.get("preset") {
        identity.push(' ');
        if let Some(preset) = preset.as_str() {
            identity.push_str(preset);
        } else {
            identity.push_str(&preset.to_string());
        }
    }
    identity
}

fn runtime_agent_icon(identity: &str) -> AnyElement {
    agent_brand_icon(identity, px(16.0), None)
}

fn runtime_menu_agents(agents: &[AgentSnapshotEntry]) -> Vec<AgentSnapshotEntry> {
    let mut choices = agents
        .iter()
        .filter(|agent| is_new_session_agent_available(agent))
        .cloned()
        .collect::<Vec<_>>();
    choices.sort_by(|left, right| {
        left.order_index
            .cmp(&right.order_index)
            .then_with(|| left.label.cmp(&right.label))
            .then_with(|| left.id.cmp(&right.id))
    });
    choices
}

fn runtime_auth_sources_for_agent(
    catalog: &SessionRuntimeOptionCatalog,
    agent_id: &AgentId,
) -> Vec<RuntimeAuthSourceSummary> {
    let mut choices = catalog
        .auth_sources
        .iter()
        .filter(|source| &source.agent_id == agent_id)
        .cloned()
        .collect::<Vec<_>>();
    choices.sort_by(|left, right| {
        left.kind
            .cmp(&right.kind)
            .then_with(|| left.label.cmp(&right.label))
            .then_with(|| left.source.cmp(&right.source))
    });
    choices
}

fn runtime_auth_source_model_count(
    catalog: &SessionRuntimeOptionCatalog,
    agent_id: &AgentId,
    auth_source: &RuntimeAuthSource,
) -> usize {
    catalog
        .options
        .iter()
        .filter(|option| {
            &option.selection.agent_id == agent_id
                && &option.selection.auth_source == auth_source
                && option.availability == vibex_core::RuntimeOptionAvailability::Available
        })
        .map(|option| runtime_model_selection_key(&option.selection.model))
        .collect::<BTreeSet<_>>()
        .len()
}

fn runtime_model_choices(
    catalog: &SessionRuntimeOptionCatalog,
    agent_id: &AgentId,
    auth_source: &RuntimeAuthSource,
    preferred: Option<&SessionRuntimeSelection>,
    remembered: &[SessionRuntimeSelection],
) -> Vec<RuntimeCascadeChoice> {
    let Some(seed) = catalog.options.iter().find(|option| {
        option.availability == vibex_core::RuntimeOptionAvailability::Available
            && &option.selection.agent_id == agent_id
            && &option.selection.auth_source == auth_source
    }) else {
        return Vec::new();
    };
    let mut choices = RuntimeCascadeProjection::from_catalog(catalog, &seed.selection).models;
    for choice in &mut choices {
        let restored = preferred
            .filter(|selection| {
                runtime_selection_identity_matches(selection, &choice.selection)
                    && catalog_has_runtime_selection(catalog, selection)
            })
            .or_else(|| {
                remembered.iter().rev().find(|selection| {
                    runtime_selection_identity_matches(selection, &choice.selection)
                        && catalog_has_runtime_selection(catalog, selection)
                })
            });
        if let Some(restored) = restored {
            choice.selection = restored.clone();
        }
    }
    choices
}

