#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SidebarWorkspaceStatus {
    Running,
    Error,
    NeedsInput,
    UnreadCompletion,
    Complete,
}

fn sidebar_workspace_status(
    summary: vibex_desktop_model::WorkspaceAgentSummary,
    lifecycle_running: bool,
    lifecycle_error: bool,
    has_unread_completion: bool,
) -> SidebarWorkspaceStatus {
    if summary.running > 0 || lifecycle_running {
        SidebarWorkspaceStatus::Running
    } else if lifecycle_error || summary.failed > 0 {
        SidebarWorkspaceStatus::Error
    } else if summary.needs_input > 0 {
        SidebarWorkspaceStatus::NeedsInput
    } else if has_unread_completion {
        SidebarWorkspaceStatus::UnreadCompletion
    } else {
        SidebarWorkspaceStatus::Complete
    }
}

fn sidebar_session_status_indicator(
    state: AgentSessionState,
    auto_continue_enabled: bool,
    cx: &App,
) -> AnyElement {
    match state {
        AgentSessionState::Running | AgentSessionState::Initializing => Spinner::new()
            .icon(Icon::new(IconName::LoaderCircle))
            .color(if auto_continue_enabled {
                cx.theme().success
            } else {
                cx.theme().primary
            })
            .xsmall()
            .into_any_element(),
        AgentSessionState::NeedsInput => sidebar_status_dot(cx.theme().warning),
        AgentSessionState::Error => sidebar_status_dot(cx.theme().danger),
        AgentSessionState::Archived | AgentSessionState::Closed => {
            sidebar_status_dot(cx.theme().sidebar_foreground.opacity(0.35))
        }
        AgentSessionState::Idle => sidebar_status_dot(cx.theme().success.opacity(0.78)),
    }
}

fn sidebar_session_display_state(
    persisted_state: AgentSessionState,
    locally_pending: bool,
) -> AgentSessionState {
    if locally_pending {
        AgentSessionState::Running
    } else {
        persisted_state
    }
}

fn format_sidebar_session_time(
    timestamp_ms: i64,
    locale: locale::ResolvedLocale,
    strings: Strings,
) -> String {
    let Some(local_time) = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(timestamp_ms)
        .map(|timestamp| timestamp.with_timezone(&chrono::Local).naive_local())
    else {
        return String::new();
    };
    format_sidebar_session_time_at(
        local_time,
        chrono::Local::now().naive_local(),
        locale,
        strings,
    )
}

fn format_sidebar_session_time_at(
    local_time: chrono::NaiveDateTime,
    now: chrono::NaiveDateTime,
    locale: locale::ResolvedLocale,
    strings: Strings,
) -> String {
    let days = now
        .date()
        .signed_duration_since(local_time.date())
        .num_days();
    if days <= 0 {
        return local_time.format("%H:%M").to_string();
    }
    if days == 1 {
        return strings.sidebar_yesterday.to_string();
    }
    if days < 7 {
        return match locale {
            locale::ResolvedLocale::En => format!("{days} days ago"),
            locale::ResolvedLocale::ZhCn => format!("{days} 天前"),
            locale::ResolvedLocale::ZhTw => format!("{days} 天前"),
        };
    }
    if days < 30 {
        let weeks = days / 7;
        return match locale {
            locale::ResolvedLocale::En => format!("{weeks} weeks ago"),
            locale::ResolvedLocale::ZhCn => format!("{weeks} 周前"),
            locale::ResolvedLocale::ZhTw => format!("{weeks} 週前"),
        };
    }
    local_time.format("%m/%d").to_string()
}

#[cfg(test)]
fn project_workspace_matches_search(
    project: &ProjectRecord,
    workspace: &WorkspaceRecord,
    normalized_query: &str,
) -> bool {
    normalized_query.is_empty()
        || [&project.name, &project.root_path, &workspace.root_path]
            .into_iter()
            .any(|value| value.to_lowercase().contains(normalized_query))
}

fn workspace_display_name(workspace_root: &str) -> String {
    std::path::Path::new(workspace_root)
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.is_empty())
        .unwrap_or(workspace_root)
        .to_string()
}

fn workbench_window_controls(wide: bool, cx: &App) -> AnyElement {
    let control_width = if wide {
        TITLE_BAR_WIDE_WINDOW_CONTROL_WIDTH
    } else {
        TITLE_BAR_NARROW_WINDOW_CONTROL_WIDTH
    };
    let foreground = cx.theme().foreground.opacity(0.7);
    let hover_background = cx.theme().sidebar_accent;
    let hover_foreground = cx.theme().sidebar_accent_foreground;
    let active_background = cx.theme().sidebar_accent.opacity(0.8);
    let close_background = cx.theme().danger;
    let close_foreground = cx.theme().danger_foreground;

    h_flex()
        .id("window-controls")
        .h_full()
        .flex_none()
        .items_stretch()
        .border_l_1()
        .border_color(cx.theme().border)
        .bg(cx.theme().background)
        .child(
            div()
                .id("window-minimize")
                .flex()
                .h_full()
                .w(px(control_width))
                .flex_none()
                .items_center()
                .justify_center()
                .text_color(foreground)
                .hover(move |style| style.bg(hover_background).text_color(hover_foreground))
                .active(move |style| style.bg(active_background).text_color(hover_foreground))
                .when(cfg!(target_os = "windows"), |this| {
                    this.window_control_area(WindowControlArea::Min)
                })
                .when(!cfg!(target_os = "windows"), |this| {
                    this.on_mouse_down(MouseButton::Left, |_, window, cx| {
                        window.prevent_default();
                        cx.stop_propagation();
                    })
                    .on_click(|_, window, cx| {
                        cx.stop_propagation();
                        window.minimize_window();
                    })
                })
                .child(Icon::new(IconName::Minus).size(px(16.0))),
        )
        .child(
            div()
                .id("window-maximize")
                .flex()
                .h_full()
                .w(px(control_width))
                .flex_none()
                .items_center()
                .justify_center()
                .text_color(foreground)
                .hover(move |style| style.bg(hover_background).text_color(hover_foreground))
                .active(move |style| style.bg(active_background).text_color(hover_foreground))
                .when(cfg!(target_os = "windows"), |this| {
                    this.window_control_area(WindowControlArea::Max)
                })
                .when(!cfg!(target_os = "windows"), |this| {
                    this.on_mouse_down(MouseButton::Left, |_, window, cx| {
                        window.prevent_default();
                        cx.stop_propagation();
                    })
                    .on_click(|_, window, cx| {
                        cx.stop_propagation();
                        window.zoom_window();
                    })
                })
                .child(Icon::new(IconName::WindowMaximize).size(px(16.0))),
        )
        .child(
            div()
                .id("window-close")
                .flex()
                .h_full()
                .w(px(control_width))
                .flex_none()
                .items_center()
                .justify_center()
                .text_color(foreground)
                .hover(move |style| style.bg(close_background).text_color(close_foreground))
                .active(move |style| style.bg(close_background).text_color(close_foreground))
                .when(cfg!(target_os = "windows"), |this| {
                    this.window_control_area(WindowControlArea::Close)
                })
                .when(!cfg!(target_os = "windows"), |this| {
                    this.on_mouse_down(MouseButton::Left, |_, window, cx| {
                        window.prevent_default();
                        cx.stop_propagation();
                    })
                    .on_click(|_, window, cx| {
                        cx.stop_propagation();
                        window.remove_window();
                    })
                })
                .child(Icon::new(IconName::Close).size(px(16.0))),
        )
        .into_any_element()
}

fn context_window_usage_fraction(usage: &AgentTokenUsage) -> Option<f32> {
    let used = usage.context_window_used_tokens?;
    let size = usage.context_window_size_tokens?;
    if size == 0 {
        return None;
    }
    Some(((used as f64 / size as f64).clamp(0.0, 1.0)) as f32)
}

fn cache_hit_fraction(usage: &AgentTokenUsage) -> Option<f32> {
    let input = usage.input_tokens?;
    let cached = usage.cached_read_tokens?;
    let total = input.saturating_add(cached);
    if total == 0 {
        return Some(0.0);
    }
    Some((cached as f64 / total as f64) as f32)
}

fn token_usage_percent(fraction: f32) -> u32 {
    (fraction.clamp(0.0, 1.0) * 100.0).round() as u32
}

fn format_compact_tokens(tokens: u64) -> String {
    if tokens >= 1_000_000 {
        format!("{:.1}m", tokens as f64 / 1_000_000.0)
    } else if tokens >= 1_000 {
        format!("{:.1}k", tokens as f64 / 1_000.0)
    } else {
        tokens.to_string()
    }
}

fn render_cache_token_ring(usage: Option<&AgentTokenUsage>, cx: &mut App) -> AnyElement {
    let is_dark = cx.theme().is_dark();
    let track_color = theme::semantic_color("muted", is_dark);
    let context_fraction = usage.and_then(context_window_usage_fraction);
    let progress_color = match context_fraction {
        Some(fraction) if fraction > 0.9 => theme::semantic_color("destructive", is_dark),
        Some(fraction) if fraction >= 0.7 => theme::semantic_color("warning", is_dark),
        Some(_) => theme::semantic_color("muted-foreground", is_dark),
        None => theme::semantic_color("muted-foreground", is_dark).opacity(0.45),
    };
    let overview_label = locale::text("Token usage", "Token 使用情况", "Token 使用情況");
    let context_value = match usage.and_then(|usage| {
        Some((
            context_window_usage_fraction(usage)?,
            usage.context_window_used_tokens?,
            usage.context_window_size_tokens?,
        ))
    }) {
        Some((fraction, used, size)) => match locale::current_locale() {
            locale::ResolvedLocale::En => format!(
                "Context {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
            locale::ResolvedLocale::ZhCn => format!(
                "上下文 {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
            locale::ResolvedLocale::ZhTw => format!(
                "上下文 {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
        },
        None => locale::text(
            "Context window not reported",
            "Agent 未上报上下文窗口",
            "Agent 未回報上下文視窗",
        )
        .to_string(),
    };
    let cache_value = match usage {
        Some(usage) if usage.cached_read_tokens.is_some() => {
            let cached_read = usage.cached_read_tokens.unwrap_or_default();
            let cached_write = usage.cached_write_tokens;
            let hit_prefix = cache_hit_fraction(usage)
                .map(|fraction| format!("{}% · ", token_usage_percent(fraction)))
                .unwrap_or_default();
            match (locale::current_locale(), cached_write) {
                (locale::ResolvedLocale::En, Some(written)) => format!(
                    "Cache {hit_prefix}{} read · {} written",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::En, None) => {
                    format!(
                        "Cache {hit_prefix}{} read",
                        format_compact_tokens(cached_read)
                    )
                }
                (locale::ResolvedLocale::ZhCn, Some(written)) => format!(
                    "缓存 {hit_prefix}读取 {} · 写入 {}",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::ZhCn, None) => format!(
                    "缓存 {hit_prefix}读取 {}",
                    format_compact_tokens(cached_read)
                ),
                (locale::ResolvedLocale::ZhTw, Some(written)) => format!(
                    "快取 {hit_prefix}讀取 {} · 寫入 {}",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::ZhTw, None) => format!(
                    "快取 {hit_prefix}讀取 {}",
                    format_compact_tokens(cached_read)
                ),
            }
        }
        _ => locale::text(
            "Cache usage not reported",
            "Agent 未上报缓存用量",
            "Agent 未回報快取用量",
        )
        .to_string(),
    };
    div()
        .id("composer-cache-token-ring")
        .flex_none()
        .size(px(28.0))
        .flex()
        .items_center()
        .justify_center()
        .child(
            canvas(
                |_, _, _| (),
                move |bounds, _, window, _| {
                    let stroke_width = px(2.5);
                    let radius = px(7.0);
                    let center_x = bounds.origin.x + bounds.size.width / 2.0;
                    let center_y = bounds.origin.y + bounds.size.height / 2.0;

                    let mut track = PathBuilder::stroke(stroke_width);
                    track.move_to(point(center_x + radius, center_y));
                    track.arc_to(
                        point(radius, radius),
                        px(0.0),
                        false,
                        true,
                        point(center_x - radius, center_y),
                    );
                    track.arc_to(
                        point(radius, radius),
                        px(0.0),
                        false,
                        true,
                        point(center_x + radius, center_y),
                    );
                    track.close();
                    if let Ok(path) = track.build() {
                        window.paint_path(path, track_color);
                    }

                    let Some(progress) = context_fraction.filter(|progress| *progress > 0.0) else {
                        return;
                    };
                    let mut foreground = PathBuilder::stroke(stroke_width);
                    if progress >= 0.999 {
                        foreground.move_to(point(center_x + radius, center_y));
                        foreground.arc_to(
                            point(radius, radius),
                            px(0.0),
                            false,
                            true,
                            point(center_x - radius, center_y),
                        );
                        foreground.arc_to(
                            point(radius, radius),
                            px(0.0),
                            false,
                            true,
                            point(center_x + radius, center_y),
                        );
                        foreground.close();
                    } else {
                        foreground.move_to(point(center_x, center_y - radius));
                        let angle =
                            -std::f32::consts::PI / 2.0 + progress * 2.0 * std::f32::consts::PI;
                        foreground.arc_to(
                            point(radius, radius),
                            px(0.0),
                            progress > 0.5,
                            true,
                            point(
                                center_x + radius * angle.cos(),
                                center_y + radius * angle.sin(),
                            ),
                        );
                    }
                    if let Ok(path) = foreground.build() {
                        window.paint_path(path, progress_color);
                    }
                },
            )
            .size(px(17.0)),
        )
        .tooltip(move |window, cx| {
            let context_value = context_value.clone();
            let cache_value = cache_value.clone();
            Tooltip::element(move |_, cx| {
                v_flex()
                    .gap(px(2.0))
                    .text_xs()
                    .child(div().font_medium().child(overview_label))
                    .child(
                        div()
                            .text_color(cx.theme().popover_foreground.opacity(0.75))
                            .child(context_value.clone()),
                    )
                    .child(
                        div()
                            .text_color(cx.theme().popover_foreground.opacity(0.75))
                            .child(cache_value.clone()),
                    )
            })
            .build(window, cx)
        })
        .into_any_element()
}

// Tauri parity: `MobilePairIcon` gradient stops oklch(0.7 0.24 25) / (0.84 0.22 90) /
// (0.76 0.22 150) / (0.72 0.22 220) converted to sRGB.
const MOBILE_PAIR_GRADIENT: [u32; 4] = [0xff464a, 0xffc000, 0x00d55e, 0x00beff];
const MOBILE_PAIR_GRADIENT_DURATION: Duration = Duration::from_millis(2400);

fn mobile_pair_gradient_color(position: f32) -> Hsla {
    let wrapped = position.rem_euclid(MOBILE_PAIR_GRADIENT.len() as f32);
    let index = wrapped.floor() as usize % MOBILE_PAIR_GRADIENT.len();
    let next = (index + 1) % MOBILE_PAIR_GRADIENT.len();
    let fraction = wrapped.fract();
    let from = rgb(MOBILE_PAIR_GRADIENT[index]);
    let to = rgb(MOBILE_PAIR_GRADIENT[next]);
    Hsla::from(Rgba {
        r: from.r + (to.r - from.r) * fraction,
        g: from.g + (to.g - from.g) * fraction,
        b: from.b + (to.b - from.b) * fraction,
        a: 1.0,
    })
}

fn composite_over(source: Hsla, destination: Hsla) -> Hsla {
    let source = Rgba::from(source);
    let destination = Rgba::from(destination);
    let alpha = source.a;
    Hsla::from(Rgba {
        r: source.r * alpha + destination.r * (1.0 - alpha),
        g: source.g * alpha + destination.g * (1.0 - alpha),
        b: source.b * alpha + destination.b * (1.0 - alpha),
        a: 1.0,
    })
}

fn mobile_pair_icon(hovered: bool, cx: &App) -> AnyElement {
    // Tauri parity: 24-unit viewBox phone at 20px display size — outer bounds
    // 13.33 x 18.33, stroke 1.67, corner radius 2.5, dot centered near the bottom.
    let width = px(13.33);
    let height = px(18.33);
    let border = px(1.67);
    let radius = px(2.5);
    let dot_size = px(1.8);
    let dot_left = px((13.33 - 1.8) / 2.0);
    let dot_bottom = px(2.4);
    let foreground = cx.theme().foreground;
    if !hovered {
        return div()
            .relative()
            .w(width)
            .h(height)
            .rounded(radius)
            .border(border)
            .border_color(foreground.opacity(0.75))
            .child(
                div()
                    .absolute()
                    .bottom(px(2.4 - 1.67))
                    .left(px((13.33 - 1.8) / 2.0 - 1.67))
                    .size(dot_size)
                    .rounded_full()
                    .bg(foreground.opacity(0.75)),
            )
            .into_any_element();
    }
    // Hover: the border fades into a moving four-stop gradient (Tauri animates the
    // gradient transform over 2.4s). Simulated with a gradient-filled outer layer
    // and an interior filled with the ghost-hover background composited over the
    // title bar, leaving a 1.67px gradient ring.
    let hover_background = if cx.theme().is_dark() {
        cx.theme().secondary.lighten(0.1).opacity(0.8)
    } else {
        cx.theme().secondary.darken(0.1).opacity(0.8)
    };
    let interior = composite_over(hover_background, cx.theme().sidebar);
    div()
        .relative()
        .w(width)
        .h(height)
        .child(div().absolute().inset_0().rounded(radius).with_animation(
            "mobile-pair-gradient",
            Animation::new(MOBILE_PAIR_GRADIENT_DURATION).repeat(),
            move |this, delta| {
                let position = delta * MOBILE_PAIR_GRADIENT.len() as f32;
                this.bg(linear_gradient(
                    135.0,
                    linear_color_stop(mobile_pair_gradient_color(position), 0.0),
                    linear_color_stop(mobile_pair_gradient_color(position + 1.0), 1.0),
                ))
            },
        ))
        .child(
            div()
                .absolute()
                .top(border)
                .left(border)
                .right(border)
                .bottom(border)
                .rounded(px(1.2))
                .bg(interior),
        )
        .child(
            div()
                .absolute()
                .bottom(dot_bottom)
                .left(dot_left)
                .size(dot_size)
                .rounded_full()
                .bg(foreground.opacity(0.9)),
        )
        .into_any_element()
}

