    fn toggle_current_auto_continue(&mut self, cx: &mut Context<Self>) {
        let _ = self.workbench.update(cx, |this, cx| {
            if let Some(session) = this.selected_session().cloned() {
                let enabled = this.auto_continue_enabled(&session.id);
                this.set_auto_continue_enabled(session.id, !enabled, cx);
            } else if let Some(project_id) = this
                .ui_state
                .workbench
                .selected_workspace_id
                .as_deref()
                .and_then(|workspace_id| {
                    this.workspaces
                        .iter()
                        .find(|(_, workspace)| workspace.id.as_str() == workspace_id)
                        .map(|(project, _)| project.id.clone())
                })
            {
                let enabled = this.project_auto_continue_enabled(&project_id);
                this.set_project_auto_continue_enabled(project_id, !enabled, cx);
            }
        });
        cx.notify();
    }

    fn open_custom_shell_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let entity = cx.weak_entity();
        let initial = self.terminal_preferences(cx).shell.unwrap_or_default();
        window.open_dialog(cx, move |dialog, window, cx| {
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .default_value(initial.clone())
                    .placeholder(locale::text("Shell path", "Shell 路径", "Shell 路徑"))
            });
            let apply = entity.clone();
            dialog
                .title(locale::text("Custom shell", "自定义 Shell", "自訂 Shell"))
                .w(px(420.0))
                .child(Input::new(&input).w_full())
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-shell")
                                    .outline()
                                    .label(locale::text("Cancel", "取消", "取消")),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("apply-shell")
                                    .primary()
                                    .label(locale::text("Apply", "应用", "套用")),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let value = input.read(cx).value().trim().to_string();
                    if value.is_empty() || std::path::Path::new(&value).is_file() {
                        let _ = apply.update(cx, |settings, cx| {
                            settings.set_terminal_shell(value, cx);
                            settings.operation_note = None;
                            cx.notify();
                        });
                        true
                    } else {
                        let _ = apply.update(cx, |settings, cx| {
                            settings.operation_note = Some(
                                locale::text(
                                    "Shell path does not exist",
                                    "Shell 路径不存在",
                                    "Shell 路徑不存在",
                                )
                                .to_string(),
                            );
                            cx.notify();
                        });
                        false
                    }
                })
        });
    }

    fn open_shortcut_dialog(
        &mut self,
        action: String,
        current: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let entity = cx.weak_entity();
        let action_label = shortcut_action_label(&action);
        window.open_dialog(cx, move |dialog, window, cx| {
            let input = cx.new(|cx| {
                InputState::new(window, cx)
                    .default_value(current.clone())
                    .placeholder("cmd-shift-p")
            });
            let apply = entity.clone();
            let action_for_apply = action.clone();
            dialog
                .title(format!(
                    "{}: {}",
                    locale::text("Shortcut", "快捷键", "快速鍵"),
                    action_label
                ))
                .w(px(420.0))
                .child(Input::new(&input).w_full())
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-shortcut")
                                    .outline()
                                    .label(locale::text("Cancel", "取消", "取消")),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("apply-shortcut")
                                    .primary()
                                    .label(locale::text("Apply", "应用", "套用")),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let value = input.read(cx).value().to_string();
                    apply
                        .update(cx, |settings, cx| {
                            settings.set_shortcut(action_for_apply.clone(), value, cx)
                        })
                        .unwrap_or(false)
                })
        });
    }

    fn render_navigation(
        &self,
        wide: bool,
        strings: Strings,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let is_dark = cx.theme().is_dark();
        let foreground = theme::semantic_color("foreground", is_dark);
        let muted_foreground = theme::semantic_color("muted-foreground", is_dark);
        let border = theme::semantic_color("border", is_dark);
        let sidebar_accent = theme::semantic_color("sidebar-accent", is_dark);
        let sections = [
            (
                SettingsSection::General,
                strings.general,
                IconName::Settings2,
            ),
            (
                SettingsSection::Appearance,
                strings.appearance,
                IconName::Palette,
            ),
            (
                SettingsSection::Workbench,
                locale::text("Workbench", "工作台", "工作台"),
                IconName::LayoutDashboard,
            ),
            (
                SettingsSection::Session,
                strings.session_settings,
                IconName::Bot,
            ),
            (
                SettingsSection::Terminal,
                locale::text("Terminal", "终端", "終端機"),
                IconName::SquareTerminal,
            ),
            (
                SettingsSection::Shortcuts,
                locale::text("Shortcuts", "快捷键", "快速鍵"),
                IconName::CaseSensitive,
            ),
            (
                SettingsSection::Data,
                locale::text("Data & Diagnostics", "数据与诊断", "資料與診斷"),
                IconName::HardDrive,
            ),
            (
                SettingsSection::About,
                locale::text("About", "关于", "關於"),
                IconName::Info,
            ),
        ];
        let mut buttons = sections
            .into_iter()
            .map(|(section, label, icon)| {
                let active = self.active_section == section;
                let icon = Icon::new(icon)
                    .size(px(16.0))
                    .mr(px(2.0))
                    .text_color(if active { foreground } else { muted_foreground });
                Button::new(SharedString::from(format!("settings-{section:?}")))
                    .small()
                    .ghost()
                    .h(px(SETTINGS_NAVIGATION_ROW_HEIGHT))
                    .px_3()
                    .rounded(px(6.0))
                    .selected(active)
                    .text_color(if active { foreground } else { muted_foreground })
                    .when(active, |this| this.bg(sidebar_accent.opacity(0.34)))
                    .when(wide, |this| this.w_full())
                    .when(!wide, |this| this.min_w(px(112.0)).flex_1())
                    .icon(icon)
                    .label(label)
                    .child(div().flex_1())
                    .tooltip(label)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.activate_settings_section(section, cx);
                        cx.notify();
                    }))
                    .into_any_element()
            })
            .collect::<Vec<_>>();
        let search = div()
            .w_full()
            .mt_1()
            .mb_1()
            .capture_key_down(cx.listener(Self::on_settings_search_key_down))
            .child(
                Input::new(&self.search)
                    .small()
                    .h(px(34.0))
                    .w_full()
                    .prefix(
                        Icon::new(IconName::Search)
                            .small()
                            .text_color(muted_foreground),
                    ),
            );
        let search_results = self.render_search_results(strings, cx);
        let has_search_results = search_results.is_some();

        if !wide {
            return v_flex()
                .w_full()
                .gap_2()
                .child(search)
                .when_some(search_results, |this, results| this.child(results))
                .when(!has_search_results, |this| {
                    this.child(div().flex().flex_wrap().gap_1().children(buttons))
                })
                .into_any_element();
        }

        let support = buttons.split_off(6);
        let workflow = buttons.split_off(2);
        let group_label = |label| {
            div()
                .px_2()
                .pb_1()
                .text_xs()
                .font_medium()
                .text_color(muted_foreground.opacity(0.72))
                .child(label)
        };
        let navigation_groups = v_flex()
            .gap_2()
            .child(
                v_flex()
                    .gap(px(SETTINGS_NAVIGATION_SECTION_GAP))
                    .child(group_label(locale::text("VIBEX", "偏好设置", "偏好設定")))
                    .children(buttons),
            )
            .child(
                v_flex()
                    .gap(px(SETTINGS_NAVIGATION_SECTION_GAP))
                    .child(group_label(locale::text("WORKSPACE", "工作流", "工作流程")))
                    .children(workflow),
            )
            .child(
                v_flex()
                    .gap(px(SETTINGS_NAVIGATION_SECTION_GAP))
                    .child(group_label(locale::text("SUPPORT", "支持", "支援")))
                    .children(support),
            );

        v_flex()
            .w(px(SETTINGS_NAVIGATION_WIDTH))
            .h_full()
            .flex_none()
            .overflow_hidden()
            .gap_2()
            .px_4()
            .pt_3()
            .border_r_1()
            .border_color(border.opacity(0.72))
            .bg(theme::semantic_color("sidebar", is_dark))
            .child(search)
            .when_some(search_results, |this, results| this.child(results))
            .when(!has_search_results, |this| this.child(navigation_groups))
            .into_any_element()
    }

    fn render_general_page(
        &self,
        desktop_behavior: &DesktopBehaviorUiState,
        network_proxy: &NetworkProxyUiState,
        stacked: bool,
        strings: Strings,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let is_dark = cx.theme().is_dark();
        let input = theme::semantic_color("input", is_dark);
        let input_background = input.opacity(if is_dark { 0.30 } else { 0.20 });
        let language_select = div().h(px(28.0)).w(px(160.0)).child(
            Select::new(&self.language_modes)
                .small()
                .h(px(28.0))
                .rounded(px(8.0))
                .border_color(input)
                .bg(input_background)
                .text_xs()
                .placeholder(strings.system_default),
        );
        let close_to_tray_switch = Switch::new("close-to-tray")
            .small()
            .checked(desktop_behavior.close_to_tray)
            .tooltip(strings.close_to_tray)
            .on_click(cx.listener(|this, enabled, _, cx| this.set_close_to_tray(*enabled, cx)));
        let proxy_value = self.proxy_input.read(cx).value().to_string();
        let proxy_error = network_proxy.enabled.then(|| {
            if proxy_value.trim().is_empty() {
                strings.network_proxy_required
            } else if vibex_desktop_runtime::network_proxy::normalize_proxy_url(&proxy_value)
                .is_err()
            {
                strings.network_proxy_invalid
            } else {
                ""
            }
        });
        let proxy_control = v_flex()
            .items_end()
            .gap_1()
            .child(
                h_flex()
                    .gap_2()
                    .child(
                        Switch::new("network-proxy-enabled")
                            .small()
                            .checked(network_proxy.enabled)
                            .tooltip(strings.network_proxy_enabled)
                            .on_click(cx.listener(|this, enabled, _, cx| {
                                this.set_network_proxy_enabled(*enabled, cx)
                            })),
                    )
                    .child(Input::new(&self.proxy_input).w(px(260.0)).h(px(32.0))),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(strings.network_proxy_hint),
            )
            .when_some(
                proxy_error.filter(|error| !error.is_empty()),
                |this, error| {
                    this.child(div().text_xs().text_color(cx.theme().danger).child(error))
                },
            );
        let startup_new_session =
            desktop_behavior.startup_destination == StartupDestination::NewSession;
        let startup_control = h_flex()
            .gap_1()
            .child(
                Button::new("startup-restore")
                    .small()
                    .outline()
                    .selected(!startup_new_session)
                    .label(locale::text("Restore", "恢复工作台", "還原工作台"))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.set_startup_destination(StartupDestination::RestoreWorkbench, cx)
                    })),
            )
            .child(
                Button::new("startup-new-session")
                    .small()
                    .outline()
                    .selected(startup_new_session)
                    .label(locale::text("New session", "新会话", "新會話"))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.set_startup_destination(StartupDestination::NewSession, cx)
                    })),
            );
        let launch_at_login = Switch::new("launch-at-login")
            .small()
            .checked(desktop_behavior.launch_at_login)
            .on_click(cx.listener(|this, enabled, _, cx| this.set_launch_at_login(*enabled, cx)));
        let notifications = Switch::new("notifications-enabled")
            .small()
            .checked(desktop_behavior.notifications_enabled)
            .on_click(
                cx.listener(|this, enabled, _, cx| this.set_notifications_enabled(*enabled, cx)),
            );
        let update_prompts = Switch::new("update-prompts-enabled")
            .small()
            .checked(desktop_behavior.show_update_prompts)
            .on_click(
                cx.listener(|this, enabled, _, cx| this.set_show_update_prompts(*enabled, cx)),
            );
        let completed_notifications = Switch::new("notify-completed")
            .small()
            .checked(desktop_behavior.notify_agent_completed)
            .disabled(!desktop_behavior.notifications_enabled)
            .on_click(cx.listener(|this, enabled, _, cx| {
                this.set_notification_kind(NotificationKind::Completed, *enabled, cx)
            }));
        let needs_input_notifications = Switch::new("notify-needs-input")
            .small()
            .checked(desktop_behavior.notify_agent_needs_input)
            .disabled(!desktop_behavior.notifications_enabled)
            .on_click(cx.listener(|this, enabled, _, cx| {
                this.set_notification_kind(NotificationKind::NeedsInput, *enabled, cx)
            }));
        let failed_notifications = Switch::new("notify-failed")
            .small()
            .checked(desktop_behavior.notify_agent_failed)
            .disabled(!desktop_behavior.notifications_enabled)
            .on_click(cx.listener(|this, enabled, _, cx| {
                this.set_notification_kind(NotificationKind::Failed, *enabled, cx)
            }));
        settings_page(
            strings.general,
            strings.general_description,
            vec![
                setting_row(
                    strings.language,
                    strings.language_description,
                    language_select,
                    stacked,
                    cx,
                ),
                setting_row(
                    strings.close_to_tray,
                    strings.close_to_tray_description,
                    close_to_tray_switch,
                    stacked,
                    cx,
                ),
                setting_row(
                    strings.network_proxy,
                    strings.network_proxy_description,
                    proxy_control,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Startup", "启动行为", "啟動行為"),
                    locale::text(
                        "Choose what opens after the local runtime is ready.",
                        "选择本地运行时就绪后的打开内容。",
                        "選擇本機執行階段就緒後要開啟的內容。",
                    ),
                    startup_control,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Launch at login", "开机启动", "登入時啟動"),
                    locale::text(
                        "Start Vibex when you sign in.",
                        "登录系统时启动 Vibex。",
                        "登入系統時啟動 Vibex。",
                    ),
                    launch_at_login,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("System notifications", "系统通知", "系統通知"),
                    locale::text(
                        "Show desktop notifications for Agent activity.",
                        "显示 Agent 活动的桌面通知。",
                        "顯示 Agent 活動的桌面通知。",
                    ),
                    notifications,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Update prompts", "更新提示", "更新提示"),
                    locale::text(
                        "Show the title-bar update button and one-time version notice. Background security checks remain enabled.",
                        "显示标题栏更新按钮和每个版本的一次性提示；后台安全检查始终保持启用。",
                        "顯示標題列更新按鈕與每個版本的一次性提示；背景安全檢查始終保持啟用。",
                    ),
                    update_prompts,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Agent completed", "Agent 完成", "Agent 完成"),
                    locale::text(
                        "Notify when an Agent turn completes.",
                        "Agent 回合完成时通知。",
                        "Agent 回合完成時通知。",
                    ),
                    completed_notifications,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Agent needs input", "Agent 需要输入", "Agent 需要輸入"),
                    locale::text(
                        "Notify when an Agent is waiting for input.",
                        "Agent 等待输入时通知。",
                        "Agent 等待輸入時通知。",
                    ),
                    needs_input_notifications,
                    stacked,
                    cx,
                ),
                setting_row(
                    locale::text("Agent failed", "Agent 失败", "Agent 失敗"),
                    locale::text(
                        "Notify when an Agent turn fails.",
                        "Agent 回合失败时通知。",
                        "Agent 回合失敗時通知。",
                    ),
                    failed_notifications,
                    stacked,
                    cx,
                ),
            ],
            cx,
        )
    }

