    #[test]
    fn session_search_normalizes_queries_and_centers_unicode_excerpts() {
        assert_eq!(
            normalized_session_search_query("  Search \n 会话  "),
            "search 会话"
        );
        let text = format!("{}目标会话内容{}", "前".repeat(120), "后".repeat(120));
        let excerpt = session_search_excerpt(&text, "目标会话内容").expect("query should match");

        assert!(excerpt.starts_with("..."));
        assert!(excerpt.ends_with("..."));
        assert!(excerpt.contains("目标会话内容"));
        assert!(excerpt.chars().count() <= SESSION_SEARCH_EXCERPT_MAX_CHARS + 6);
        assert!(session_search_excerpt(&text, "not present").is_none());
    }

    #[test]
    fn conversation_find_registers_local_search_navigation_and_focus_order() {
        let source = include_str!("app.rs");
        let shortcuts = source
            .split_once("const FOUNDATION_SHORTCUTS")
            .and_then(|(_, tail)| tail.split_once("fn shortcut_action_label"))
            .map(|(body, _)| body)
            .expect("foundation shortcuts should remain inspectable");
        assert!(shortcuts.contains("(\"open_conversation_find\", \"cmd-f\")"));

        let workbench = source
            .split_once(".id(\"vibex-foundation\")")
            .and_then(|(_, tail)| tail.split_once(".on_drag_move("))
            .map(|(body, _)| body)
            .expect("workbench keyboard handlers should remain inspectable");
        assert!(workbench.contains(".capture_key_down("));
        assert!(workbench.contains("modifiers.control || modifiers.platform"));
        assert!(workbench.contains("this.open_conversation_find(window, cx)"));

        let renderer = source
            .split_once("    fn render_conversation_find(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_timeline_turn("))
            .map(|(body, _)| body)
            .expect("conversation find renderer should remain inspectable");
        let input = renderer
            .find("Input::new(&self.conversation_find)")
            .expect("find input should render");
        let previous = renderer
            .find("Button::new(\"conversation-find-previous\")")
            .expect("previous control should render");
        let next = renderer
            .find("Button::new(\"conversation-find-next\")")
            .expect("next control should render");
        let close = renderer
            .find("Button::new(\"conversation-find-close\")")
            .expect("close control should render");
        assert!(input < previous && previous < next && next < close);
        assert!(renderer.contains("self.conversation_find_matches(cx).len()"));

        let highlights = source
            .split_once("    fn session_search_highlight_query_for_rows")
            .and_then(|(_, tail)| tail.split_once("\n    fn session_search_highlighted_row_text"))
            .map(|(body, _)| body)
            .expect("timeline highlighting should remain inspectable");
        assert!(highlights.contains("self.conversation_find_open"));
        assert!(highlights.contains("session_search_match_ranges"));
    }

    #[test]
    fn session_search_match_ranges_highlight_all_case_insensitive_unicode_matches() {
        let text = "Alpha alpha İSTANBUL";
        let matches = session_search_match_ranges(text, "ALPHA")
            .into_iter()
            .map(|range| &text[range])
            .collect::<Vec<_>>();
        assert_eq!(matches, ["Alpha", "alpha"]);

        let unicode_match = session_search_match_ranges(text, "i")
            .into_iter()
            .next()
            .expect("lowercase expansion should map back to the original character");
        assert_eq!(&text[unicode_match], "İ");
    }

    #[test]
    fn session_search_documents_keep_timeline_jump_identity() {
        let session_id = VibexSessionId::parse("session_search").unwrap();
        let user_item_id = TimelineItemId::new();
        let agent_item_id = TimelineItemId::new();
        let timeline_item = |id: TimelineItemId,
                             sequence: i64,
                             timestamp_ms: i64,
                             source: TimelineSource,
                             payload: TimelinePayload| {
            let kind = payload.kind();
            TimelineItem {
                id,
                session_id: session_id.clone(),
                sequence,
                timestamp_ms,
                source,
                kind,
                correlation_id: None,
                provider_correlation_id: None,
                redaction_state: TimelineRedactionState::None,
                execution_attribution: None,
                payload,
            }
        };
        let documents = session_search_documents(&[
            timeline_item(
                user_item_id.clone(),
                7,
                100,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "查找这段用户内容".into(),
                    attachments: Vec::new(),
                }),
            ),
            timeline_item(
                agent_item_id.clone(),
                8,
                120,
                TimelineSource::Agent,
                TimelinePayload::AgentMessage(AgentMessagePayload {
                    text: "这是对应的回答".into(),
                    is_final: true,
                }),
            ),
        ]);

        assert_eq!(documents.len(), 2);
        assert_eq!(documents[0].item_id.as_deref(), Some(user_item_id.as_str()));
        assert_eq!(documents[0].first_sequence, 7);
        assert_eq!(documents[0].timestamp_ms, 100);
        assert!(documents[0].text.contains("查找这段用户内容"));
        assert_eq!(
            documents[1].item_id.as_deref(),
            Some(agent_item_id.as_str())
        );
        assert_eq!(documents[0].turn_id, documents[1].turn_id);
    }

    #[test]
    fn session_search_replaces_sidebar_input_with_modal_navigation() {
        let source = include_str!("app.rs");
        let sidebar = source
            .split_once("    fn render_agent_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_project("))
            .map(|(body, _)| body)
            .expect("sidebar renderer should remain inspectable");
        assert!(!sidebar.contains("Input::new(&self.session_search)"));
        let new_project = sidebar
            .find("Button::new(\"sidebar-new-project\")")
            .expect("new-project action should remain in the project toolbar");
        let search = sidebar
            .find("Button::new(\"sidebar-search-sessions\")")
            .expect("search action should be in the project toolbar");
        assert!(new_project < search);

        let overlay = source
            .split_once("    fn render_session_search_overlay(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_shell("))
            .map(|(body, _)| body)
            .expect("search overlay should remain inspectable");
        assert!(overlay.contains(".absolute()"));
        assert!(overlay.contains(".inset_0()"));
        assert!(overlay.contains("v_virtual_list("));
        assert!(overlay.contains("Self::on_session_search_key_down"));
        assert!(overlay.contains("activate_session_search_selection"));
        assert!(overlay.contains("session_search_highlighted_text"));
        assert!(overlay.contains("agent_brand_icon"));
        assert!(!overlay.contains("count_label"));
        assert!(source.contains(".search_query(search_query)"));
        assert!(source.contains("MarkdownView::new("));

        let workbench_render = source
            .split_once("impl Render for VibexWorkbench")
            .map(|(_, body)| body)
            .expect("workbench renderer should remain inspectable");
        assert!(workbench_render.contains("clear_session_search_highlight"));

        let load = source
            .split_once("    fn load_agent_session_timeline(")
            .and_then(|(_, tail)| tail.split_once("\n    fn refresh_selected_agent_timeline("))
            .map(|(body, _)| body)
            .expect("timeline loader should remain inspectable");
        let jump = load
            .find("this.apply_pending_session_search_jump(cx)")
            .expect("search jump should run after timeline loading");
        let bottom = load
            .find("this.request_timeline_scroll_to_latest()")
            .expect("normal timeline loading should still follow the bottom");
        assert!(jump < bottom);
    }

    #[test]
    fn token_usage_overview_calculates_context_and_cache_independently() {
        let usage = AgentTokenUsage {
            input_tokens: Some(600),
            cached_read_tokens: Some(1_400),
            context_window_used_tokens: Some(50_000),
            context_window_size_tokens: Some(200_000),
            ..AgentTokenUsage::default()
        };

        assert_eq!(context_window_usage_fraction(&usage), Some(0.25));
        assert_eq!(cache_hit_fraction(&usage), Some(0.7));
        assert_eq!(token_usage_percent(0.256), 26);
    }

    #[test]
    fn token_usage_overview_clamps_overflow_and_handles_missing_data() {
        let overflow = AgentTokenUsage {
            context_window_used_tokens: Some(250_000),
            context_window_size_tokens: Some(200_000),
            ..AgentTokenUsage::default()
        };
        assert_eq!(context_window_usage_fraction(&overflow), Some(1.0));
        assert_eq!(cache_hit_fraction(&overflow), None);

        let empty_cache = AgentTokenUsage {
            input_tokens: Some(0),
            cached_read_tokens: Some(0),
            ..AgentTokenUsage::default()
        };
        assert_eq!(cache_hit_fraction(&empty_cache), Some(0.0));
        assert_eq!(format_compact_tokens(999), "999");
        assert_eq!(format_compact_tokens(12_500), "12.5k");
        assert_eq!(format_compact_tokens(2_000_000), "2.0m");
    }

