    #[gpui::test]
    fn composer_queue_visual_contract_draws_at_design_dimensions(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        let queue_width = Rc::new(Cell::new(0.0));
        let header_height = Rc::new(Cell::new(0.0));
        let composer_width = Rc::new(Cell::new(0.0));
        let composer_height = Rc::new(Cell::new(0.0));
        let row_height = Rc::new(Cell::new(0.0));
        let queue_bottom = Rc::new(Cell::new(0.0));
        let composer_top = Rc::new(Cell::new(0.0));
        let observed_queue_width = queue_width.clone();
        let observed_header_height = header_height.clone();
        let observed_composer_width = composer_width.clone();
        let observed_composer_height = composer_height.clone();
        let observed_row_height = row_height.clone();
        let observed_queue_bottom = queue_bottom.clone();
        let observed_composer_top = composer_top.clone();
        let (_, cx) = cx.add_window_view(|window, cx| ComposerLayoutProbe {
            input: cx.new(|cx| {
                InputState::new(window, cx)
                    .auto_grow(2, 8)
                    .submit_on_enter(true)
                    .placeholder("Ask for follow-up changes")
            }),
            queue_width,
            header_height,
            composer_width,
            composer_height,
            row_height,
            queue_bottom,
            composer_top,
        });

        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        // GPUI reports the bordered elements' content boxes. Both surfaces use
        // the same 768px session width contract, with the queue inset by 20px;
        // the two-row InputState raises the composer content box to 116px.
        assert!((observed_queue_width.get() - 726.0).abs() < 0.5);
        assert!(
            (observed_header_height.get() - (COMPOSER_QUEUE_HEADER_HEIGHT - 1.0)).abs() < 0.5,
            "queue header height: {}",
            observed_header_height.get()
        );
        assert!(
            (observed_composer_width.get() - 766.0).abs() < 0.5,
            "composer width: {}",
            observed_composer_width.get()
        );
        assert!(
            (observed_composer_height.get() - 116.0).abs() < 0.5,
            "composer height: {}",
            observed_composer_height.get()
        );
        assert!(
            (observed_row_height.get() - 28.0).abs() < 0.5,
            "row height: {}",
            observed_row_height.get()
        );
        assert!(
            (observed_queue_bottom.get() - observed_composer_top.get()).abs() < 0.5,
            "queue bottom {} should meet composer top {}",
            observed_queue_bottom.get(),
            observed_composer_top.get()
        );
    }

    #[gpui::test]
    fn overflowing_composer_stays_anchored_to_the_workbench_bottom(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        let input_slot = Rc::new(RefCell::new(None));
        let root_bottom = Rc::new(Cell::new(0.0));
        let shell_bottom = Rc::new(Cell::new(0.0));
        let center_bottom = Rc::new(Cell::new(0.0));
        let workbench_bottom = Rc::new(Cell::new(0.0));
        let composer_bottom = Rc::new(Cell::new(0.0));
        let composer_height = Rc::new(Cell::new(0.0));
        let root_bottom_for_view = root_bottom.clone();
        let shell_bottom_for_view = shell_bottom.clone();
        let center_bottom_for_view = center_bottom.clone();
        let workbench_bottom_for_view = workbench_bottom.clone();
        let composer_bottom_for_view = composer_bottom.clone();
        let composer_height_for_view = composer_height.clone();
        let (_, cx) = cx.add_window_view(|window, cx| {
            let input = cx.new(|cx| InputState::new(window, cx).auto_grow(2, 8));
            *input_slot.borrow_mut() = Some(input.clone());
            let probe = cx.new(|_| ComposerBottomAnchorProbe {
                input,
                root_bottom: root_bottom_for_view,
                shell_bottom: shell_bottom_for_view,
                center_bottom: center_bottom_for_view,
                workbench_bottom: workbench_bottom_for_view,
                composer_bottom: composer_bottom_for_view,
                composer_height: composer_height_for_view,
            });
            gpui_component::Root::new(probe, window, cx)
        });
        let input = input_slot
            .borrow()
            .clone()
            .expect("composer input should be created with the probe");

        cx.update(|window, cx| {
            let _ = window.draw(cx);
            window.simulate_next_frame(cx);
            let _ = window.draw(cx);
            window.simulate_next_frame(cx);
            let _ = window.draw(cx);
            window.simulate_next_frame(cx);
            let _ = window.draw(cx);
        });
        let initial_root_bottom = root_bottom.get();
        let initial_composer_bottom = composer_bottom.get();
        let initial_composer_height = composer_height.get();

        cx.update(|window, cx| {
            input.update(cx, |input, cx| {
                let text = (0..24)
                    .map(|line| format!("line {line}"))
                    .collect::<Vec<_>>()
                    .join("\n");
                input.replace(text, window, cx);
            });
            let _ = window.draw(cx);
            window.simulate_next_frame(cx);
            let _ = window.draw(cx);
            window.simulate_next_frame(cx);
            let _ = window.draw(cx);
        });

        assert!(
            (composer_bottom.get() - root_bottom.get()).abs() < 0.5,
            "root={} shell={} center={} workbench={} composer={} initial_root={} initial_composer={}",
            root_bottom.get(),
            shell_bottom.get(),
            center_bottom.get(),
            workbench_bottom.get(),
            composer_bottom.get(),
            initial_root_bottom,
            initial_composer_bottom
        );
        assert!((composer_bottom.get() - shell_bottom.get()).abs() < 0.5);
        assert!((composer_bottom.get() - center_bottom.get()).abs() < 0.5);
        assert!((composer_bottom.get() - workbench_bottom.get()).abs() < 0.5);
        assert!((initial_composer_bottom - initial_root_bottom).abs() < 0.5);
        assert!(
            composer_height.get() > initial_composer_height + 1.0,
            "multiline input should increase composer height: initial={} current={}",
            initial_composer_height,
            composer_height.get()
        );
    }

