    #[test]
    fn sidebar_session_navigation_leaves_management_without_background_navigation() {
        let source = include_str!("app.rs");
        let selection = source
            .split_once("    fn select_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn select_session_with_history("))
            .map(|(body, _)| body)
            .expect("sidebar session navigation should remain inspectable");
        let management_route = selection
            .find("self.sync_current_navigation_entry();")
            .expect("session navigation should preserve the management route");
        let agent_route = selection
            .find("self.ui_state.workbench.active_tab = \"agent\".to_string();")
            .expect("session navigation should restore the agent workbench");
        let session_load = selection
            .find("self.select_session_with_history(session_id, !primary_tab_changed, cx);")
            .expect("session navigation should load the selected session");
        let history_push = selection
            .find("self.push_current_navigation_entry();")
            .expect("session navigation should add the agent route to history");
        assert!(management_route < agent_route);
        assert!(agent_route < session_load);
        assert!(session_load < history_push);

        let events = source
            .split_once("    fn apply_desktop_event(")
            .and_then(|(_, tail)| tail.split_once("\n    fn rebuild_timeline_sizes("))
            .map(|(body, _)| body)
            .expect("desktop event refreshes should remain inspectable");
        assert!(!events.contains("select_session"));
        // Runtime-selection events are scoped by their required session id;
        // only an actual timeline recovery path refreshes the selected session.
        assert_eq!(
            events
                .matches("self.refresh_selected_agent_timeline(cx);")
                .count(),
            1
        );
    }

