    #[test]
    fn agent_brand_assets_match_tauri_identity_priority_and_theme_behavior() {
        assert_eq!(
            agent_brand_asset("OpenCode Gemini"),
            Some(AgentBrandAsset {
                path: "icons/vibex/opencode.svg",
                uses_current_color: false,
            }),
        );
        assert_eq!(
            agent_brand_asset("Google Gemini"),
            Some(AgentBrandAsset {
                path: "icons/vibex/gemini.svg",
                uses_current_color: false,
            }),
        );
        assert_eq!(
            agent_brand_asset("GitHub Copilot"),
            Some(AgentBrandAsset {
                path: "icons/vibex/copilot.svg",
                uses_current_color: true,
            }),
        );
        assert_eq!(
            agent_brand_asset("OpenAI Codex"),
            Some(AgentBrandAsset {
                path: "icons/vibex/openai.svg",
                uses_current_color: true,
            }),
        );
        assert_eq!(agent_brand_asset("custom acp"), None);

        let mut custom = AgentSnapshotEntry::from_definition(
            vibex_core::builtin_agent_definitions().first().unwrap(),
            None,
            None,
        );
        custom.id = AgentId::parse("custom-acp").unwrap();
        custom.label = "Custom Agent".into();
        custom.command = Some(vibex_core::AgentCommandConfig {
            command: "opencode".into(),
            args: Vec::new(),
        });
        custom.params = serde_json::json!({ "preset": "gemini" });
        assert_eq!(
            agent_brand_asset(&agent_brand_identity(&custom)),
            Some(AgentBrandAsset {
                path: "icons/vibex/opencode.svg",
                uses_current_color: false,
            }),
        );

        custom.command = None;
        assert_eq!(
            agent_brand_asset(&agent_brand_identity(&custom)),
            Some(AgentBrandAsset {
                path: "icons/vibex/gemini.svg",
                uses_current_color: false,
            }),
        );
    }

    #[test]
    fn sidebar_session_logo_prefers_the_latest_desired_agent() {
        let persisted = AgentId::parse("codex").unwrap();
        let cached = AgentId::parse("claude").unwrap();
        let selected = AgentId::parse("opencode").unwrap();

        assert_eq!(
            sidebar_session_agent_id(&persisted, Some(&selected), Some(&cached)),
            selected
        );
        assert_eq!(
            sidebar_session_agent_id(&persisted, None, Some(&cached)),
            cached
        );
        assert_eq!(sidebar_session_agent_id(&persisted, None, None), persisted);
    }

    #[test]
    fn sidebar_session_time_uses_local_calendar_days() {
        let at = |day, hour, minute| {
            chrono::NaiveDate::from_ymd_opt(2026, 8, day)
                .unwrap()
                .and_hms_opt(hour, minute, 0)
                .unwrap()
        };
        let now = at(18, 0, 1);

        assert_eq!(
            format_sidebar_session_time_at(
                at(17, 23, 59),
                now,
                locale::ResolvedLocale::ZhCn,
                locale::strings(locale::ResolvedLocale::ZhCn),
            ),
            "昨天"
        );
        assert_eq!(
            format_sidebar_session_time_at(
                at(18, 0, 0),
                now,
                locale::ResolvedLocale::En,
                locale::strings(locale::ResolvedLocale::En),
            ),
            "00:00"
        );
        assert_eq!(
            format_sidebar_session_time_at(
                at(16, 23, 59),
                now,
                locale::ResolvedLocale::En,
                locale::strings(locale::ResolvedLocale::En),
            ),
            "2 days ago"
        );
    }

