    #[test]
    fn overview_refresh_preserves_an_explicit_new_session_navigation() {
        assert!(resolve_initial_new_session_open(
            true,
            false,
            StartupDestination::RestoreWorkbench,
        ));
        assert!(resolve_initial_new_session_open(
            false,
            true,
            StartupDestination::RestoreWorkbench,
        ));
        assert!(resolve_initial_new_session_open(
            false,
            false,
            StartupDestination::NewSession,
        ));
        assert!(!resolve_initial_new_session_open(
            false,
            false,
            StartupDestination::RestoreWorkbench,
        ));

        let source = include_str!("app.rs");
        let overview = source
            .split_once("    fn load_agent_overview(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    pub(crate) fn refresh_workspace_contexts(")
            })
            .map(|(body, _)| body)
            .expect("agent overview should remain inspectable");
        let initial_state = overview
            .find("this.new_session_open = resolve_initial_new_session_open(")
            .expect("initial new-session state should preserve explicit navigation");
        let guarded_selection = overview
            .find("if this.new_session_open {")
            .expect("overview selection should be fenced by the new-session home");
        let session_selection = overview
            .find("this.select_session_with_history(session_id, false, cx);")
            .expect("overview should still select a session when the home is closed");
        assert!(initial_state < guarded_selection);
        assert!(guarded_selection < session_selection);
        assert!(overview.contains("this.finish_startup_loading(cx);"));
    }

    #[test]
    fn composer_queue_reorders_only_within_a_session_and_steer_promotes_the_message() {
        let selection = SessionRuntimeSelection::provider(
            AgentId::parse("agent-queue").unwrap(),
            ProviderProfileId::parse("provider_queue").unwrap(),
            "model-queue",
        );
        let queued = |id, session: &str| ComposerQueueMessage {
            id,
            session_id: VibexSessionId::parse(session).unwrap(),
            desired_runtime: selection.clone(),
            text: format!("message {id}"),
            attachments: Vec::new(),
            command_invocation: None,
        };
        let mut queue = vec![
            queued(1, "session_queue_a"),
            queued(4, "session_queue_b"),
            queued(2, "session_queue_a"),
            queued(3, "session_queue_a"),
        ];

        assert!(reorder_composer_queue_message(&mut queue, 3, 1, false));
        assert_eq!(
            queue
                .iter()
                .filter(|message| message.session_id.as_str() == "session_queue_a")
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            [3, 1, 2]
        );
        assert!(!reorder_composer_queue_message(&mut queue, 1, 4, true));
        assert_eq!(
            promote_composer_queue_message(&mut queue, 2)
                .expect("queued message should be promoted")
                .as_str(),
            "session_queue_a"
        );
        assert_eq!(
            queue
                .iter()
                .filter(|message| message.session_id.as_str() == "session_queue_a")
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            [2, 3, 1]
        );
    }

