    #[test]
    fn new_session_snapshots_keep_the_optimistic_title_until_a_real_title_arrives() {
        let source = include_str!("app.rs");
        let upsert = source
            .split_once("    fn upsert_session_snapshot(")
            .and_then(|(_, tail)| tail.split_once("\n    fn session_turn_pending("))
            .map(|(body, _)| body)
            .expect("session snapshot upsert should remain inspectable");
        assert!(upsert.contains("self.reconcile_pending_new_session_title(session);"));

        let reconcile = source
            .split_once("    fn reconcile_pending_new_session_title(")
            .and_then(|(_, tail)| tail.split_once("\n    fn upsert_session_snapshot("))
            .map(|(body, _)| body)
            .expect("pending-title reconciliation should remain inspectable");
        assert!(reconcile.contains("agent_session_fallback_title(&session.agent_id)"));
        assert!(reconcile.contains("pending_new_session_titles"));
        // The optimistic new-session row is itself a non-fallback snapshot;
        // releasing the recorded title on any non-fallback title would drop
        // the record before the manager's fallback snapshot ever arrives.
        assert!(reconcile.contains("existing.id == session.id"));

        let submit = source
            .split_once("    fn submit_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn choose_runtime_selection("))
            .map(|(body, _)| body)
            .expect("new-session submission should remain inspectable");
        assert!(submit.contains("pending_new_session_titles"));
    }

    #[test]
    fn collapse_all_restores_by_snapshot_even_if_the_collapsed_set_changes() {
        let project_ids = ["workspace-a", "workspace-b"]
            .into_iter()
            .map(str::to_string)
            .collect::<BTreeSet<_>>();
        let mut collapsed_ids = ["workspace-a"]
            .into_iter()
            .map(str::to_string)
            .collect::<BTreeSet<_>>();
        let mut restore_snapshot = None;

        toggle_sidebar_project_collapse_all(
            &mut collapsed_ids,
            &mut restore_snapshot,
            &project_ids,
        );
        assert_eq!(collapsed_ids, project_ids);
        assert_eq!(
            restore_snapshot,
            Some(["workspace-a"].into_iter().map(str::to_string).collect())
        );

        collapsed_ids.remove("workspace-b");
        toggle_sidebar_project_collapse_all(
            &mut collapsed_ids,
            &mut restore_snapshot,
            &project_ids,
        );

        assert_eq!(
            collapsed_ids,
            ["workspace-a"].into_iter().map(str::to_string).collect()
        );
        assert_eq!(restore_snapshot, None);
    }

    #[test]
    fn locating_a_session_reveals_the_required_sidebar_ancestors() {
        let mut collapsed_projects = ["project-a", "project-b"]
            .into_iter()
            .map(str::to_string)
            .collect::<BTreeSet<_>>();
        let mut collapsed_workspaces = ["workspace-a", "workspace-b"]
            .into_iter()
            .map(str::to_string)
            .collect::<BTreeSet<_>>();

        assert!(reveal_sidebar_session(
            &mut collapsed_projects,
            &mut collapsed_workspaces,
            "project-a",
            "workspace-a",
            SidebarHierarchyMode::Compact,
        ));
        assert!(!collapsed_projects.contains("project-a"));
        assert!(collapsed_workspaces.contains("workspace-a"));

        collapsed_projects.insert("project-a".into());
        assert!(reveal_sidebar_session(
            &mut collapsed_projects,
            &mut collapsed_workspaces,
            "project-a",
            "workspace-a",
            SidebarHierarchyMode::Detailed,
        ));
        assert!(!collapsed_projects.contains("project-a"));
        assert!(!collapsed_workspaces.contains("workspace-a"));
        assert!(collapsed_projects.contains("project-b"));
        assert!(collapsed_workspaces.contains("workspace-b"));
    }

