    #[test]
    fn turn_preview_content_uses_the_prompt_result_and_unique_changed_files() {
        let row =
            |id: &str, kind: TimelineRowKind, body: &str, file_path: Option<&str>| TimelineRow {
                id: id.into(),
                kind,
                item_ids: vec![id.into()],
                turn_id: Some("turn:preview".into()),
                turn_item_count: 6,
                turn_failed: false,
                turn_pending_permission: false,
                conclusion: kind == TimelineRowKind::AgentMessage,
                first_sequence: 1,
                last_sequence: 1,
                title: id.into(),
                body: body.into(),
                streaming: false,
                collapsible: false,
                pending_permission: false,
                failed: false,
                runtime_attribution: None,
                file_path: file_path.map(str::to_string),
            };
        let turn = TimelineConversationTurn {
            id: "turn:preview".into(),
            user_row: Some(row(
                "user",
                TimelineRowKind::UserMessage,
                "  Continue\nnow  ",
                None,
            )),
            process_rows: vec![
                row(
                    "file-a",
                    TimelineRowKind::FileOperation,
                    "updated",
                    Some("crates/relay_smoke.rs"),
                ),
                row(
                    "file-b",
                    TimelineRowKind::FileOperation,
                    "updated",
                    Some("src/lib.rs"),
                ),
                row(
                    "file-a-again",
                    TimelineRowKind::FileOperation,
                    "updated",
                    Some("crates/relay_smoke.rs"),
                ),
                row(
                    "file-c",
                    TimelineRowKind::FileOperation,
                    "updated",
                    Some("src/runtime.rs"),
                ),
            ],
            process_activity_groups: Vec::new(),
            process_activity_groups_with_commands: Vec::new(),
            process_activity_groups_with_file_operations: Vec::new(),
            process_activity_groups_with_commands_and_file_operations: Vec::new(),
            live_status: None,
            conclusion_row: Some(row(
                "conclusion",
                TimelineRowKind::AgentMessage,
                "[Relay smoke passed. The rollback regression is fixed.](src/lib.rs)",
                None,
            )),
            runtime_attribution: None,
            complete: true,
            failed: false,
            pending_permission: false,
            item_count: 6,
            started_at_ms: 1,
            ended_at_ms: Some(2),
        };

        let preview = agent_turn_preview_content(&turn, "#1", "Empty message");

        assert_eq!(preview.title, "Continue now");
        assert_eq!(
            preview.message,
            "Relay smoke passed. The rollback regression is fixed."
        );
        assert_eq!(
            preview.file_paths,
            ["crates/relay_smoke.rs", "src/lib.rs", "src/runtime.rs"]
        );
        assert_eq!(
            agent_turn_preview_file_name(&preview.file_paths[0]),
            "relay_smoke.rs"
        );
    }

