    #[test]
    fn user_message_edit_action_is_only_enabled_for_the_latest_completed_turn() {
        assert_eq!(
            user_message_edit_action_state(
                false,
                true,
                false,
                Some(AgentSessionState::Idle),
                false,
            ),
            UserMessageEditActionState::Hidden
        );
        assert_eq!(
            user_message_edit_action_state(true, true, false, Some(AgentSessionState::Idle), false),
            UserMessageEditActionState::Enabled
        );
        for disabled in [
            user_message_edit_action_state(
                true,
                false,
                false,
                Some(AgentSessionState::Idle),
                false,
            ),
            user_message_edit_action_state(true, true, true, Some(AgentSessionState::Idle), false),
            user_message_edit_action_state(
                true,
                true,
                false,
                Some(AgentSessionState::Running),
                false,
            ),
            user_message_edit_action_state(true, true, false, Some(AgentSessionState::Error), true),
        ] {
            assert_eq!(disabled, UserMessageEditActionState::Disabled);
        }
    }

