    #[test]
    fn pending_user_message_edit_replaces_the_user_row_and_hides_the_old_response() {
        let session_id = VibexSessionId::parse("session_pending_edit").unwrap();
        let timeline_item =
            |sequence: i64, timestamp_ms: i64, source: TimelineSource, payload: TimelinePayload| {
                let kind = payload.kind();
                TimelineItem {
                    id: TimelineItemId::new(),
                    session_id: session_id.clone(),
                    sequence,
                    timestamp_ms,
                    source,
                    kind,
                    correlation_id: None,
                    provider_correlation_id: None,
                    redaction_state: TimelineRedactionState::None,
                    execution_attribution: None,
                    payload,
                }
            };
        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(
            session_id.clone(),
            [
                timeline_item(
                    7,
                    10,
                    TimelineSource::User,
                    TimelinePayload::UserMessage(UserMessagePayload {
                        text: "old prompt".into(),
                        attachments: Vec::new(),
                    }),
                ),
                timeline_item(
                    8,
                    11,
                    TimelineSource::Agent,
                    TimelinePayload::AgentMessage(AgentMessagePayload {
                        text: "old response".into(),
                        is_final: true,
                    }),
                ),
            ],
        );
        let attachment = MessageAttachment {
            label: "notes.txt".into(),
            mime_type: Some("text/plain".into()),
            uri: None,
            inline_text_offset: None,
        };
        let pending = PendingUserMessageEdit {
            source_session_id: session_id,
            user_sequence: 7,
            submitted_at_ms: 20,
            text: "edited prompt".into(),
            attachments: vec![attachment.clone()],
        };

        let projected = pending.projected_items(&timeline).unwrap();

        assert_eq!(projected.len(), 1);
        assert_eq!(
            timeline.items.len(),
            2,
            "authoritative timeline stays intact"
        );
        assert_eq!(projected[0].timestamp_ms, 20);
        let TimelinePayload::UserMessage(message) = &projected[0].payload else {
            panic!("projected item should remain a user message");
        };
        assert_eq!(message.text, "edited prompt");
        assert_eq!(message.attachments, vec![attachment]);
        let turns = timeline_conversation_turns(&projected, Some(AgentSessionState::Running), true);
        assert_eq!(turns.len(), 1);
        assert!(!turns[0].complete);
        assert!(turns[0].conclusion_row.is_none());
    }

    #[test]
    fn optimistic_user_message_projects_until_matching_authoritative_row_arrives() {
        let session_id = VibexSessionId::parse("session_optimistic_message").unwrap();
        let attachment = MessageAttachment {
            label: "notes.txt".into(),
            mime_type: Some("text/plain".into()),
            uri: None,
            inline_text_offset: None,
        };
        let optimistic = OptimisticUserMessage {
            session_id: session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence: 1,
            submitted_at_ms: 20,
            text: "  first prompt  ".into(),
            attachments: vec![attachment.clone()],
        };
        let timeline = TimelineModel::default();
        let projected = optimistic.projected_items(&timeline).unwrap();
        assert_eq!(projected.len(), 1);
        assert_eq!(timeline.items.len(), 0);
        assert_eq!(projected[0].sequence, 1);
        let pending_turns =
            timeline_conversation_turns(&projected, Some(AgentSessionState::Running), true);
        assert_eq!(pending_turns.len(), 1);
        assert_eq!(
            pending_turns[0]
                .user_row
                .as_ref()
                .map(|row| row.body.trim()),
            Some("first prompt")
        );
        assert!(!pending_turns[0].complete);
        assert!(pending_turns[0].conclusion_row.is_none());

        let failed_turns =
            timeline_conversation_turns(&projected, Some(AgentSessionState::Error), false);
        assert_eq!(failed_turns.len(), 1);
        assert_eq!(
            failed_turns[0].user_row.as_ref().map(|row| row.body.trim()),
            Some("first prompt"),
            "a terminal send failure must keep the captured user message visible"
        );

        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(
            session_id.clone(),
            [timeline_item_with_payload(
                &session_id,
                2,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "first prompt".into(),
                    attachments: vec![attachment.clone()],
                }),
            )],
        );
        assert!(optimistic.projected_items(&timeline).is_none());
        let authoritative_turns = timeline.conversation_turns(Some(AgentSessionState::Idle), false);
        assert_eq!(authoritative_turns.len(), 1);
        assert_eq!(
            authoritative_turns[0]
                .user_row
                .as_ref()
                .map(|row| row.body.as_str()),
            Some("first prompt")
        );
    }

